INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93049, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "精彩是特别好看，让人想一直看。", "primary_collocate": null, "pronunciation": "jīng cǎi", "ipa": "tɕiŋ tsʰaɪ", "syllable_count": 2, "sentences": [{"text": "这场足球比赛太精彩了，我一直没离开电视。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影很精彩，我想再看一遍。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的故事特别精彩，孩子们都不想睡觉。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的节目真精彩，大家都看得很开心。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说写得很精彩，我一口气看完了。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的球赛精彩极了，最后一分钟还进了球。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧越看越精彩。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一点也不精彩，我看着看着就睡了。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书最精彩的地方在最后一章。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着精彩的动画片，一直笑个不停。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精彩纷呈", "label": "复合"}], "register": "通用", "sense_fingerprint": "特别好看、让人想一直看下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93049, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精彩", "is_correct": true, "explanation": "“精彩”指比赛特别吸引人，与“太……了”和“一直没离开电视”相符。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说的是价钱，不能用来评价一场比赛。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”与足球比赛的热闹相反，也与“一直没离开电视”的投入感矛盾。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写高度，不能用来形容比赛的好坏。"}], "explanations": {"精彩": "“精彩”指比赛特别吸引人，与“太……了”和“一直没离开电视”相符。", "贵": "搭配：“贵”说的是价钱，不能用来评价一场比赛。", "安静": "语义：“安静”与足球比赛的热闹相反，也与“一直没离开电视”的投入感矛盾。", "矮": "体貌：“矮”描写高度，不能用来形容比赛的好坏。"}, "sentence_index": 0, "correct_answer": "精彩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很精彩，我很喜欢。", "explanation": "这里应该用〈好看〉。精彩多用于比赛、节目等让人想一直看的事物，形容衣服的外观要用好看。"}, {"text": "这个苹果很精彩，又甜又脆。", "explanation": "这里应该用〈好吃〉。精彩不用来形容食物的味道，描写苹果好不好吃要用好吃。"}, {"text": "房间今天很精彩，地板擦得很亮。", "explanation": "这里应该用〈干净〉。精彩不用来描写房间的整洁，形容房间要用干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93049, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精彩", "is_correct": true, "explanation": "“精彩”表示电视剧越看越吸引人，与“越看越”的评价相符。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”描写温度，不能用来评价电视剧的好坏。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”描写食物的味道，不能用于电视剧。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”描写人或空间的密集，与“越看越”的评价不合。"}], "explanations": {"精彩": "“精彩”表示电视剧越看越吸引人，与“越看越”的评价相符。", "寒冷": "语义：“寒冷”描写温度，不能用来评价电视剧的好坏。", "好吃": "搭配：“好吃”描写食物的味道，不能用于电视剧。", "拥挤": "语义：“拥挤”描写人或空间的密集，与“越看越”的评价不合。"}, "sentence_index": 6, "correct_answer": "精彩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手的声音很精彩。", "explanation": "这里应该用〈好听〉。精彩用于节目、比赛等，形容声音要用好听。"}, {"text": "这套餐具做得很精彩，我买了一套。", "explanation": "这里应该用〈精美〉。精彩指出色、吸引人，形容器物的做工要用精美。"}, {"text": "这瓶香水很精彩，我很喜欢。", "explanation": "这里应该用〈好闻〉。精彩不用来描写气味，形容香水的气味要用好闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影没精彩，我看了一半就走了。", "corrected_sentence": "这部电影不精彩，我看了一半就走了。", "error_description": "错误：“没精彩”。正确：“不精彩”。“精彩”是形容词，表示性质，否定时要用“不”，不能用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很精彩节目。", "corrected_sentence": "这是一个很精彩的节目。", "error_description": "错误：“很精彩节目”。正确：“很精彩的节目”。“很”修饰形容词后再修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
