INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93050, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表演、展览、言论等优美出色。", "primary_collocate": null, "pronunciation": "jīng cǎi", "ipa": "tɕiŋ tsʰaɪ", "syllable_count": 2, "sentences": [{"text": "他的发言很精彩，大家都鼓掌了。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次演出非常精彩，观众都站起来鼓掌。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个画展很精彩，有很多名画。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的讲话精彩极了，每句都有道理。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈演员的表演十分精彩。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上做了一个精彩的发言。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的音乐会精彩而难忘。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的课讲得很精彩，学生都听得很认真。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家的演讲精彩又有趣。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目里的魔术表演很精彩。", "target_word": "精彩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精彩纷呈", "label": "复合"}], "register": "通用", "sense_fingerprint": "表演、展览、言论等优美出色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精彩", "is_correct": true, "explanation": "“精彩”形容发言出色，与“大家都鼓掌了”相符。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场面没人气，与“大家都鼓掌了”矛盾。"}, {"text": "苦", "is_correct": false, "explanation": "搭配：“苦”描写味道，不能用来形容发言。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”描写味道，不能用来形容发言。"}], "explanations": {"精彩": "“精彩”形容发言出色，与“大家都鼓掌了”相符。", "冷清": "语义：“冷清”形容场面没人气，与“大家都鼓掌了”矛盾。", "苦": "搭配：“苦”描写味道，不能用来形容发言。", "咸": "搭配：“咸”描写味道，不能用来形容发言。"}, "sentence_index": 0, "correct_answer": "精彩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盆花很精彩，颜色很鲜艳。", "explanation": "这里应该用〈漂亮〉。精彩指表演、展览等出色，形容花的外观要用漂亮。"}, {"text": "这块蛋糕很精彩，又香又软。", "explanation": "这里应该用〈好吃〉。精彩不用来描写食物的味道，形容蛋糕要用好吃。"}, {"text": "这间教室很精彩，窗户擦得很亮。", "explanation": "这里应该用〈干净〉。精彩指表演、展览等出色，形容教室的整洁要用干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精彩", "is_correct": true, "explanation": "“精彩”形容音乐会出色，与“而难忘”相配。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”描写物体或天气，与音乐会的体验不合。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”描写质地，不能用来评价音乐会。"}, {"text": "酸", "is_correct": false, "explanation": "搭配：“酸”描写味道，不能用来形容音乐会。"}], "explanations": {"精彩": "“精彩”形容音乐会出色，与“而难忘”相配。", "干燥": "语义：“干燥”描写物体或天气，与音乐会的体验不合。", "硬": "搭配：“硬”描写质地，不能用来评价音乐会。", "酸": "搭配：“酸”描写味道，不能用来形容音乐会。"}, "sentence_index": 6, "correct_answer": "精彩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的嗓音很精彩，大家都很喜欢。", "explanation": "这里应该用〈好听〉。精彩用于表演、展览、言论等，形容嗓音要用好听。"}, {"text": "这把椅子很精彩，我坐了一下午。", "explanation": "这里应该用〈舒服〉。精彩指表演、展览等出色，形容椅子坐着的感觉要用舒服。"}, {"text": "这杯茶很精彩，喝起来很舒服。", "explanation": "这里应该用〈好喝〉。精彩指表演、展览等出色，形容茶的口感要用好喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次表演没精彩，观众都没有鼓掌。", "corrected_sentence": "这次表演不精彩，观众都没有鼓掌。", "error_description": "错误：“没精彩”。正确：“不精彩”。“精彩”是形容词，表示性质，否定时要用“不”，不能用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一场很精彩演出。", "corrected_sentence": "这是一场很精彩的演出。", "error_description": "错误：“很精彩演出”。正确：“很精彩的演出”。“很”修饰形容词后再修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
