INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93051, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "元年是一个新的开始的第一年。", "primary_collocate": null, "pronunciation": "yuán nián", "ipa": "yɥɛn˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "有人说今年是人工智能应用的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司把今年当作自己的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "2015年是共享单车的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市把新机场开通的那年叫作发展元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，明年会是电动汽车普及的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对我来说，退休后的第一年是生活的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把结婚那年看作幸福生活的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年是我们学校开始网上教学的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这一年是手机支付的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策出台后，今年成了环保行动的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某件新事物或新阶段开始的第一年，常说“某某元年”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecaec501-a7ea-4216-b684-7b1fdd95ce2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元年", "is_correct": true, "explanation": "元年：指新阶段开始的第一年，与“今年是……的”所指的时间相符。"}, {"text": "城市", "is_correct": false, "explanation": "语义：“城市”指地方，不指年份，不能与“今年是……的”搭配。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是物件，不能表示一个年份或新阶段。"}, {"text": "寿辰", "is_correct": false, "explanation": "语义：“寿辰”指生日，是一天，不能表示新阶段开始的一年。"}], "explanations": {"元年": "元年：指新阶段开始的第一年，与“今年是……的”所指的时间相符。", "城市": "语义：“城市”指地方，不指年份，不能与“今年是……的”搭配。", "课本": "语义：“课本”是物件，不能表示一个年份或新阶段。", "寿辰": "语义：“寿辰”指生日，是一天，不能表示新阶段开始的一年。"}, "sentence_index": 0, "correct_answer": "元年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司明天开的是元年。", "explanation": "这里应该用〈年会〉。元年指新阶段的第一年，不能指一次聚会。"}, {"text": "昨天我们去了元年，住了一晚。", "explanation": "这里应该用〈酒店〉。元年是纪年时间，不是可以去的地方。"}, {"text": "元年我们要吃一个西瓜。", "explanation": "这里应该用〈夏天〉。元年是纪年时间，不表示季节，句子不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元年", "is_correct": true, "explanation": "元年：新阶段开始的第一年，与“把结婚那年看作幸福生活的”所指相符。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”指某一天，而“那年”指一整年，不能看作生活的开端年。"}, {"text": "戒指", "is_correct": false, "explanation": "语义：“戒指”是首饰，不表示一段时间，不能充当“幸福生活的”所指。"}, {"text": "洞房", "is_correct": false, "explanation": "语义：“洞房”指新婚夫妇的房间，是地方，不是年份。"}], "explanations": {"元年": "元年：新阶段开始的第一年，与“把结婚那年看作幸福生活的”所指相符。", "生日": "语义：“生日”指某一天，而“那年”指一整年，不能看作生活的开端年。", "戒指": "语义：“戒指”是首饰，不表示一段时间，不能充当“幸福生活的”所指。", "洞房": "语义：“洞房”指新婚夫妇的房间，是地方，不是年份。"}, "sentence_index": 6, "correct_answer": "元年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想请你吃一块元年。", "explanation": "这里应该用〈蛋糕〉。元年是纪年词，不是可以吃的东西。"}, {"text": "他元年很大了。", "explanation": "这里应该用〈年纪〉。元年指新阶段的第一年，不能用来说人的年纪。"}, {"text": "我们明天要过元年。", "explanation": "这里不该用“元年”。元年是年份，不是节日；春节说“过年”，不说“过元年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "2018年是外卖平台的第一个元年。", "corrected_sentence": "2018年是外卖平台的元年。", "error_description": "错误：“元年”本身就是第一年，前面再加“第一个”是重复。应直接说“外卖平台的元年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年是我们公司转型的一本元年。", "corrected_sentence": "明年是我们公司转型的元年。", "error_description": "错误：“元年”前加了量词“本”。“本”用于书籍，元年不用这个量词，应直接说“转型的元年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
