INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93052, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "帝王即位或纪年开始的第一年。", "primary_collocate": null, "pronunciation": "yuán nián", "ipa": "yɥɛn˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "新皇帝即位的第一年叫元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉文帝的元年是公元前一百七十九年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唐太宗即位后，第一年叫贞观元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝登上皇位后会定年号，当年叫元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "康熙元年是公元1662年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝即位那一年，古人叫它元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新皇帝换了年号，这一年就是新年号的元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书从太祖元年写到太祖十年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代纪年时，年号开始的那一年称为元年。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "史书中记着，皇帝即位的元年要举行大典。", "target_word": "元年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "古代帝王即位后或新年号开始使用的第一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecaec501-a7ea-4216-b684-7b1fdd95ce2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元年", "is_correct": true, "explanation": "元年：帝王即位后第一年的纪年称呼，与“第一年叫”的语义吻合。"}, {"text": "年号", "is_correct": false, "explanation": "搭配：“年号”是年代的名称，“第一年叫”后接的是年份称呼，不能说“叫年号”。"}, {"text": "陛下", "is_correct": false, "explanation": "语义：“陛下”指人，是对帝王的敬称，不能用来称呼“第一年”。"}, {"text": "太子", "is_correct": false, "explanation": "语义：“太子”指人，是帝位继承人，不能用来称呼“第一年”。"}], "explanations": {"元年": "元年：帝王即位后第一年的纪年称呼，与“第一年叫”的语义吻合。", "年号": "搭配：“年号”是年代的名称，“第一年叫”后接的是年份称呼，不能说“叫年号”。", "陛下": "语义：“陛下”指人，是对帝王的敬称，不能用来称呼“第一年”。", "太子": "语义：“太子”指人，是帝位继承人，不能用来称呼“第一年”。"}, "sentence_index": 0, "correct_answer": "元年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "皇帝退位那一年叫元年。", "explanation": "这里应该用〈末年〉。元年指第一年，退位那年是末年，不能叫元年。"}, {"text": "皇帝去世的那一年就是他的元年。", "explanation": "这里应该用〈末年〉。元年是即位后的第一年，去世那年是末年。"}, {"text": "这位皇帝的元年很长，有十年。", "explanation": "这里应该用〈在位〉。元年只指第一年，不能指在位的整段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元年", "is_correct": true, "explanation": "元年：新年号开始使用的第一年，与“这一年就是新年号的”所指相符。"}, {"text": "诏书", "is_correct": false, "explanation": "语域：“诏书”是公文语体，与叙述句的语境不符，且指文书而非年份。"}, {"text": "皇宫", "is_correct": false, "explanation": "语义：“皇宫”指建筑地点，不能作为年号所对应的年份。"}, {"text": "玉玺", "is_correct": false, "explanation": "语义：“玉玺”指印章，不是时间段，不能表示“新年号的”所指。"}], "explanations": {"元年": "元年：新年号开始使用的第一年，与“这一年就是新年号的”所指相符。", "诏书": "语域：“诏书”是公文语体，与叙述句的语境不符，且指文书而非年份。", "皇宫": "语义：“皇宫”指建筑地点，不能作为年号所对应的年份。", "玉玺": "语义：“玉玺”指印章，不是时间段，不能表示“新年号的”所指。"}, "sentence_index": 6, "correct_answer": "元年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的生日就是皇帝即位的元年。", "explanation": "这里应该用〈即位当日〉。元年指整年，不能指即位的那一天。"}, {"text": "史书里说他的元年是一个人名。", "explanation": "这里被误当作〈名字〉来用。元年是纪年词，不能指人名。"}, {"text": "这本书每个月都改一次元年。", "explanation": "元年是一次纪年的第一年，改元只在换年号时发生，不会每月更换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位皇帝登基后，第一年就元年。", "corrected_sentence": "这位皇帝登基后，第一年就叫元年。", "error_description": "错误：句子缺少谓语动词“叫”，“第一年就元年”不成句。应说“第一年就叫元年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一年是新年号的第一个元年。", "corrected_sentence": "这一年是新年号的元年。", "error_description": "错误：“元年”本身就指第一年，再加“第一个”是重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
