INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93054, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大公司或某些组织的最高负责人。", "primary_collocate": null, "pronunciation": "zǒng cái", "ipa": "tsʊŋ˨˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这家公司的总裁今天要来开会。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三年前当上了公司的总裁。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总裁请大家明天早上九点到会议室。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新总裁很年轻，只有四十岁。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位总裁每年都给学校送书。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的总裁昨天见了几位客人。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是这家大公司的第一位女总裁。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总裁说下个月公司要去北京开会。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看过那位总裁。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总裁把这件事交给了经理。", "target_word": "总裁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副总裁", "label": "复合"}, {"form": "集团总裁", "label": "复合"}], "register": "中性", "sense_fingerprint": "总裁：大公司或组织的最高负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459873f2-15f3-4c94-997f-d7fd10d4860f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生是在学校读书的人，不会是这家公司的负责人，与“这家公司的”不符。"}, {"text": "总裁", "is_correct": true, "explanation": "总裁是大公司的最高负责人，可以来开会，与句子相符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是需要看病的人，不能作为公司的负责人去开会。"}, {"text": "皇帝", "is_correct": false, "explanation": "语域：皇帝是古代君主的称号，不用于现代公司的负责人。"}], "explanations": {"学生": "语义：学生是在学校读书的人，不会是这家公司的负责人，与“这家公司的”不符。", "总裁": "总裁是大公司的最高负责人，可以来开会，与句子相符。", "病人": "语义：病人是需要看病的人，不能作为公司的负责人去开会。", "皇帝": "语域：皇帝是古代君主的称号，不用于现代公司的负责人。"}, "sentence_index": 0, "correct_answer": "总裁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的总裁今天请假了。", "explanation": "这里应该用〈班长〉。总裁指大公司或组织的最高负责人，班级的负责人要说班长。"}, {"text": "这辆公交车的总裁每天早上开车。", "explanation": "这里应该用〈司机〉。总裁指大公司或组织的最高负责人，开车的人要说司机。"}, {"text": "我爸爸是一家小饭馆的总裁。", "explanation": "这里应该用〈老板〉。总裁只用于大公司或组织的最高负责人，小饭馆的负责人要说老板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演员", "is_correct": false, "explanation": "语义：演员在剧场或片场工作，不是大公司的最高负责人。"}, {"text": "总裁", "is_correct": true, "explanation": "总裁指大公司的最高负责人，与「大公司」和「第一位女」相合。"}, {"text": "酋长", "is_correct": false, "explanation": "语义：酋长是部落的首领，不是现代大公司的负责人。"}, {"text": "校长", "is_correct": false, "explanation": "语义：校长是学校的负责人，不是大公司的最高负责人。"}], "explanations": {"演员": "语义：演员在剧场或片场工作，不是大公司的最高负责人。", "总裁": "总裁指大公司的最高负责人，与「大公司」和「第一位女」相合。", "酋长": "语义：酋长是部落的首领，不是现代大公司的负责人。", "校长": "语义：校长是学校的负责人，不是大公司的最高负责人。"}, "sentence_index": 6, "correct_answer": "总裁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这艘船的总裁今天要靠岸。", "explanation": "这里应该用〈船长〉。总裁是大公司的最高负责人，船上的负责人要说船长。"}, {"text": "我们班的总裁每周给大家讲课。", "explanation": "这里应该用〈班主任〉。总裁只用于大公司或组织的最高负责人，班级的负责人要说班主任。"}, {"text": "我们篮球队的总裁每天训练我们。", "explanation": "这里应该用〈教练〉。总裁是大公司的最高负责人，训练球队的人要说教练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只总裁正在会议室等你。", "corrected_sentence": "一位总裁正在会议室等你。", "error_description": "量词错误：总裁是人，应该用「位」，「只」用于动物。错误句中的「一只」应改为「一位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是这家大公司的一条总裁。", "corrected_sentence": "她是这家大公司的一位总裁。", "error_description": "量词错误：「条」用于细长的东西，指人的总裁要用「位」，错误句中的「一条」应改为「一位」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
