INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93055, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93055, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "入学是第一次去学校读书。", "primary_collocate": null, "pronunciation": "rù xué", "ipa": "ʐu˥˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "明天是小雨入学的第一天。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子到了七岁就该入学了。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "入学那天，他背着新书包。", "target_word": "入学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子要入学了，妈妈很高兴。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他六岁才入学读书。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说入学以前要先报名。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她入学前一直在家，没去过学校。", "target_word": "入学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "入学前一天，爸爸带我去学校报名，我有点怕。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的孩子也能入学了。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "入学以后，我每天都学新字。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "入学了", "label": "体标"}, {"form": "入学年龄", "label": "复合"}, {"form": "入學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "第一次去学校读书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93055, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入学", "is_correct": true, "explanation": "入学指第一次进入学校，符合“第一天”的句意。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：“下班”指结束工作离开单位，不能说“下班的第一天”。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽是植物的事，与“小雨”不符。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”的主语一般是花或植物，不能说“小雨开花”。"}], "explanations": {"入学": "入学指第一次进入学校，符合“第一天”的句意。", "下班": "搭配：“下班”指结束工作离开单位，不能说“下班的第一天”。", "发芽": "语义：发芽是植物的事，与“小雨”不符。", "开花": "搭配：“开花”的主语一般是花或植物，不能说“小雨开花”。"}, "sentence_index": 0, "correct_answer": "入学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹每天骑车入学。", "explanation": "这里应该用〈上学〉。入学指第一次进入学校，只发生一次，不能说“每天入学”。"}, {"text": "妈妈因为腿伤，前天去医院入学了。", "explanation": "这里应该用〈住院〉。入学指进入学校，不能用于医院。"}, {"text": "妹妹入学了重点中学。", "explanation": "这里应该用〈考入〉。入学是不及物动词，不能带“重点中学”作宾语，应说“考入重点中学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93055, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入学", "is_correct": true, "explanation": "入学指进入学校读书，与“没去过学校”相对应。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生前一直在家”没有读书的语境，与句中“没去过学校”不相关。"}, {"text": "冬眠", "is_correct": false, "explanation": "搭配：“冬眠”是动物的习性，不能用于“她”。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨与人的读书经历无关，不能说“下雨前一直在家”。"}], "explanations": {"入学": "入学指进入学校读书，与“没去过学校”相对应。", "出生": "语义：“出生前一直在家”没有读书的语境，与句中“没去过学校”不相关。", "冬眠": "搭配：“冬眠”是动物的习性，不能用于“她”。", "下雨": "语义：下雨与人的读书经历无关，不能说“下雨前一直在家”。"}, "sentence_index": 6, "correct_answer": "入学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暑假结束了，学校明天又要入学了。", "explanation": "这里应该用〈开学〉。入学指个人第一次进入学校，学校假期后开始上课应说“开学”。"}, {"text": "这家公司今年入学了很多新员工。", "explanation": "这里应该用〈入职〉。入学指进入学校成为学生，员工进入公司应说“入职”。"}, {"text": "游客一大早就入学了，园里很热闹。", "explanation": "这里应该用〈入园〉。入学指进入学校，游客进公园要说“入园”，不说“入学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我女儿明年就要入学校了。", "corrected_sentence": "我女儿明年就要入学了。", "error_description": "多了宾语“学校”。“入学”本身已含“进入学校”的意思，不能再加“学校”，应说“入学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被入学以后很快就交到了朋友。", "corrected_sentence": "他入学以后很快就交到了朋友。", "error_description": "“入学”是不及物动词，不能用“被”字句。应说“他入学以后很快就交到了朋友”，不说“被入学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
