INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93056, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进入学校成为学生。", "primary_collocate": null, "pronunciation": "rù xué", "ipa": "ʐu˥˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "我弟弟今年九月入学。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她六岁时就入学了。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子入学以前要先体检。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新生入学那天，校门口很热闹。", "target_word": "入学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明已经入学一个月了。", "target_word": "入学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所学校今年有三百个新生入学。", "target_word": "入学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为生病，晚了一年入学。", "target_word": "入学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "入学时，我还不认识几个字。", "target_word": "入学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈陪着女儿去报名，准备入学。", "target_word": "入学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥去年入学，现在上二年级了。", "target_word": "入学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "入学了", "label": "体标"}, {"form": "入学率", "label": "复合"}, {"form": "入學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "进入学校，成为那里的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入学", "is_correct": true, "explanation": "入学指进入学校读书，与句中“弟弟”“九月”相符。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽是植物的事，不能用来说人。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”的主语一般是植物，不能说“弟弟开花”。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，与“弟弟”无关。"}], "explanations": {"入学": "入学指进入学校读书，与句中“弟弟”“九月”相符。", "发芽": "语义：发芽是植物的事，不能用来说人。", "开花": "搭配：“开花”的主语一般是植物，不能说“弟弟开花”。", "下雨": "语义：下雨是天气现象，与“弟弟”无关。"}, "sentence_index": 0, "correct_answer": "入学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天七点入学。", "explanation": "这里应该用〈上学〉。入学指第一次进入学校，只发生一次，不能说“每天入学”。"}, {"text": "我下个月去医院入学。", "explanation": "这里应该用〈住院〉。入学指进入学校，不能用于医院。"}, {"text": "寒假过完了，学校下周一又入学。", "explanation": "这里应该用〈开学〉。入学指个人第一次进入学校，学校假期后开始上课应说“开学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入学", "is_correct": true, "explanation": "入学指进入学校，符合“晚了一年”的句意。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生是人一生只有一次的开始，不能因生病而“晚了一年”出生。"}, {"text": "下班", "is_correct": false, "explanation": "语义：下班是每天的事，不能说“晚了一年下班”。"}, {"text": "出嫁", "is_correct": false, "explanation": "搭配：“出嫁”指女子结婚离家，不能用于“他”。"}], "explanations": {"入学": "入学指进入学校，符合“晚了一年”的句意。", "出生": "语义：出生是人一生只有一次的开始，不能因生病而“晚了一年”出生。", "下班": "语义：下班是每天的事，不能说“晚了一年下班”。", "出嫁": "搭配：“出嫁”指女子结婚离家，不能用于“他”。"}, "sentence_index": 6, "correct_answer": "入学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "观众陆续入学，场内很热闹。", "explanation": "这里应该用〈入场〉。入学指进入学校成为学生，观众进场不能说“入学”。"}, {"text": "这家医院今年入学了一千个病人。", "explanation": "这里应该用〈入院〉。入学只指学生进入学校，病人进入医院应说“入院”。"}, {"text": "他去年入学了大学。", "explanation": "这里应该用〈考上〉。入学不能直接带“大学”作宾语，应说“考上大学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我侄子明年要入学校了。", "corrected_sentence": "我侄子明年要入学了。", "error_description": "多了宾语“学校”。“入学”本身已含“进入学校”的意思，不能再加“学校”，应说“入学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我女儿后年才能被入学。", "corrected_sentence": "我女儿后年才能入学。", "error_description": "“入学”是不及物动词，不能用“被”字句。应说“后年才能入学”，不说“被入学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
