INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93058, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彼此取得联系，保持往来。", "primary_collocate": null, "pronunciation": "lián luò", "ipa": "ljɛn˧˥ lwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "毕业以后，我们还常常联络。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人很少联络。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间要多联络。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我跟老同学不再联络了。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用手机保持联络。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，我和她一直有联络。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国后，他跟家里常有联络。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然在不同的城市，我们还是互相联络。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们好久没联络了，她过得好吗？", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们约好每个月联络一次。", "target_word": "联络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "联络了", "label": "完成体"}, {"form": "联络过", "label": "经历体"}, {"form": "联络联络", "label": "重叠"}, {"form": "联络员", "label": "复合词"}], "register": "中性", "sense_fingerprint": "双方互相联系，长期保持往来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459873f2-15f3-4c94-997f-d7fd10d4860f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下雪", "is_correct": false, "explanation": "语义：「下雪」是天气，主语不能是「我们」。"}, {"text": "联络", "is_correct": true, "explanation": "联络：彼此取得联系，保持往来，与句子语境相符。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：「冻结」用于账户或物体，不用于人与人之间的往来。"}, {"text": "开花", "is_correct": false, "explanation": "语义：「开花」说的是植物，人不能开花。"}], "explanations": {"下雪": "语义：「下雪」是天气，主语不能是「我们」。", "联络": "联络：彼此取得联系，保持往来，与句子语境相符。", "冻结": "搭配：「冻结」用于账户或物体，不用于人与人之间的往来。", "开花": "语义：「开花」说的是植物，人不能开花。"}, "sentence_index": 0, "correct_answer": "联络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教授每天都在实验室联络这个问题。", "explanation": "这里应该用〈研究〉。联络指和人取得联系，对问题要说研究。"}, {"text": "我们要联络健康的生活习惯。", "explanation": "这里应该用〈保持〉。联络不能和习惯搭配，健康的生活习惯要说保持。"}, {"text": "妈妈每天在厨房联络晚饭。", "explanation": "这里应该用〈做〉。联络指彼此取得联系，做晚饭要说做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食物", "is_correct": false, "explanation": "语义：食物不是人与人之间的往来，「跟家里常有食物」说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「有」后接「颜色」不能表示与家里的往来，搭配不当。"}, {"text": "联络", "is_correct": true, "explanation": "联络：彼此取得联系，保持往来，与「出国后」和「跟家里」的语境相符。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡是照明的物品，与「跟家里常有」的往来不符。"}], "explanations": {"食物": "语义：食物不是人与人之间的往来，「跟家里常有食物」说不通。", "颜色": "搭配：「有」后接「颜色」不能表示与家里的往来，搭配不当。", "联络": "联络：彼此取得联系，保持往来，与「出国后」和「跟家里」的语境相符。", "灯泡": "语义：灯泡是照明的物品，与「跟家里常有」的往来不符。"}, "sentence_index": 6, "correct_answer": "联络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上联络教室。", "explanation": "这里应该用〈打扫〉。联络的对象是人，教室要说打扫。"}, {"text": "我想联络一下价格。", "explanation": "这里应该用〈询问〉。联络表示和人取得联系，问价格要说询问。"}, {"text": "老师在黑板上联络这道题。", "explanation": "这里应该用〈讲解〉。联络的对象是人，讲解题目要说讲解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年我们每年只有一头联络。", "corrected_sentence": "这几年我们每年只有一次联络。", "error_description": "量词错误：「头」用于牲畜，「联络」计次应当用「次」，错误句中的「一头」应改为「一次」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们每个月都互相联络一只。", "corrected_sentence": "同学们每个月都互相联络一次。", "error_description": "量词错误：「只」用于动物或成对物品中的一件，「联络」计次应当用「次」，错误句中的「一只」应改为「一次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
