INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93061, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "公尺是量长度的一个单位，就是一米。", "primary_collocate": null, "pronunciation": "gōng chǐ", "ipa": "kʊŋ⁵⁵ ʈʂʰɻ̩²¹⁴", "syllable_count": 2, "sentences": [{"text": "学校的操场长一百公尺。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑了一百公尺，只用了十三秒。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请往前走五十公尺，就到车站了。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河有二十公尺宽。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那棵树高十公尺。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校只有三百公尺。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的桌子长两公尺。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池一共五十公尺长。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面两百公尺有一家银行。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跳远跳了四公尺多。", "target_word": "公尺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方公尺", "label": "复合词"}, {"form": "立方公尺", "label": "复合词"}], "register": "中性", "sense_fingerprint": "量长度的单位，一公尺就是一米", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088928fc-a436-497e-8711-79f5a28a97a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93061, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厘米", "is_correct": false, "explanation": "语义：一百厘米只有一米，与操场的实际长度不符。"}, {"text": "公尺", "is_correct": true, "explanation": "正确：公尺是长度单位，与“长一百”搭配，指操场的长度。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“个”是个体量词，不用于长度，“长一百个”不成立。"}, {"text": "公里", "is_correct": false, "explanation": "语义：一百公里是很长的距离，不适用于一个操场的长度。"}], "explanations": {"厘米": "语义：一百厘米只有一米，与操场的实际长度不符。", "公尺": "正确：公尺是长度单位，与“长一百”搭配，指操场的长度。", "个": "搭配：“个”是个体量词，不用于长度，“长一百个”不成立。", "公里": "语义：一百公里是很长的距离，不适用于一个操场的长度。"}, "sentence_index": 0, "correct_answer": "公尺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室的面积有六十公尺。", "explanation": "这里应该用〈平方公尺〉。面积要按平方计量，公尺只用于长度。"}, {"text": "我买了三公尺牛奶。", "explanation": "这里应该用〈升〉。牛奶是液体，按体积计量要用升，公尺只用于长度。"}, {"text": "这袋大米重了五公尺。", "explanation": "这里应该用〈公斤〉。大米按重量计量要用公斤，公尺只用于长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93061, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亩", "is_correct": false, "explanation": "搭配：“亩”是面积单位，不能用来表示桌子的长度。"}, {"text": "公尺", "is_correct": true, "explanation": "正确：公尺是长度单位，与“长两”搭配，指桌子的长度。"}, {"text": "里", "is_correct": false, "explanation": "语义：两里约等于一公里，远超一张桌子的长度。"}, {"text": "平方米", "is_correct": false, "explanation": "搭配：“平方米”是面积单位，不能与“长”搭配。"}], "explanations": {"亩": "搭配：“亩”是面积单位，不能用来表示桌子的长度。", "公尺": "正确：公尺是长度单位，与“长两”搭配，指桌子的长度。", "里": "语义：两里约等于一公里，远超一张桌子的长度。", "平方米": "搭配：“平方米”是面积单位，不能与“长”搭配。"}, "sentence_index": 6, "correct_answer": "公尺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个水池的容积有两百公尺。", "explanation": "这里应该用〈立方公尺〉。容积是立体空间的体积，要用立方公尺，公尺只用于长度。"}, {"text": "我加了十公尺汽油。", "explanation": "这里应该用〈升〉。汽油按体积计量，要说升，公尺只用于长度。"}, {"text": "这箱苹果重了八公尺。", "explanation": "这里应该用〈公斤〉。苹果按重量计量，要说公斤，公尺只用于长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93061, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥长一百个公尺。", "corrected_sentence": "这座桥长一百公尺。", "error_description": "错误在于“个”。“个”不能放在数词和“公尺”之间。应说“这座桥长一百公尺”，不说“这座桥长一百个公尺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93061, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站离这儿五百公尺长。", "corrected_sentence": "车站离这儿五百公尺远。", "error_description": "错误在于“长”。“离……远”表示距离，要用“远”；“长”用于物体的长度，不能描述两地之间的距离。应说“离这儿五百公尺远”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
