INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93063, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93063, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "举是用手把东西往上拿起来。", "primary_collocate": null, "pronunciation": "jǔ", "ipa": "tɕy˨˩˦", "syllable_count": 1, "sentences": [{"text": "他举着一面红旗走在前面。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家把手举高，再回答问题。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把书包举过了头顶。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能用一只手举这个箱子吗？", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子举着小手，想问老师问题。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她累得连杯子都举不起来了。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他双手举着一个大西瓜。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同意这个方案的同学，请把手举起来。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把孩子举得高高的，让他看烟花。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一口气举了五十下杠铃。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "举了", "label": "完成体"}, {"form": "举着", "label": "持续体"}, {"form": "举过", "label": "经历体"}, {"form": "举起", "label": "复合词"}, {"form": "舉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手把东西或手臂往上拿起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93063, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举", "is_correct": true, "explanation": "正确：举指用手把东西往上拿起，与“红旗”“走在前面”的动作相符。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推”是向前用力使物体移动，与“着一面红旗”的手持动作不符。"}, {"text": "剪", "is_correct": false, "explanation": "语义：“剪”是用剪刀断开，与手持红旗走在前面的动作不符。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开、拆卸，与“红旗”搭配不通，句子读不通。"}], "explanations": {"举": "正确：举指用手把东西往上拿起，与“红旗”“走在前面”的动作相符。", "推": "语义：“推”是向前用力使物体移动，与“着一面红旗”的手持动作不符。", "剪": "语义：“剪”是用剪刀断开，与手持红旗走在前面的动作不符。", "拆": "语义：“拆”是拆开、拆卸，与“红旗”搭配不通，句子读不通。"}, "sentence_index": 0, "correct_answer": "举"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把箱子举在桌子上放好。", "explanation": "这里应该用〈搬〉。举强调把东西向上拿起，把箱子放到桌上要用搬。"}, {"text": "大家举他当班长。", "explanation": "这里的“举”是推举、推选的意思，指大家选出某人担任职务，与本义“用手把东西往上拿起来”无关。"}, {"text": "他的脾气很大，经常举别人。", "explanation": "这里应该用〈批评〉。举只指用手往上拿起，不能用来指责别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举", "is_correct": true, "explanation": "正确：举指用手托起东西，与“双手”“大西瓜”相符。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是用脚压，与“双手”托着西瓜的动作不符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿，与“双手”的动作不符。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚，与“双手”的动作不符。"}], "explanations": {"举": "正确：举指用手托起东西，与“双手”“大西瓜”相符。", "踩": "语义：“踩”是用脚压，与“双手”托着西瓜的动作不符。", "咬": "语义：“咬”是用牙齿，与“双手”的动作不符。", "踢": "语义：“踢”是用脚，与“双手”的动作不符。"}, "sentence_index": 6, "correct_answer": "举"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师又举了几个例子。", "explanation": "这里的“举”是列举、举例的意思，指一一说出来，与本义“用手把东西往上拿起来”无关。"}, {"text": "他举家搬到了北京。", "explanation": "这里的“举”是全、整个的意思，指一家人全部，与本义“用手把东西往上拿起来”无关。"}, {"text": "他一口气举了五十个问题。", "explanation": "这里应该用〈提出〉。举指用手往上拿起，不能用来指抛出问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他举着红旗着走在前面。", "corrected_sentence": "他举着红旗走在前面。", "error_description": "错误形式：“举着红旗着”；正确形式：“举着红旗”。“着”只能出现一次，紧跟动词“举”表示持续，宾语后多出的“着”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她双手举起一个相框起，站在门口。", "corrected_sentence": "她双手举起一个相框，站在门口。", "error_description": "错误形式：“举起一个相框起”；正确形式：“举起一个相框”。结果补语“起”只能出现一次，紧跟动词“举”，宾语后多出的“起”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
