INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向上托；往上抬起。", "primary_collocate": null, "pronunciation": "jǔ", "ipa": "tɕy˨˩˦", "syllable_count": 1, "sentences": [{"text": "大家举起杯，一起祝他生日快乐。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举枪对准了前面的目标。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她举起手机，拍下了天上的月亮。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员举着奖杯，笑得很开心。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把女儿举到肩膀上。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举着伞，在雨里等了很久。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们举着手里的小旗欢迎客人。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察大声说：“把手举起来！”", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举着相机，站在人群后面拍照。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们一起举起了那块大石头。", "target_word": "举", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "举了", "label": "完成体"}, {"form": "举着", "label": "持续体"}, {"form": "举过", "label": "经历体"}, {"form": "举起", "label": "复合词"}, {"form": "舉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "向上托起、抬起（杯、枪、伞、头等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677d3bb3-2de6-472d-8d37-0d9bf6e69e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举", "is_correct": true, "explanation": "正确：举指向上托起，与“杯”“祝他生日快乐”的动作相符。"}, {"text": "碰", "is_correct": false, "explanation": "语义：“碰”是接触、撞击，与“起杯”的托起动作不同。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推”是用力使物体移动，与敬酒时向上举杯的动作不符。"}, {"text": "放", "is_correct": false, "explanation": "语义：“放”是把东西搁下，与“祝他生日快乐”时的举杯动作相反。"}], "explanations": {"举": "正确：举指向上托起，与“杯”“祝他生日快乐”的动作相符。", "碰": "语义：“碰”是接触、撞击，与“起杯”的托起动作不同。", "推": "语义：“推”是用力使物体移动，与敬酒时向上举杯的动作不符。", "放": "语义：“放”是把东西搁下，与“祝他生日快乐”时的举杯动作相反。"}, "sentence_index": 0, "correct_answer": "举"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全班同学举他当班长。", "explanation": "这里的“举”是推举、推选的意思，指大家选出某人担任职务，与本义“向上托；往上抬起”无关。"}, {"text": "他举家迁到了上海。", "explanation": "这里的“举”是全、整个的意思，指一家人全部，与本义“向上托；往上抬起”无关。"}, {"text": "他举了很多理由说明自己没错。", "explanation": "这里的“举”是列举的意思，指一一说出来，与本义“向上托；往上抬起”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举", "is_correct": true, "explanation": "正确：举指用手往上拿起，与“着小旗”“欢迎客人”的动作相符。"}, {"text": "卷", "is_correct": false, "explanation": "语义：“卷”是把东西弯曲成筒，与“着小旗欢迎”的展示动作不合。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是扯裂，与欢迎客人时展示小旗的动作相反。"}, {"text": "藏", "is_correct": false, "explanation": "语义：“藏”是隐藏，与“欢迎客人”的公开展示相反。"}], "explanations": {"举": "正确：举指用手往上拿起，与“着小旗”“欢迎客人”的动作相符。", "卷": "语义：“卷”是把东西弯曲成筒，与“着小旗欢迎”的展示动作不合。", "撕": "语义：“撕”是扯裂，与欢迎客人时展示小旗的动作相反。", "藏": "语义：“藏”是隐藏，与“欢迎客人”的公开展示相反。"}, "sentence_index": 6, "correct_answer": "举"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师举了三个例子，帮大家理解。", "explanation": "这里的“举”是列举、举例的意思，指一一说出来，与本义“向上托；往上抬起”无关。"}, {"text": "大家一致举他当代表。", "explanation": "这里的“举”是推举、推选的意思，指选出某人担任职务，与本义“向上托；往上抬起”无关。"}, {"text": "他们举家搬到了南方。", "explanation": "这里的“举”是全、整个的意思，指一家人全部，与本义“向上托；往上抬起”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小女孩举着一朵红花着，笑着跑过来。", "corrected_sentence": "小女孩举着一朵红花，笑着跑过来。", "error_description": "错误形式：“举着一朵红花着”；正确形式：“举着一朵红花”。“着”只能出现一次，紧跟动词“举”表示持续，宾语后多出的“着”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她举了起一面旗，笑着走了过来。", "corrected_sentence": "她举起了一面旗，笑着走了过来。", "error_description": "错误形式：“举了起”；正确形式：“举起了”。结果补语“起”须紧跟动词“举”，“了”放在“举起”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fad2deb-cd75-4679-8a8b-6890cacad058') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
