INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93065, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "分外是比平常更加。", "primary_collocate": null, "pronunciation": "fèn wài", "ipa": "fən⁵¹ wai⁵¹", "syllable_count": 2, "sentences": [{"text": "下雪以后，天空看起来分外干净。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛那天，他分外紧张。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前一天，图书馆里分外安静。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的饭，今天吃起来分外香。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人在外面过节，心里分外难受。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，公园里的花开得分外好看。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们过生日，笑得分外开心。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打完球，冰水喝起来分外舒服。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来以后，海边的颜色分外漂亮。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了这个好消息，大家分外激动。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：比平常更加，说明某种情况下感受或状态格外明显", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分外", "is_correct": true, "explanation": "正确：“天空看起来分外干净”表示比平常更加干净。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示急忙，不能修饰“看起来……干净”。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“看起来干净”的状态描述不合。"}, {"text": "恰好", "is_correct": false, "explanation": "搭配：“恰好”表示碰巧，不能修饰“看起来……干净”。"}], "explanations": {"分外": "正确：“天空看起来分外干净”表示比平常更加干净。", "赶紧": "搭配：“赶紧”表示急忙，不能修饰“看起来……干净”。", "偶尔": "语义：“偶尔”表示不常发生，与“看起来干净”的状态描述不合。", "恰好": "搭配：“恰好”表示碰巧，不能修饰“看起来……干净”。"}, "sentence_index": 0, "correct_answer": "分外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师分外地讲解题目，让大家都听懂了。", "explanation": "这里应该用〈耐心〉。“分外”只修饰形容词或心理动词，不修饰“讲解”这类动作。"}, {"text": "他分外地打开盒子，怕弄坏里面的东西。", "explanation": "这里应该用〈小心〉。“分外”只修饰形容词或心理动词，不修饰“打开”这类动作。"}, {"text": "妈妈分外地洗碗，每天都不偷懒。", "explanation": "这里应该用〈认真〉。“分外”只修饰形容词或心理动词，不修饰“洗碗”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分外", "is_correct": true, "explanation": "正确：“笑得分外开心”表示比平常更加开心。"}, {"text": "慢慢", "is_correct": false, "explanation": "搭配：“慢慢”表示速度，不能作程度补语修饰“开心”。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，与过生日时持续的笑不合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与过生日当下的笑不合。"}], "explanations": {"分外": "正确：“笑得分外开心”表示比平常更加开心。", "慢慢": "搭配：“慢慢”表示速度，不能作程度补语修饰“开心”。", "忽然": "语义：“忽然”表示突然，与过生日时持续的笑不合。", "曾经": "语义：“曾经”指过去，与过生日当下的笑不合。"}, "sentence_index": 6, "correct_answer": "分外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他分外把门关上了。", "explanation": "这里应该用〈随手〉。“分外”只修饰形容词或心理动词，不修饰“关门”这类动作；顺手做某事要用〈随手〉。"}, {"text": "这两份文件要分外保存，不能放在一起。", "explanation": "这里应该用〈分开〉。“分外”表示比平常更加，不能表示“分别”；分别保存要用〈分开〉。"}, {"text": "他分外为朋友准备了生日礼物。", "explanation": "这里应该用〈特意〉。“分外”只修饰形容词或心理动词，不修饰“准备”这类动作；专门为某事做要用〈特意〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风停以后，湖面分外奔跑。", "corrected_sentence": "风停以后，湖面分外平静。", "error_description": "用词错误：“分外”修饰的应是状态形容词，不能修饰“奔跑”这类动作，应改为“分外平静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们听到消息，很分外兴奋。", "corrected_sentence": "孩子们听到消息，分外兴奋。", "error_description": "“分外”本身已表示程度，前面又加“很”，属于重复，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
