INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93066, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "格外；特别地。", "primary_collocate": null, "pronunciation": "fèn wài", "ipa": "fən⁵¹ wai⁵¹", "syllable_count": 2, "sentences": [{"text": "过年的时候，街上分外热闹。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天晚上的月亮分外明亮。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离家很远，我在节日里分外想家。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下过雨以后，空气分外新鲜。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老朋友，他分外高兴。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的山上分外安静，一点声音也没有。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败以后，她练得分外努力。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都走了，房间里分外冷清。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在外国生活，我分外珍惜和家人在一起的时间。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪后的早晨，阳光分外刺眼。", "target_word": "分外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：格外、特别，用在形容词或心理动词前，程度比一般情况高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分外", "is_correct": true, "explanation": "正确：“分外热闹”表示格外热闹，修饰形容词。"}, {"text": "分别", "is_correct": false, "explanation": "搭配：“分别”表示各自、分开，不能修饰“热闹”。"}, {"text": "连", "is_correct": false, "explanation": "搭配：“连”要与“都”“也”配合，“街上连热闹”不成立。"}, {"text": "并", "is_correct": false, "explanation": "搭配：“并”多用于否定句，“街上并热闹”不成立。"}], "explanations": {"分外": "正确：“分外热闹”表示格外热闹，修饰形容词。", "分别": "搭配：“分别”表示各自、分开，不能修饰“热闹”。", "连": "搭配：“连”要与“都”“也”配合，“街上连热闹”不成立。", "并": "搭配：“并”多用于否定句，“街上并热闹”不成立。"}, "sentence_index": 0, "correct_answer": "分外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两批货要分外存放，不能放在一起。", "explanation": "这里应该用〈分开〉。“分外”是程度副词，表示格外、特别，不能表示“分别”；分别存放要用〈分开〉。"}, {"text": "他分外去图书馆，每周都去一次。", "explanation": "这里应该用〈经常〉。“分外”表示格外、特别，不能修饰“去”这类动作，也不表示次数；表示经常去要用〈经常〉。"}, {"text": "他分外地坐在门口，等了很久。", "explanation": "这里应该用〈一直〉。“分外”只修饰形容词或心理动词，不修饰“坐”这类动作；表示持续地坐要用〈一直〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分外", "is_correct": true, "explanation": "正确：“练得分外努力”表示努力的程度比平常高。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”强调一直，与“失败以后”的转折语境不合。"}, {"text": "最后", "is_correct": false, "explanation": "语义：“最后”表示结局，不能表示努力的程度。"}, {"text": "恰好", "is_correct": false, "explanation": "搭配：“恰好”表示碰巧，不能放在“练得……努力”的程度补语位置。"}], "explanations": {"分外": "正确：“练得分外努力”表示努力的程度比平常高。", "始终": "语义：“始终”强调一直，与“失败以后”的转折语境不合。", "最后": "语义：“最后”表示结局，不能表示努力的程度。", "恰好": "搭配：“恰好”表示碰巧，不能放在“练得……努力”的程度补语位置。"}, "sentence_index": 6, "correct_answer": "分外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司给他分外发了一笔奖金，表示感谢。", "explanation": "这里应该用〈额外〉。“分外”作副词只表示程度，不能修饰“发”，“分外发”不成立。"}, {"text": "他分外地为朋友准备了生日礼物。", "explanation": "这里应该用〈特意〉。“分外”只修饰形容词或心理动词，不修饰“准备”这类动作；专门为某事做要用〈特意〉。"}, {"text": "这周他分外去了一次医院，身体还是不舒服。", "explanation": "这里应该用〈再〉。“分外”表示格外、特别，不能表示“又一次”；又一次去要用〈再〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋天的山林分外。", "corrected_sentence": "秋天的山林分外美丽。", "error_description": "句子不完整：“分外”是副词，只能修饰后面的形容词，句末不能只剩“分外”，应为“分外美丽”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪后的早晨，阳光很分外耀眼。", "corrected_sentence": "雪后的早晨，阳光分外耀眼。", "error_description": "“分外”本身已表示程度，前面又加“很”，属于重复，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
