INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93067, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "制订是想好办法，写下来作为计划。", "primary_collocate": null, "pronunciation": "zhì dìng", "ipa": "ʈʂɻ̩˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "新年到了，我制订了学习计划。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师帮我制订了一张复习表。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出发前，我们制订了旅行计划。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她给自己制订了减肥计划。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你制订一个周末的活动计划。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想制订一个存钱的计划。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥正在为考试制订复习计划。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈和我制订了家里的打扫计划。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练为运动员制订了训练计划。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你最好提前制订好今年的计划。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "制订了", "label": "体标"}, {"form": "制订过", "label": "体标"}, {"form": "制訂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己想好办法并写成计划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93067, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制订", "is_correct": true, "explanation": "正确：「制订」指想好办法并写成计划，与「学习计划」搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说吃「学习计划」。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」是不及物动词，不能带「学习计划」作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发出歌声，与「学习计划」无关，句意不通。"}], "explanations": {"制订": "正确：「制订」指想好办法并写成计划，与「学习计划」搭配。", "吃": "搭配：「吃」的对象是食物，不能说吃「学习计划」。", "散步": "配价：「散步」是不及物动词，不能带「学习计划」作宾语。", "唱": "语义：「唱」指发出歌声，与「学习计划」无关，句意不通。"}, "sentence_index": 0, "correct_answer": "制订"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重制订了三公斤。", "explanation": "这里应该用〈增加〉。制订指确定计划，体重的变化要说增加。"}, {"text": "她给自己制订了一件衣服。", "explanation": "这里应该用〈设计〉。制订指确定计划，衣服要说设计。"}, {"text": "她给自己制订了一碗面。", "explanation": "这里应该用〈煮〉。制订不用于烹饪，面要说煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
