INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93068, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "创制并确定（法律、规章、政策等）。", "primary_collocate": null, "pronunciation": "zhì dìng", "ipa": "ʈʂɻ̩˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学校制订了新的规章制度。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府正在制订新的法律。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要制订明年的员工守则。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起制订了比赛规则。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法是专家制订的。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家制订了保护环境的政策。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先制订规则，再开始工作。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们制订的规定很严格。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院制订了一套新的管理办法。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部法律制订得很清楚。", "target_word": "制订", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "制订了", "label": "体标"}, {"form": "制订过", "label": "体标"}, {"form": "制訂", "label": "繁体"}], "register": "书面", "sense_fingerprint": "创制并确定法律、规章、政策等正式文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制订", "is_correct": true, "explanation": "正确：「制订」指拟定并确定规章制度，与「规章制度」搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发出乐音，与「规章制度」不能搭配，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」的对象是器物，不能说修理「规章制度」。"}, {"text": "走", "is_correct": false, "explanation": "配价：「走」是不及物动词，不能带「规章制度」作宾语。"}], "explanations": {"制订": "正确：「制订」指拟定并确定规章制度，与「规章制度」搭配。", "唱": "语义：「唱」指发出乐音，与「规章制度」不能搭配，句意不通。", "修理": "搭配：「修理」的对象是器物，不能说修理「规章制度」。", "走": "配价：「走」是不及物动词，不能带「规章制度」作宾语。"}, "sentence_index": 0, "correct_answer": "制订"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每天制订三百个零件。", "explanation": "这里应该用〈制造〉。制订用于规章、计划等，不用于生产零件，生产零件要说制造。"}, {"text": "我们制订了一个新的广告。", "explanation": "这里应该用〈设计〉。制订指制定规章或计划，广告要说设计，不能说制订。"}, {"text": "他们制订了一首新歌。", "explanation": "这里应该用〈创作〉。制订用于规章、计划，歌曲要说创作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制订", "is_correct": true, "explanation": "正确：「制订」指拟定规则，与「规则」搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说吃「规则」。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」是不及物动词，不能带「规则」作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」指用水清除污物，与「规则」无关，句意不通。"}], "explanations": {"制订": "正确：「制订」指拟定规则，与「规则」搭配，句意通顺。", "吃": "搭配：「吃」的对象是食物，不能说吃「规则」。", "散步": "配价：「散步」是不及物动词，不能带「规则」作宾语。", "洗": "语义：「洗」指用水清除污物，与「规则」无关，句意不通。"}, "sentence_index": 6, "correct_answer": "制订"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他制订了一封长信。", "explanation": "这里应该用〈写〉。制订指确定规章或计划，信件要说写。"}, {"text": "这位画家制订了一幅风景画。", "explanation": "这里应该用〈绘制〉。制订指确定规章或计划，绘制风景画要说绘制，不能说制订。"}, {"text": "厨师制订了一个蛋糕。", "explanation": "这里应该用〈烤〉。制订不用于烹饪，蛋糕要说烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
