INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93073, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "透露是把还没说出去的事告诉别人。", "primary_collocate": null, "pronunciation": "tòu lù", "ipa": "tʰoʊ lu", "syllable_count": 2, "sentences": [{"text": "我悄悄向你透露一个小秘密。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先向朋友透露了结婚的消息。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有对任何人透露这个计划。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥偷偷透露了我的生日计划。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能不能先透露一点？", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈还没透露我们要去哪儿。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只对我透露了真实的想法。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁把我的地址透露给他了？", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师透露考试会有作文。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你别把我的话透露给别人。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "透露了", "label": "体标"}, {"form": "透露过", "label": "体标"}, {"form": "透露出", "label": "方向补语"}], "register": "通用", "sense_fingerprint": "把还没公开的事告诉别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透露", "is_correct": true, "explanation": "“透露”指把小秘密告诉对方，与“悄悄向你”相符。"}, {"text": "宣布", "is_correct": false, "explanation": "语义：“宣布”是公开告知，与“悄悄”和“秘密”矛盾。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的对象是物品，不能用于秘密。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能说购买秘密。"}], "explanations": {"透露": "“透露”指把小秘密告诉对方，与“悄悄向你”相符。", "宣布": "语义：“宣布”是公开告知，与“悄悄”和“秘密”矛盾。", "生产": "搭配：“生产”的对象是物品，不能用于秘密。", "购买": "搭配：“购买”的对象是商品，不能说购买秘密。"}, "sentence_index": 0, "correct_answer": "透露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把饭透露给了我。", "explanation": "这里应该用〈送〉。透露只用于消息、想法，不能用于食物，把饭给人要用送。"}, {"text": "我把钱透露给了他。", "explanation": "这里可以用〈借〉。透露只用于消息、想法，不能用于钱，把钱给别人要用借、给等动词。"}, {"text": "我把感冒透露给了老师。", "explanation": "这里应该用〈传染〉。透露指把消息告诉别人，不能用于病的传播，把病传给别人要用传染。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透露", "is_correct": true, "explanation": "“透露”指把想法告诉对方，与“只对我”相符。"}, {"text": "宰杀", "is_correct": false, "explanation": "语义：“宰杀”指杀动物，与想法无关。"}, {"text": "出租", "is_correct": false, "explanation": "搭配：“出租”的对象是房屋或物品，不能用于想法。"}, {"text": "运输", "is_correct": false, "explanation": "搭配：“运输”的对象是货物，不能用于想法。"}], "explanations": {"透露": "“透露”指把想法告诉对方，与“只对我”相符。", "宰杀": "语义：“宰杀”指杀动物，与想法无关。", "出租": "搭配：“出租”的对象是房屋或物品，不能用于想法。", "运输": "搭配：“运输”的对象是货物，不能用于想法。"}, "sentence_index": 6, "correct_answer": "透露"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把作业透露给了老师。", "explanation": "这里应该用〈交〉。透露只用于消息、想法，不能用于作业，把作业给老师要用交。"}, {"text": "我把书透露给了图书馆。", "explanation": "这里应该用〈还〉。透露不能用于书本，把书归还给图书馆要用还。"}, {"text": "他把房子透露给了别人。", "explanation": "这里应该用〈卖〉。透露不能用于房产，把房子卖给别人要用卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我偷偷向朋友透露给了这件事。", "corrected_sentence": "我偷偷向朋友透露了这件事。", "error_description": "错误：“透露给了这件事”。正确：“透露了这件事”。“透露”后接的是消息内容，不能用“给”引出，“给”只用于接受消息的人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个秘密是谁透露你的？", "corrected_sentence": "这个秘密是谁透露给你的？", "error_description": "错误：“透露你的”。正确：“透露给你的”。“透露”表示把消息告诉某人时，接受消息的人要用“给”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
