INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93074, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把消息、想法等泄露或显露出来。", "primary_collocate": null, "pronunciation": "tòu lù", "ipa": "tʰoʊ lu", "syllable_count": 2, "sentences": [{"text": "他不愿意透露自己的年龄。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没有透露新产品的价格。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息是谁透露给记者的？", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话透露出她很不高兴。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板透露了明年的计划。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一句话也没透露。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察不能透露案子的情况。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼神透露出一点紧张。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把这件事透露出去。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队没有透露比赛的名单。", "target_word": "透露", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "透露了", "label": "体标"}, {"form": "透露过", "label": "体标"}, {"form": "透露出", "label": "方向补语"}], "register": "通用", "sense_fingerprint": "泄露或显露消息、想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透露", "is_correct": true, "explanation": "“透露”指把年龄说出来，与“不愿意”相符。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是货物，不能用于年龄。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”指保存物品，与说出自己年龄的语境不合。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的对象是物品，不能用于年龄。"}], "explanations": {"透露": "“透露”指把年龄说出来，与“不愿意”相符。", "搬运": "搭配：“搬运”的对象是货物，不能用于年龄。", "收藏": "语义：“收藏”指保存物品，与说出自己年龄的语境不合。", "生产": "搭配：“生产”的对象是物品，不能用于年龄。"}, "sentence_index": 0, "correct_answer": "透露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他点了点头，把钥匙透露给了我。", "explanation": "这里应该用〈递〉。透露只用于消息、想法，不能用于钥匙，递钥匙要用递。"}, {"text": "他一直替朋友透露行李，从来不让别人碰。", "explanation": "这里应该用〈保管〉。透露指把消息、想法说出或显露出来，替朋友看管行李要用保管。"}, {"text": "他握着方向盘，把它透露了一圈。", "explanation": "这里应该用〈转〉。透露只用于消息、想法，不能用于操作物体，转方向盘要用转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透露", "is_correct": true, "explanation": "“透露”指把案子的情况说出去，与“不能”的禁止语境相符。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”针对喜事，不能用于案子的情况。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞人或作品，不能用于案子的情况。"}, {"text": "运送", "is_correct": false, "explanation": "搭配：“运送”的对象是货物，不能说运送案情。"}], "explanations": {"透露": "“透露”指把案子的情况说出去，与“不能”的禁止语境相符。", "庆祝": "语义：“庆祝”针对喜事，不能用于案子的情况。", "夸奖": "语义：“夸奖”是称赞人或作品，不能用于案子的情况。", "运送": "搭配：“运送”的对象是货物，不能说运送案情。"}, "sentence_index": 6, "correct_answer": "透露"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他背着书包，把一本书透露给了同学。", "explanation": "这里应该用〈借〉。透露只用于消息、想法，借书要用借给。"}, {"text": "园丁给花透露了水。", "explanation": "这里应该用〈浇〉。透露不能用于浇水这种动作，给花浇水要用浇。"}, {"text": "工人在地上透露了一个坑。", "explanation": "这里应该用〈挖〉。透露不能用于挖掘的动作，地上挖坑要用挖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个秘密是谁透露老师的？", "corrected_sentence": "那个秘密是谁透露给老师的？", "error_description": "错误：“透露老师的”。正确：“透露给老师的”。“透露”表示把消息告诉某人时，接受消息的人要用“给”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没透露了这件事。", "corrected_sentence": "我从没透露过这件事。", "error_description": "错误：“从没透露了”。正确：“从没透露过”。表示从未有过的经历，要用“过”，不用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
