INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93075, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "剧场是大家坐着看表演的大房子。", "primary_collocate": null, "pronunciation": "jù chǎng", "ipa": "tɕy⁵¹ ʈʂʰaŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "我们昨天晚上去剧场看了一场话剧。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个剧场的舞台很大，能站五十个演员。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧场里很黑，大家都安静地坐着。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们排好队，走进剧场看木偶戏。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想和朋友去剧场看演出。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧场门口贴着新话剧的海报。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家旁边新开了一个剧场，常演话剧。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出七点开始，我们六点半到了剧场。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧场的灯一关，演员就上台了。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在剧场门口买了两张话剧票。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "小剧场", "label": "复合词"}, {"form": "劇場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常说法：有舞台和座位，大家去看话剧等表演的大房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93075, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "剧场", "is_correct": true, "explanation": "正确。剧场是供大家坐着看话剧等表演的大房子。"}, {"text": "机场", "is_correct": false, "explanation": "机场：jī（第一声）与 jù（第四声）的韵母和声调都不同，意思是飞机起降的地方。"}, {"text": "主场", "is_correct": false, "explanation": "主场：zhǔ（第三声）与 jù（第四声）声母与声调不同，意思是比赛时主队所在的场地。"}, {"text": "驻场", "is_correct": false, "explanation": "驻场：zhù（第四声）与 jù（第四声）声母不同（zh 与 j），韵母也不同（u 与 ü），意思是长期在某个场所演出。"}, {"text": "救场", "is_correct": false, "explanation": "救场：jiù（第四声）与 jù（第四声）韵母不同（iu 与 ü），意思是临时顶替、挽回局面。"}], "explanations": {"剧场": "正确。剧场是供大家坐着看话剧等表演的大房子。", "机场": "机场：jī（第一声）与 jù（第四声）的韵母和声调都不同，意思是飞机起降的地方。", "主场": "主场：zhǔ（第三声）与 jù（第四声）声母与声调不同，意思是比赛时主队所在的场地。", "驻场": "驻场：zhù（第四声）与 jù（第四声）声母不同（zh 与 j），韵母也不同（u 与 ü），意思是长期在某个场所演出。", "救场": "救场：jiù（第四声）与 jù（第四声）韵母不同（iu 与 ü），意思是临时顶替、挽回局面。"}, "sentence_index": null, "correct_answer": "剧场"}, "level_3": {"options": [{"text": "剧场", "is_correct": true, "explanation": "正确。看话剧要去有舞台和座位的剧场。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借书、读书的地方，不是演出话剧的场所。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理存取款的地方，不能用来看话剧。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：“看……话剧”要在演出场所进行，菜市场不能和“看话剧”搭配。"}], "explanations": {"剧场": "正确。看话剧要去有舞台和座位的剧场。", "图书馆": "语义：图书馆是借书、读书的地方，不是演出话剧的场所。", "银行": "语义：银行是办理存取款的地方，不能用来看话剧。", "菜市场": "搭配：“看……话剧”要在演出场所进行，菜市场不能和“看话剧”搭配。"}, "sentence_index": 0, "correct_answer": "剧场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去剧场游泳。", "explanation": "这里应该用〈游泳馆〉。剧场是演出戏剧、歌舞的场所，游泳要去游泳馆。"}, {"text": "演员站在剧场上表演，观众在下面看。", "explanation": "这里应该用〈舞台〉。剧场指整座建筑，站在上面表演要说舞台；应说在剧场里表演。"}, {"text": "剧场里人很多，大家都在排队结账。", "explanation": "这里应该用〈超市〉。剧场是演出戏剧、歌舞的场所，排队结账要去超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93075, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "剧场", "is_correct": true, "explanation": "正确。剧场是供大家坐着看话剧等表演的大房子。"}, {"text": "鸡场", "is_correct": false, "explanation": "鸡场：jī（第一声）与 jù（第四声）的韵母和声调都不同，意思是养鸡的场地。"}, {"text": "鱼场", "is_correct": false, "explanation": "鱼场：yú（第二声）与 jù（第四声）声母不同（y 与 j），声调也不同，意思是养鱼的场所。"}, {"text": "句长", "is_correct": false, "explanation": "句长：第二音节 cháng（第二声）与 chǎng（第三声）声调不同，意思是句子的长度。"}], "explanations": {"剧场": "正确。剧场是供大家坐着看话剧等表演的大房子。", "鸡场": "鸡场：jī（第一声）与 jù（第四声）的韵母和声调都不同，意思是养鸡的场地。", "鱼场": "鱼场：yú（第二声）与 jù（第四声）声母不同（y 与 j），声调也不同，意思是养鱼的场所。", "句长": "句长：第二音节 cháng（第二声）与 chǎng（第三声）声调不同，意思是句子的长度。"}, "sentence_index": null, "correct_answer": "剧场"}, "level_3": {"options": [{"text": "剧场", "is_correct": true, "explanation": "正确。剧场是常演话剧的演出场所。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“常演话剧”的地点要说剧场或剧院，饭店不能和“演话剧”搭配。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是卖东西的地方，与“常演话剧”的语境不符。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池是游泳的地方，不用来演话剧。"}], "explanations": {"剧场": "正确。剧场是常演话剧的演出场所。", "饭店": "搭配：“常演话剧”的地点要说剧场或剧院，饭店不能和“演话剧”搭配。", "超市": "语义：超市是卖东西的地方，与“常演话剧”的语境不符。", "游泳池": "语义：游泳池是游泳的地方，不用来演话剧。"}, "sentence_index": 6, "correct_answer": "剧场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "剧场里陈列着很多古代文物。", "explanation": "这里应该用〈博物馆〉。剧场是演出戏剧、歌舞的场所，陈列文物要去博物馆。"}, {"text": "剧场里有很多病人在排队挂号。", "explanation": "这里应该用〈医院〉。剧场用于演出，排队挂号要去医院。"}, {"text": "剧场每周一都举行升旗仪式。", "explanation": "这里应该用〈学校〉。剧场用于演出，升旗仪式是学校的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只剧场是去年才建成的。", "corrected_sentence": "这座剧场是去年才建成的。", "error_description": "量词错误：剧场是大型建筑，量词应用「座」，不用「只」（「只」多用于动物或成对的物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这个周末去那台剧场看话剧。", "corrected_sentence": "我们这个周末去那座剧场看话剧。", "error_description": "量词错误：剧场是建筑，量词应用「座」，不用「台」（「台」多用于机器、晚会等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
