INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93076, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供演出戏剧、歌舞等并供观众观看的场所。", "primary_collocate": null, "pronunciation": "jù chǎng", "ipa": "tɕy⁵¹ ʈʂʰaŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这座剧场可以容纳八百名观众。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧场是演出戏剧和歌舞的场所。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心新建了一座现代化的剧场。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家剧场每周都有新的戏剧演出。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在剧场里当了十年舞台工作人员。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老剧场的舞台很小，但声音很好。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧场的灯光和音响都需要检查。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个剧团明天在城里的剧场首次演出。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让更多观众看戏，城里又建了两座剧场。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众提前半小时走进剧场，找到了自己的座位。", "target_word": "剧场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "小剧场", "label": "复合词"}, {"form": "劇場", "label": "繁体"}], "register": "书面", "sense_fingerprint": "辞典释义：供演出戏剧、歌舞并供观众观看的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93076, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "剧场", "is_correct": true, "explanation": "正确。剧场是供演出戏剧、歌舞并供观众观看的场所。"}, {"text": "机场", "is_correct": false, "explanation": "机场：jī（第一声）与 jù（第四声）的韵母和声调都不同，意思是飞机起降的地方。"}, {"text": "驻场", "is_correct": false, "explanation": "驻场：zhù（第四声）与 jù（第四声）声母不同（zh 与 j），韵母也不同（u 与 ü），意思是长期在某场所演出。"}, {"text": "救场", "is_correct": false, "explanation": "救场：jiù（第四声）与 jù（第四声）韵母不同（iu 与 ü），意思是临时顶替、挽回局面。"}, {"text": "鸡场", "is_correct": false, "explanation": "鸡场：jī（第一声）与 jù（第四声）的韵母和声调不同，意思是养鸡的场地。"}], "explanations": {"剧场": "正确。剧场是供演出戏剧、歌舞并供观众观看的场所。", "机场": "机场：jī（第一声）与 jù（第四声）的韵母和声调都不同，意思是飞机起降的地方。", "驻场": "驻场：zhù（第四声）与 jù（第四声）声母不同（zh 与 j），韵母也不同（u 与 ü），意思是长期在某场所演出。", "救场": "救场：jiù（第四声）与 jù（第四声）韵母不同（iu 与 ü），意思是临时顶替、挽回局面。", "鸡场": "鸡场：jī（第一声）与 jù（第四声）的韵母和声调不同，意思是养鸡的场地。"}, "sentence_index": null, "correct_answer": "剧场"}, "level_3": {"options": [{"text": "剧场", "is_correct": true, "explanation": "正确。这座剧场指的是供演出戏剧、歌舞的大型场所。"}, {"text": "大桥", "is_correct": false, "explanation": "语义：大桥是交通设施，不能用来容纳观众看戏。"}, {"text": "高山", "is_correct": false, "explanation": "语义：高山是自然景观，不是可以容纳观众的场所。"}, {"text": "雕像", "is_correct": false, "explanation": "搭配：“可以容纳八百名观众”说的是空间，雕像不能和“容纳观众”搭配。"}], "explanations": {"剧场": "正确。这座剧场指的是供演出戏剧、歌舞的大型场所。", "大桥": "语义：大桥是交通设施，不能用来容纳观众看戏。", "高山": "语义：高山是自然景观，不是可以容纳观众的场所。", "雕像": "搭配：“可以容纳八百名观众”说的是空间，雕像不能和“容纳观众”搭配。"}, "sentence_index": 0, "correct_answer": "剧场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家剧场每周都有新的篮球比赛。", "explanation": "这里应该用〈体育馆〉。剧场用于演出戏剧、歌舞，篮球比赛要在体育馆进行。"}, {"text": "这家剧场每周都有新的画展。", "explanation": "这里应该用〈美术馆〉。剧场用于演出戏剧、歌舞，画展要去美术馆。"}, {"text": "剧场里有很多旅客在办理登机手续。", "explanation": "这里应该用〈机场〉。剧场用于演出，办理登机手续要去机场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93076, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "剧场", "is_correct": true, "explanation": "正确。剧场是供演出戏剧、歌舞并供观众观看的场所。"}, {"text": "主场", "is_correct": false, "explanation": "主场：zhǔ（第三声）与 jù（第四声）声母与声调不同，意思是比赛时主队所在的场地。"}, {"text": "鱼场", "is_correct": false, "explanation": "鱼场：yú（第二声）与 jù（第四声）声母不同（y 与 j），声调也不同，意思是养鱼的场所。"}, {"text": "句长", "is_correct": false, "explanation": "句长：第二音节 cháng（第二声）与 chǎng（第三声）声调不同，意思是句子的长度。"}], "explanations": {"剧场": "正确。剧场是供演出戏剧、歌舞并供观众观看的场所。", "主场": "主场：zhǔ（第三声）与 jù（第四声）声母与声调不同，意思是比赛时主队所在的场地。", "鱼场": "鱼场：yú（第二声）与 jù（第四声）声母不同（y 与 j），声调也不同，意思是养鱼的场所。", "句长": "句长：第二音节 cháng（第二声）与 chǎng（第三声）声调不同，意思是句子的长度。"}, "sentence_index": null, "correct_answer": "剧场"}, "level_3": {"options": [{"text": "剧场", "is_correct": true, "explanation": "正确。剧场是供演出戏剧、歌舞的场所，有灯光和音响设备。"}, {"text": "诗歌", "is_correct": false, "explanation": "搭配：诗歌是文字作品，没有灯光和音响设备，不能和“灯光和音响”搭配。"}, {"text": "字典", "is_correct": false, "explanation": "搭配：字典是工具书，没有灯光和音响设备，不能和“灯光和音响”搭配。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“……的灯光和音响”说的是有设备的场所，书架不能和“灯光和音响”搭配。"}], "explanations": {"剧场": "正确。剧场是供演出戏剧、歌舞的场所，有灯光和音响设备。", "诗歌": "搭配：诗歌是文字作品，没有灯光和音响设备，不能和“灯光和音响”搭配。", "字典": "搭配：字典是工具书，没有灯光和音响设备，不能和“灯光和音响”搭配。", "书架": "搭配：“……的灯光和音响”说的是有设备的场所，书架不能和“灯光和音响”搭配。"}, "sentence_index": 6, "correct_answer": "剧场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "剧场里很安静，学生们在认真看书。", "explanation": "这里应该用〈图书馆〉。剧场用于演出，认真看书要去图书馆。"}, {"text": "剧场里有很多老人在散步聊天。", "explanation": "这里应该用〈公园〉。剧场用于演出，散步聊天要去公园。"}, {"text": "剧场里排着长队，大家在等着取钱。", "explanation": "这里应该用〈银行〉。剧场用于演出，取钱要去银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条剧场在去年翻修后重新开放了。", "corrected_sentence": "这座剧场在去年翻修后重新开放了。", "error_description": "量词错误：剧场是建筑，量词应用「座」，不用「条」（「条」用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场演出剧场举行。", "corrected_sentence": "这场演出在剧场举行。", "error_description": "介词错误：表示地点要用「在剧场」，省略「在」后「剧场举行」不成句，应说「在剧场举行」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
