INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93077, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "配是把合适的东西放在一起。", "primary_collocate": null, "pronunciation": "pèi", "ipa": "pʰei˥˩", "syllable_count": 1, "sentences": [{"text": "我去楼下配了一把新钥匙。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给他配了三天的药。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷要去商店配一副眼镜。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套茶具少了一个杯子，我想配一个。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手表没电了，我去店里配了一块新电池。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "眼镜坏了，他要去重新配一副。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钥匙丢了，我得去配一把。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店能按手机型号配手机壳。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请按这张单子把东西配齐。", "target_word": "配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把四个同样的杯子配成了一套。", "target_word": "配", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "配了", "label": "体标"}, {"form": "配着", "label": "体标"}, {"form": "配过", "label": "体标"}], "register": "口语", "sense_fingerprint": "按要求把合适的东西凑在一起，如配钥匙、配药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93077, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "配", "is_correct": true, "explanation": "正确：「配」读作 pèi（第四声），即本词，指按要求把东西配齐。"}, {"text": "类", "is_correct": false, "explanation": "声母不同：lèi 与 pèi 的声母不同（l／p），意思是种类。"}, {"text": "备", "is_correct": false, "explanation": "声母不同：bèi 与 pèi 的声母不同（b 不送气，p 送气），意思是准备。"}, {"text": "废", "is_correct": false, "explanation": "声母不同：fèi 与 pèi 的声母不同（f／p），意思是废弃。"}], "explanations": {"配": "正确：「配」读作 pèi（第四声），即本词，指按要求把东西配齐。", "类": "声母不同：lèi 与 pèi 的声母不同（l／p），意思是种类。", "备": "声母不同：bèi 与 pèi 的声母不同（b 不送气，p 送气），意思是准备。", "废": "声母不同：fèi 与 pèi 的声母不同（f／p），意思是废弃。"}, "sentence_index": null, "correct_answer": "配"}, "level_3": {"options": [{"text": "配", "is_correct": true, "explanation": "正确：「配」指按要求配一把钥匙，与「新钥匙」的语境吻合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发出歌声，与「新钥匙」无关，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」是不及物动词，不能带「钥匙」作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说吃「钥匙」。"}], "explanations": {"配": "正确：「配」指按要求配一把钥匙，与「新钥匙」的语境吻合。", "唱": "语义：「唱」指发出歌声，与「新钥匙」无关，句意不通。", "散步": "配价：「散步」是不及物动词，不能带「钥匙」作宾语。", "吃": "搭配：「吃」的对象是食物，不能说吃「钥匙」。"}, "sentence_index": 0, "correct_answer": "配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书配进了箱子里。", "explanation": "这里应该用〈装〉。配指把合适的东西放在一起、配齐，把书装进箱子要说装，不能说配。"}, {"text": "他把积木配成了一座房子。", "explanation": "这里应该用〈拼〉。配成多指把成套的东西配在一起，积木拼成房子要说拼，不能说配。"}, {"text": "我周末配孩子去公园。", "explanation": "这里应该用〈陪〉。配指把合适的东西放在一起，陪孩子去公园要说陪，不能说配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93077, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "配", "is_correct": true, "explanation": "正确：「配」读作 pèi（第四声），即本词，指按要求把东西配齐。"}, {"text": "位", "is_correct": false, "explanation": "声母不同：wèi 与 pèi 的声母不同（w／p），意思是位置。"}, {"text": "倍", "is_correct": false, "explanation": "声母不同：bèi 与 pèi 的声母不同（b 不送气，p 送气），意思是倍数。"}, {"text": "泪", "is_correct": false, "explanation": "声母不同：lèi 与 pèi 的声母不同（l／p），意思是眼泪。"}], "explanations": {"配": "正确：「配」读作 pèi（第四声），即本词，指按要求把东西配齐。", "位": "声母不同：wèi 与 pèi 的声母不同（w／p），意思是位置。", "倍": "声母不同：bèi 与 pèi 的声母不同（b 不送气，p 送气），意思是倍数。", "泪": "声母不同：lèi 与 pèi 的声母不同（l／p），意思是眼泪。"}, "sentence_index": null, "correct_answer": "配"}, "level_3": {"options": [{"text": "配", "is_correct": true, "explanation": "正确：「配」指按要求配一把钥匙，与「丢了」的语境吻合。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」指用水去除污物，与「钥匙」无关，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：「游泳」是不及物动词，不能带「一把」作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是饮品，不能说喝「钥匙」。"}], "explanations": {"配": "正确：「配」指按要求配一把钥匙，与「丢了」的语境吻合。", "洗": "语义：「洗」指用水去除污物，与「钥匙」无关，句意不通。", "游泳": "配价：「游泳」是不及物动词，不能带「一把」作宾语。", "喝": "搭配：「喝」的对象是饮品，不能说喝「钥匙」。"}, "sentence_index": 6, "correct_answer": "配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸给汽车配了一次油。", "explanation": "这里应该用〈加〉。配指把合适的东西放在一起，给汽车加油要说加，不能说配。"}, {"text": "他配了一大堆邮票。", "explanation": "这里应该用〈收集〉。配指把合适的东西放在一起，收集邮票要说收集，不能说配。"}, {"text": "他把这首诗配成了英文。", "explanation": "这里应该用〈翻译〉。配成指把东西配在一起成套，把诗译成英文要说翻译，不能说配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我正在楼下配了一把新钥匙。", "corrected_sentence": "我正在楼下配一把新钥匙。", "error_description": "错误：「正在」表示动作进行中，不能与「了」同用。正确说法是「我正在楼下配一把新钥匙」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把钥匙配很准。", "corrected_sentence": "这把钥匙配得很准。", "error_description": "错误：「配」后带补语「很准」时，漏掉了结构助词「得」。正确说法是「配得很准」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
