INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93078, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使合适的人或物相搭配、相称。", "primary_collocate": null, "pronunciation": "pèi", "ipa": "pʰei˥˩", "syllable_count": 1, "sentences": [{"text": "这条裤子配你的白鞋很好看。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红色的衣服配黑色的包，很好看。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩站在一起，真的很配。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋配这条裙子正好。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "米饭配青菜，吃起来很清淡。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白酒配花生米，他最爱吃。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件红衣服配她的黑头发，特别好看。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个颜色配不配我的衣服？", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这顶帽子配你的外套刚刚好。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛肉配红酒是很多人喜欢的吃法。", "target_word": "配", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "配了", "label": "体标"}, {"form": "配着", "label": "体标"}, {"form": "配过", "label": "体标"}], "register": "口语", "sense_fingerprint": "两样东西或两个人搭在一起很相称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93078, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "配", "is_correct": true, "explanation": "正确：「配」读作 pèi（第四声），即本词，指使两样东西相称。"}, {"text": "陪", "is_correct": false, "explanation": "声调不同：péi（第二声）与 pèi（第四声）声调不同，意思是陪同。"}, {"text": "费", "is_correct": false, "explanation": "声母不同：fèi 与 pèi 的声母不同（f／p），意思是花费。"}, {"text": "妹", "is_correct": false, "explanation": "声母不同：mèi 与 pèi 的声母不同（m／p），意思是妹妹。"}], "explanations": {"配": "正确：「配」读作 pèi（第四声），即本词，指使两样东西相称。", "陪": "声调不同：péi（第二声）与 pèi（第四声）声调不同，意思是陪同。", "费": "声母不同：fèi 与 pèi 的声母不同（f／p），意思是花费。", "妹": "声母不同：mèi 与 pèi 的声母不同（m／p），意思是妹妹。"}, "sentence_index": null, "correct_answer": "配"}, "level_3": {"options": [{"text": "配", "is_correct": true, "explanation": "正确：「配」指使合适的东西相搭配，与「白鞋」「好看」的语境吻合。"}, {"text": "穿", "is_correct": false, "explanation": "语义：「穿」指把衣物套在身上，主语是裤子，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说吃「白鞋」。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」是不及物动词，不能带「白鞋」作宾语。"}], "explanations": {"配": "正确：「配」指使合适的东西相搭配，与「白鞋」「好看」的语境吻合。", "穿": "语义：「穿」指把衣物套在身上，主语是裤子，句意不通。", "吃": "搭配：「吃」的对象是食物，不能说吃「白鞋」。", "散步": "配价：「散步」是不及物动词，不能带「白鞋」作宾语。"}, "sentence_index": 0, "correct_answer": "配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他配了一个笑话。", "explanation": "这里应该用〈讲〉。配表示相配、相称，讲笑话要说讲，不能说配。"}, {"text": "他很配老师的安排。", "explanation": "这里应该用〈配合〉。配表示相配、相称，服从或配合别人的安排要说配合，不能只说配。"}, {"text": "我下班后配你去医院。", "explanation": "这里应该用〈陪〉。配表示相配、相称，陪人去医院要说陪，不能说配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93078, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "配", "is_correct": true, "explanation": "正确：「配」读作 pèi（第四声），即本词，指使两样东西相称。"}, {"text": "赔", "is_correct": false, "explanation": "声调不同：péi（第二声）与 pèi（第四声）声调不同，意思是赔偿。"}, {"text": "味", "is_correct": false, "explanation": "声母不同：wèi 与 pèi 的声母不同（w／p），意思是味道。"}, {"text": "贝", "is_correct": false, "explanation": "声母不同：bèi 与 pèi 的声母不同（b 不送气，p 送气），意思是贝壳。"}], "explanations": {"配": "正确：「配」读作 pèi（第四声），即本词，指使两样东西相称。", "赔": "声调不同：péi（第二声）与 pèi（第四声）声调不同，意思是赔偿。", "味": "声母不同：wèi 与 pèi 的声母不同（w／p），意思是味道。", "贝": "声母不同：bèi 与 pèi 的声母不同（b 不送气，p 送气），意思是贝壳。"}, "sentence_index": null, "correct_answer": "配"}, "level_3": {"options": [{"text": "配", "is_correct": true, "explanation": "正确：「配」指使红衣服与黑头发相称，与「特别好看」的语境吻合。"}, {"text": "梳", "is_correct": false, "explanation": "语义：「梳」指梳理头发，主语是衣服，句意不通。"}, {"text": "走", "is_correct": false, "explanation": "配价：「走」是不及物动词，不能带「黑头发」作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是饮品，不能说喝「黑头发」。"}], "explanations": {"配": "正确：「配」指使红衣服与黑头发相称，与「特别好看」的语境吻合。", "梳": "语义：「梳」指梳理头发，主语是衣服，句意不通。", "走": "配价：「走」是不及物动词，不能带「黑头发」作宾语。", "喝": "搭配：「喝」的对象是饮品，不能说喝「黑头发」。"}, "sentence_index": 6, "correct_answer": "配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师每周配他学习数学。", "explanation": "这里应该用〈辅导〉。配表示相配、相称，老师给学生补习功课要说辅导，不能说配。"}, {"text": "他配了一封长信。", "explanation": "这里应该用〈写〉。配表示相配、相称，写信要说写，不能说配。"}, {"text": "我们每天都配妈妈去公园。", "explanation": "这里应该用〈陪〉。配表示相配、相称，陪人去公园要说陪，不能说配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这顶帽子和你的外套配很好。", "corrected_sentence": "这顶帽子和你的外套配得很好。", "error_description": "错误：「配」后带补语「很好」时，漏掉了结构助词「得」。正确说法是「配得很好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正在给这条裙子配了一双鞋。", "corrected_sentence": "我正在给这条裙子配一双鞋。", "error_description": "错误：「正在」表示动作进行中，不能与「了」同用。正确说法是「我正在给这条裙子配一双鞋」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
