INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93079, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "顶是最上面的地方。", "primary_collocate": null, "pronunciation": "dǐng", "ipa": "tiŋ˨˩", "syllable_count": 1, "sentences": [{"text": "电梯一直开到顶。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架的顶上放着一盆花。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把箱子放在柜子的顶上。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬到顶以后，我们坐下来休息。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙的顶上有一只猫。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白云挂在高楼的顶上。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱的顶上有一层灰。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不到柜子的顶，要用椅子。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台阶一共有一百级，他走到顶了。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想爬到大树的顶。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "山顶", "label": "复合词"}, {"form": "屋顶", "label": "复合词"}, {"form": "头顶", "label": "复合词"}, {"form": "顶部", "label": "复合词"}], "register": "中性", "sense_fingerprint": "某处最上面的位置，与底相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459873f2-15f3-4c94-997f-d7fd10d4860f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93079, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：dǐng（第三声），指某处最上面的位置。"}, {"text": "订", "is_correct": false, "explanation": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“订”。"}, {"text": "盯", "is_correct": false, "explanation": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“盯着”。"}, {"text": "挡", "is_correct": false, "explanation": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“挡”。"}, {"text": "党", "is_correct": false, "explanation": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“政党”。"}], "explanations": {"顶": "顶：dǐng（第三声），指某处最上面的位置。", "订": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“订”。", "盯": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“盯着”。", "挡": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“挡”。", "党": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“政党”。"}, "sentence_index": null, "correct_answer": "顶"}, "level_3": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：最上面的地方，电梯开到的最高一层。"}, {"text": "海", "is_correct": false, "explanation": "语义：电梯不能开到海里，“海”不是楼层。"}, {"text": "雨", "is_correct": false, "explanation": "语义：电梯开不到“雨”，“雨”不是可到达的处所。"}, {"text": "作业", "is_correct": false, "explanation": "配价：“开到”要求处所，“作业”是事物，不能作终点。"}], "explanations": {"顶": "顶：最上面的地方，电梯开到的最高一层。", "海": "语义：电梯不能开到海里，“海”不是楼层。", "雨": "语义：电梯开不到“雨”，“雨”不是可到达的处所。", "作业": "配价：“开到”要求处所，“作业”是事物，不能作终点。"}, "sentence_index": 0, "correct_answer": "顶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电梯一直降到顶。", "explanation": "这里应该用〈底〉。“降”是向下，要到最下面，应说“降到底”，“顶”是最上面。"}, {"text": "我们从楼的顶走到一楼，再往下走就到顶了。", "explanation": "这里应该用〈底〉。往下走到的是最下面，要说「到底」，「顶」是最上面。"}, {"text": "操场的顶有一棵树。", "explanation": "这里应该用〈中央〉。“顶”指最上面，操场中间要说“中央”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93079, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：dǐng（第三声），指某处最上面的位置。"}, {"text": "定", "is_correct": false, "explanation": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“确定”。"}, {"text": "挺", "is_correct": false, "explanation": "tǐng 与 dǐng 声母不同（t／d），意思是“挺”。"}, {"text": "等", "is_correct": false, "explanation": "děng 与 dǐng 韵母不同（eng／ing），意思是“等”。"}, {"text": "钉", "is_correct": false, "explanation": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“钉子”。"}], "explanations": {"顶": "顶：dǐng（第三声），指某处最上面的位置。", "定": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“确定”。", "挺": "tǐng 与 dǐng 声母不同（t／d），意思是“挺”。", "等": "děng 与 dǐng 韵母不同（eng／ing），意思是“等”。", "钉": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“钉子”。"}, "sentence_index": null, "correct_answer": "顶"}, "level_3": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：冰箱最上面的地方，那里容易积灰。"}, {"text": "名字", "is_correct": false, "explanation": "语义：「名字」不会积灰，「冰箱的名字上有一层灰」说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”是气味感受，不能有“一层灰”。"}, {"text": "笑容", "is_correct": false, "explanation": "搭配：“一层灰”一般说物体的表面，不能搭“笑容”。"}], "explanations": {"顶": "顶：冰箱最上面的地方，那里容易积灰。", "名字": "语义：「名字」不会积灰，「冰箱的名字上有一层灰」说不通。", "味道": "语义：“味道”是气味感受，不能有“一层灰”。", "笑容": "搭配：“一层灰”一般说物体的表面，不能搭“笑容”。"}, "sentence_index": 6, "correct_answer": "顶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游泳池的顶有很多水。", "explanation": "这里应该用〈底〉。水在游泳池下面，要说「池底」，「顶」指最上面。"}, {"text": "这棵大树的顶很深。", "explanation": "这里应该用〈根〉。“深”形容根，“顶”指最上面，不能说顶很深。"}, {"text": "这张椅子的顶很舒服。", "explanation": "这里应该用〈靠背〉。坐得舒服说的是椅子的靠背，“顶”指最上面，不能指靠背。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们终于在了顶，大家都很高兴。", "corrected_sentence": "孩子们终于到了顶，大家都很高兴。", "error_description": "“到了顶”不能说成“在了顶”。表示走到最高处要用“到”，“在”不能作这个补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我站在椅子上，才看到柜子得顶。", "corrected_sentence": "我站在椅子上，才看到柜子的顶。", "error_description": "“柜子的顶”中的“的”不能写成“得”。“得”用于动词后作补语，名词前的修饰语要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
