INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体最高的部分。", "primary_collocate": null, "pronunciation": "dǐng", "ipa": "tiŋ˨˩", "syllable_count": 1, "sentences": [{"text": "这座塔很高，我们爬了很久才到顶。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树的顶上有一个鸟窝。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树太高了，我看不到它的顶。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梯子的顶碰到了天花板。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帽子的顶是红色的。", "target_word": "顶", "complexity_tier": "T3", "furigana": "mào zi de dǐng shì hóng sè de", "sentence_source": "generated"}, {"text": "路很陡，他爬到顶就累坏了。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从瓶子的底到顶都擦干净了。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小旗一直挂在旗杆的顶上。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼的顶是平的，可以看星星。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪人的顶上放着一个红桶。", "target_word": "顶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "山顶", "label": "复合词"}, {"form": "屋顶", "label": "复合词"}, {"form": "头顶", "label": "复合词"}, {"form": "顶部", "label": "复合词"}], "register": "中性", "sense_fingerprint": "物体本身最高的那一部分，如塔、树、帽子的顶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459873f2-15f3-4c94-997f-d7fd10d4860f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：dǐng（第三声），指物体最高的部分。"}, {"text": "定", "is_correct": false, "explanation": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“确定”。"}, {"text": "挺", "is_correct": false, "explanation": "tǐng 与 dǐng 声母不同（t／d），意思是“挺”。"}, {"text": "等", "is_correct": false, "explanation": "děng 与 dǐng 韵母不同（eng／ing），意思是“等”。"}, {"text": "钉", "is_correct": false, "explanation": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“钉子”。"}], "explanations": {"顶": "顶：dǐng（第三声），指物体最高的部分。", "定": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“确定”。", "挺": "tǐng 与 dǐng 声母不同（t／d），意思是“挺”。", "等": "děng 与 dǐng 韵母不同（eng／ing），意思是“等”。", "钉": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“钉子”。"}, "sentence_index": null, "correct_answer": "顶"}, "level_3": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：指物体最高的部分，与“爬了很久”“这座塔很高”相合。"}, {"text": "水", "is_correct": false, "explanation": "语义：爬塔的终点应是高处，“水”不能作这里的到达点。"}, {"text": "海", "is_correct": false, "explanation": "语义：“海”在地面，与“这座塔很高”和“爬”的动作不合。"}, {"text": "课本", "is_correct": false, "explanation": "配价：“到”要求处所，“课本”是物品，不能作“到”的终点。"}], "explanations": {"顶": "顶：指物体最高的部分，与“爬了很久”“这座塔很高”相合。", "水": "语义：爬塔的终点应是高处，“水”不能作这里的到达点。", "海": "语义：“海”在地面，与“这座塔很高”和“爬”的动作不合。", "课本": "配价：“到”要求处所，“课本”是物品，不能作“到”的终点。"}, "sentence_index": 0, "correct_answer": "顶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只鞋的顶破了，要扔掉。", "explanation": "这里应该用〈面〉。鞋子的上半部分叫“鞋面”，“顶”不用来指鞋子。"}, {"text": "这朵玫瑰的顶很扎手。", "explanation": "这里应该用〈刺〉。扎手说的是玫瑰的刺，“顶”指最上面的部分，不能指刺。"}, {"text": "这条路的顶有一片湖。", "explanation": "这里应该用〈尽头〉。路的末端要说“尽头”，“顶”指最上面，不能说路的顶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：dǐng（第三声），指物体最高的部分。"}, {"text": "订", "is_correct": false, "explanation": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“订”。"}, {"text": "盯", "is_correct": false, "explanation": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“盯着”。"}, {"text": "挡", "is_correct": false, "explanation": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“挡”。"}, {"text": "党", "is_correct": false, "explanation": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“政党”。"}], "explanations": {"顶": "顶：dǐng（第三声），指物体最高的部分。", "订": "dìng（第四声）与 dǐng（第三声）声调不同，意思是“订”。", "盯": "dīng（第一声）与 dǐng（第三声）声调不同，意思是“盯着”。", "挡": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“挡”。", "党": "dǎng 与 dǐng 韵母不同（ang／ing），意思是“政党”。"}, "sentence_index": null, "correct_answer": "顶"}, "level_3": {"options": [{"text": "顶", "is_correct": true, "explanation": "顶：与“从瓶子的底到”构成相对的一端，指最高处。"}, {"text": "手", "is_correct": false, "explanation": "语义：“手”不是瓶子的一部分，“从瓶子的底到手”说不通。"}, {"text": "书", "is_correct": false, "explanation": "配价：“到”后要求位置，“书”是物品，不能作擦拭的终点。"}, {"text": "花", "is_correct": false, "explanation": "语义：瓶子上没有“花”这一部分，与“从底到”不合。"}], "explanations": {"顶": "顶：与“从瓶子的底到”构成相对的一端，指最高处。", "手": "语义：“手”不是瓶子的一部分，“从瓶子的底到手”说不通。", "书": "配价：“到”后要求位置，“书”是物品，不能作擦拭的终点。", "花": "语义：瓶子上没有“花”这一部分，与“从底到”不合。"}, "sentence_index": 6, "correct_answer": "顶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口井的顶有很多水。", "explanation": "这里应该用〈底〉。水在井的下面，要说「井底」，「顶」指最高的部分。"}, {"text": "这条河的顶很宽。", "explanation": "这里应该用〈河面〉。河没有“顶”，说河的宽度要用“河面”。"}, {"text": "他的顶很高，走路很显眼。", "explanation": "这里应该用〈个子〉。说人的高矮要用“个子”，“顶”指最上面的部分，不能说人的顶很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一直往上走，终于在顶了。", "corrected_sentence": "他们一直往上走，终于到顶了。", "error_description": "“到顶”不能说成“在顶”。表示走到最高处要用“到”作补语，应说“到顶了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个衣柜很高，我站在地上看不到顶的它。", "corrected_sentence": "这个衣柜很高，我站在地上看不到它的顶。", "error_description": "“它的顶”不能倒成“顶的它”。“它”修饰“顶”，中间要用“的”，应说“它的顶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
