INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93081, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "剧院是看戏和表演的地方。", "primary_collocate": null, "pronunciation": "jù yuàn", "ipa": "tɕy˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "周末我们去剧院看戏。", "target_word": "剧院", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家剧院很大，有一千个座位。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "剧院门口站着很多人。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "剧院里很安静，大家都在看表演。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近新开了一家剧院。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "剧院的票太贵了，我没有买。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在剧院门口等我。", "target_word": "剧院", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座剧院已经有一百年的历史了。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐地铁去剧院，十分钟就到了。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "剧院七点开门，我们六点半就到了。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "家", "label": "量词"}, {"form": "歌剧院", "label": "复合词"}, {"form": "劇院", "label": "繁体"}], "register": "中性", "sense_fingerprint": "供人看戏、看表演的建筑场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93081, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剧院", "is_correct": true, "explanation": "“剧院”是供人看戏的场所，与“看戏”的语境一致。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”不是看戏的场所，与“看戏”的语境冲突。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：“图书馆”是借阅书籍的地方，不能用来看戏。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：“菜市场”是买菜的场所，不与“看戏”搭配。"}], "explanations": {"剧院": "“剧院”是供人看戏的场所，与“看戏”的语境一致。", "医院": "语义：“医院”不是看戏的场所，与“看戏”的语境冲突。", "图书馆": "语义：“图书馆”是借阅书籍的地方，不能用来看戏。", "菜市场": "搭配：“菜市场”是买菜的场所，不与“看戏”搭配。"}, "sentence_index": 0, "correct_answer": "剧院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我感冒了，今天去剧院看病。", "explanation": "这里应该用〈医院〉。剧院是看戏和表演的地方，看病要去医院。"}, {"text": "周末我们去剧院买菜。", "explanation": "这里应该用〈菜市场〉。剧院是看戏和表演的地方，买菜要去菜市场。"}, {"text": "我把钱存在剧院里，每个月都去取。", "explanation": "这里应该用〈银行〉。剧院是看戏和表演的地方，存钱要去银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93081, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剧院", "is_correct": true, "explanation": "“剧院”是可以站人、有门口的场所，与“他在……门口等我”的语境一致。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不是能站人、有门口的场所，句子语义不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”没有门口，与“等我”的场所语境不符。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“钢琴”是乐器，不能与“门口”搭配作为等人的位置。"}], "explanations": {"剧院": "“剧院”是可以站人、有门口的场所，与“他在……门口等我”的语境一致。", "电脑": "语义：“电脑”不是能站人、有门口的场所，句子语义不通。", "水果": "语义：“水果”没有门口，与“等我”的场所语境不符。", "钢琴": "搭配：“钢琴”是乐器，不能与“门口”搭配作为等人的位置。"}, "sentence_index": 6, "correct_answer": "剧院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的电脑坏了，今天送到剧院修理。", "explanation": "这里应该用〈修理店〉。剧院是看戏和表演的地方，修电脑要去修理店。"}, {"text": "孩子发烧了，我们在剧院挂了急诊。", "explanation": "这里应该用〈医院〉。剧院是看戏和表演的地方，挂急诊要去医院。"}, {"text": "我每天在剧院里理发，理发师的手艺很好。", "explanation": "这里应该用〈理发店〉。剧院是看戏和表演的地方，理发要去理发店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们那天去了一只剧院，看了一场话剧。", "corrected_sentence": "我们那天去了一家剧院，看了一场话剧。", "error_description": "错误：“一只剧院”。正确：“一家剧院”。剧院是场所，量词用“家”或“座”，“只”用于动物，不能用于剧院。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天在一条剧院门口拍了照片。", "corrected_sentence": "她昨天在一家剧院门口拍了照片。", "error_description": "错误：“一条剧院”。正确：“一家剧院”。“条”用于细长的东西，剧院应使用量词“家”或“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
