INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "演出戏剧、歌舞等的场所，也指演出的团体。", "primary_collocate": null, "pronunciation": "jù yuàn", "ipa": "tɕy˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个剧院每年都会演出新戏。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家剧院的演员都很年轻。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家剧院下个月要来我们城市演出。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家剧院的歌舞表演很受欢迎。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个剧院有自己的演员和乐队。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "剧院的演员们正在台上练习舞蹈。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友在一家剧院工作，是舞台设计师。", "target_word": "剧院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家剧院去年演出了一百多场戏。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城里的剧院常常演出歌舞。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个剧院的演员要去国外演出。", "target_word": "剧院", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "家", "label": "量词"}, {"form": "歌剧院", "label": "复合词"}, {"form": "劇院", "label": "繁体"}], "register": "中性", "sense_fingerprint": "演出戏剧歌舞的场所，也指演出团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b978dc-3304-4b6f-922b-d87fbcdc36f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剧院", "is_correct": true, "explanation": "“剧院”是演出戏剧、歌舞的场所，与“演出新戏”一致。"}, {"text": "电影院", "is_correct": false, "explanation": "语义：“电影院”放映电影，不演出新戏，与句意不符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：“图书馆”是借阅书籍的地方，不能演出新戏。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“饭店”不作为演出新戏的场所，不与“演出新戏”搭配。"}], "explanations": {"剧院": "“剧院”是演出戏剧、歌舞的场所，与“演出新戏”一致。", "电影院": "语义：“电影院”放映电影，不演出新戏，与句意不符。", "图书馆": "语义：“图书馆”是借阅书籍的地方，不能演出新戏。", "饭店": "搭配：“饭店”不作为演出新戏的场所，不与“演出新戏”搭配。"}, "sentence_index": 0, "correct_answer": "剧院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在这家剧院看病，医生很认真。", "explanation": "这里应该用〈医院〉。剧院是演出场所，看病要去医院。"}, {"text": "这家剧院每天卖很多蔬菜，价格很便宜。", "explanation": "这里应该用〈菜市场〉或〈超市〉。剧院是演出场所，卖蔬菜要去菜市场。"}, {"text": "我妈妈每个月都在这家剧院存钱。", "explanation": "这里应该用〈银行〉。剧院是演出场所，存钱要去银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剧院", "is_correct": true, "explanation": "“剧院”是演出戏剧、歌舞的场所，与“舞台设计师”的工作场所一致。"}, {"text": "超市", "is_correct": false, "explanation": "语义：“超市”与“舞台设计师”的职业无关，句子语义不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”与舞台设计无关，句子语义自相矛盾。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“银行”不是舞台设计师的工作单位，不与“舞台设计师”搭配。"}], "explanations": {"剧院": "“剧院”是演出戏剧、歌舞的场所，与“舞台设计师”的工作场所一致。", "超市": "语义：“超市”与“舞台设计师”的职业无关，句子语义不通。", "医院": "语义：“医院”与舞台设计无关，句子语义自相矛盾。", "银行": "搭配：“银行”不是舞台设计师的工作单位，不与“舞台设计师”搭配。"}, "sentence_index": 6, "correct_answer": "剧院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在剧院买了一件新衣服。", "explanation": "这里应该用〈商店〉。剧院是演出场所，买衣服要去商店。"}, {"text": "我的车坏了，我把它开到剧院去修理。", "explanation": "这里应该用〈修理店〉。剧院是演出场所，修车要去修理店。"}, {"text": "妈妈在剧院里种了很多花。", "explanation": "这里应该用〈花园〉。剧院是演出场所，种花要在花园里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城里有一只剧院，去年演出了很多新戏。", "corrected_sentence": "城里有一家剧院，去年演出了很多新戏。", "error_description": "错误：“一只剧院”。正确：“一家剧院”。剧院用量词“家”或“座”，“只”不能用于剧院。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0bf8eaf-afd7-4b38-9a3d-cb96ad77dcd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
