INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93083, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "显是让人能看出来。", "primary_collocate": null, "pronunciation": "xiǎn", "ipa": "ɕiɛn", "syllable_count": 1, "sentences": [{"text": "这件白衣服太显脏了。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑色的衣服显瘦。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发型让你显年轻。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子穿着显腿长。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿红色很显白。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里放太多东西，会显小。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件大衣太长，显个子矮。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他留了胡子，显老。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种灯光下，皮肤显白。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你戴上这顶帽子显精神。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "显得", "label": "复合"}, {"form": "显眼", "label": "复合"}], "register": "口语", "sense_fingerprint": "让人看出某种样子，如显瘦、显老", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93083, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显", "is_correct": true, "explanation": "显（xiǎn，第三声）表示让人看出某种样子，如显瘦、显老，是正确答案。"}, {"text": "县", "is_correct": false, "explanation": "xiàn（第四声）与 xiǎn（第三声）声调不同，意思是县。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xiǎn（第三声）声调不同，意思是先。"}, {"text": "检", "is_correct": false, "explanation": "jiǎn 与 xiǎn 声母不同（j 与 x），声调相同，意思是检查。"}, {"text": "响", "is_correct": false, "explanation": "xiǎng 与 xiǎn 韵母不同（ang 与 an），声调相同，意思是响声。"}, {"text": "闲", "is_correct": false, "explanation": "xián（第二声）与 xiǎn（第三声）声调不同，意思是空闲。"}], "explanations": {"显": "显（xiǎn，第三声）表示让人看出某种样子，如显瘦、显老，是正确答案。", "县": "xiàn（第四声）与 xiǎn（第三声）声调不同，意思是县。", "先": "xiān（第一声）与 xiǎn（第三声）声调不同，意思是先。", "检": "jiǎn 与 xiǎn 声母不同（j 与 x），声调相同，意思是检查。", "响": "xiǎng 与 xiǎn 韵母不同（ang 与 an），声调相同，意思是响声。", "闲": "xián（第二声）与 xiǎn（第三声）声调不同，意思是空闲。"}, "sentence_index": null, "correct_answer": "显"}, "level_3": {"options": [{"text": "显", "is_correct": true, "explanation": "显：“太显脏了”表示让人看出脏的样子，符合句意。"}, {"text": "嫌", "is_correct": false, "explanation": "语义：“嫌”的主语须是人，白衣服不能嫌脏。"}, {"text": "爱", "is_correct": false, "explanation": "语义：“爱”指喜欢，衣服不会喜欢脏，句子说不通。"}, {"text": "讨厌", "is_correct": false, "explanation": "搭配：“讨厌”多用来表示人对人或事的厌恶，不能说白衣服“太讨厌脏了”。"}], "explanations": {"显": "显：“太显脏了”表示让人看出脏的样子，符合句意。", "嫌": "语义：“嫌”的主语须是人，白衣服不能嫌脏。", "爱": "语义：“爱”指喜欢，衣服不会喜欢脏，句子说不通。", "讨厌": "搭配：“讨厌”多用来表示人对人或事的厌恶，不能说白衣服“太讨厌脏了”。"}, "sentence_index": 0, "correct_answer": "显"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份数据显了一个大问题。", "explanation": "这里应该用〈显示〉。显示用于数据、结果等，表示让人看出；“显”只表示人或物显出某种样子，不带“问题”这类抽象宾语。"}, {"text": "这张标签显了价钱。", "explanation": "这里应该用〈标明〉。“标明”指写出或标出价钱等；“显”表示使人看出外在样子，不能说“显了价钱”。"}, {"text": "这件红衣服很显。", "explanation": "这里应该用〈显眼〉。“显”是动词，表示使人看出某种样子，不能单独作形容词说“很显”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93083, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显", "is_correct": true, "explanation": "显（xiǎn，第三声）表示让人看出某种样子，是正确答案。"}, {"text": "线", "is_correct": false, "explanation": "xiàn（第四声）与 xiǎn（第三声）声调不同，意思是线。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiǎn（第三声）声调不同，意思是鲜艳。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 xiǎn 声母不同（j 与 x），声调相同，意思是剪子、剪断。"}, {"text": "咸", "is_correct": false, "explanation": "xián（第二声）与 xiǎn（第三声）声调不同，意思是咸味。"}], "explanations": {"显": "显（xiǎn，第三声）表示让人看出某种样子，是正确答案。", "线": "xiàn（第四声）与 xiǎn（第三声）声调不同，意思是线。", "鲜": "xiān（第一声）与 xiǎn（第三声）声调不同，意思是鲜艳。", "剪": "jiǎn 与 xiǎn 声母不同（j 与 x），声调相同，意思是剪子、剪断。", "咸": "xián（第二声）与 xiǎn（第三声）声调不同，意思是咸味。"}, "sentence_index": null, "correct_answer": "显"}, "level_3": {"options": [{"text": "显", "is_correct": true, "explanation": "显：“显个子矮”表示让人看出个子矮，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物放进嘴里，不能表示让人看出个子矮，不说“吃个子矮”。"}, {"text": "彰", "is_correct": false, "explanation": "语域：“彰”偏书面，口语不说“彰个子矮”。"}, {"text": "瞧", "is_correct": false, "explanation": "语义：“瞧”是看的意思，不能使人显得个子矮。"}], "explanations": {"显": "显：“显个子矮”表示让人看出个子矮，符合句意。", "吃": "语义：“吃”指把食物放进嘴里，不能表示让人看出个子矮，不说“吃个子矮”。", "彰": "语域：“彰”偏书面，口语不说“彰个子矮”。", "瞧": "语义：“瞧”是看的意思，不能使人显得个子矮。"}, "sentence_index": 6, "correct_answer": "显"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一进门，就显了自己的体重。", "explanation": "这里应该用〈说出〉。“说出”指用话讲出来；“显”表示使人看出外在样子，不能用于“体重”这类数据。"}, {"text": "这把椅子显了三条腿。", "explanation": "这里应该用〈有〉。“有”表示具备或存在；“显”表示使人看出样子，不能说“显了三条腿”。"}, {"text": "这扇门显了一个把手。", "explanation": "这里应该用〈装〉。“装”指安装在某处；“显”表示使人看出样子，不能表示安装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件深色的外套显很瘦。", "corrected_sentence": "这件深色的外套显瘦。", "error_description": "错误形式“显很瘦”，正确形式“显瘦”（或“显得很瘦”）。“显”后直接接补语，中间不能插入“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件浅色的卫衣显。", "corrected_sentence": "这件浅色的卫衣显胖。", "error_description": "错误形式“这件浅色的卫衣显。”缺少补语，正确形式“这件浅色的卫衣显胖。”。“显”表示使人看出某种样子，后面要接出具体样子的补语（胖、瘦、老），不能单独作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93084, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐", "is_correct": true, "explanation": "隐：与“显”相反，指隐藏、不让人看见，与“显出”相对。"}, {"text": "扩大", "is_correct": false, "explanation": "扩大与“显”没有反义关系，只表示范围变大。"}, {"text": "跑", "is_correct": false, "explanation": "跑是动作动词，与“显”的任何义项都不构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声的动作，与“显”的任何义项都不构成反义。"}], "correct_answer": "隐", "explanations": {"隐": "隐：与“显”相反，指隐藏、不让人看见，与“显出”相对。", "扩大": "扩大与“显”没有反义关系，只表示范围变大。", "跑": "跑是动作动词，与“显”的任何义项都不构成反义。", "唱": "唱是发声的动作，与“显”的任何义项都不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93084, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐", "is_correct": true, "explanation": "隐：与“显”相反，指隐藏，与“显本事”相对。"}, {"text": "吃", "is_correct": false, "explanation": "吃与“显”没有反义关系。"}, {"text": "拆", "is_correct": false, "explanation": "拆与“显”的任何义项都不构成反义。"}, {"text": "烧", "is_correct": false, "explanation": "烧与“显”的任何义项都不构成反义。"}], "correct_answer": "隐", "explanations": {"隐": "隐：与“显”相反，指隐藏，与“显本事”相对。", "吃": "吃与“显”没有反义关系。", "拆": "拆与“显”的任何义项都不构成反义。", "烧": "烧与“显”的任何义项都不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93084, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表现出来；露出，使人看见。", "primary_collocate": null, "pronunciation": "xiǎn", "ipa": "ɕiɛn", "syllable_count": 1, "sentences": [{"text": "他的脸上显出了高兴的样子。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳一出来，山就显出了绿色。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事显出他很聪明。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的脸上显出一点疲惫。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在比赛里显一显本事。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，天空显出了彩虹。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一喝酒，脸就显出红色。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一亮，墙上的画都显出来了。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑的时候，脸上显出两个小酒窝。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想在人前显自己的本事。", "target_word": "显", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "显出", "label": "复合"}, {"form": "显得", "label": "复合"}], "register": "通用", "sense_fingerprint": "表现、露出，使人看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de94bd89-19e3-4337-868c-ae9af5a910e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显", "is_correct": true, "explanation": "显（xiǎn，第三声）表示表现出来、露出，是正确答案。"}, {"text": "线", "is_correct": false, "explanation": "xiàn（第四声）与 xiǎn（第三声）声调不同，意思是线。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xiǎn（第三声）声调不同，意思是先。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 xiǎn 声母不同（j 与 x），声调相同，意思是剪子、剪断。"}, {"text": "响", "is_correct": false, "explanation": "xiǎng 与 xiǎn 韵母不同（ang 与 an），声调相同，意思是响声。"}, {"text": "咸", "is_correct": false, "explanation": "xián（第二声）与 xiǎn（第三声）声调不同，意思是咸味。"}], "explanations": {"显": "显（xiǎn，第三声）表示表现出来、露出，是正确答案。", "线": "xiàn（第四声）与 xiǎn（第三声）声调不同，意思是线。", "先": "xiān（第一声）与 xiǎn（第三声）声调不同，意思是先。", "剪": "jiǎn 与 xiǎn 声母不同（j 与 x），声调相同，意思是剪子、剪断。", "响": "xiǎng 与 xiǎn 韵母不同（ang 与 an），声调相同，意思是响声。", "咸": "xián（第二声）与 xiǎn（第三声）声调不同，意思是咸味。"}, "sentence_index": null, "correct_answer": "显"}, "level_3": {"options": [{"text": "显", "is_correct": true, "explanation": "显：“显出”表示表现出来、露出，符合句意。"}, {"text": "长", "is_correct": false, "explanation": "语义：脸上长出的是皮肤、毛发等，不会长出高兴的样子。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃出”多指吃到某种味道或东西，不说吃出表情。"}, {"text": "钓", "is_correct": false, "explanation": "搭配：“钓”指用钩子取鱼等，不能用来表示露出表情。"}], "explanations": {"显": "显：“显出”表示表现出来、露出，符合句意。", "长": "语义：脸上长出的是皮肤、毛发等，不会长出高兴的样子。", "吃": "搭配：“吃出”多指吃到某种味道或东西，不说吃出表情。", "钓": "搭配：“钓”指用钩子取鱼等，不能用来表示露出表情。"}, "sentence_index": 0, "correct_answer": "显"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话显出一个秘密。", "explanation": "这里应该用〈透露〉。透露指把消息或秘密说出来；“显出”只表示外在样子或迹象露出来，不能用于秘密。"}, {"text": "他向大家显出了新产品。", "explanation": "这里应该用〈展示〉。展示指主动拿出来让人看；“显出”指事物自然露出、呈现出来，不能表示有意拿出给人看。"}, {"text": "他不小心显出了公司的机密。", "explanation": "这里应该用〈泄露〉。泄露指不该传出去的机密被传出；“显出”不能表示泄密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93084, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显", "is_correct": true, "explanation": "显（xiǎn，第三声）表示表现出来、露出，是正确答案。"}, {"text": "县", "is_correct": false, "explanation": "xiàn（第四声）与 xiǎn（第三声）声调不同，意思是县。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiǎn（第三声）声调不同，意思是鲜艳。"}, {"text": "检", "is_correct": false, "explanation": "jiǎn 与 xiǎn 声母不同（j 与 x），声调相同，意思是检查。"}, {"text": "闲", "is_correct": false, "explanation": "xián（第二声）与 xiǎn（第三声）声调不同，意思是空闲。"}], "explanations": {"显": "显（xiǎn，第三声）表示表现出来、露出，是正确答案。", "县": "xiàn（第四声）与 xiǎn（第三声）声调不同，意思是县。", "鲜": "xiān（第一声）与 xiǎn（第三声）声调不同，意思是鲜艳。", "检": "jiǎn 与 xiǎn 声母不同（j 与 x），声调相同，意思是检查。", "闲": "xián（第二声）与 xiǎn（第三声）声调不同，意思是空闲。"}, "sentence_index": null, "correct_answer": "显"}, "level_3": {"options": [{"text": "显", "is_correct": true, "explanation": "显：“显出红色”表示脸上露出红色，符合句意。"}, {"text": "吐", "is_correct": false, "explanation": "语义：“吐”指从口中排出东西，脸上不会吐出颜色，句子说不通。"}, {"text": "挤", "is_correct": false, "explanation": "语义：“挤”指把东西压出来，脸上不会被挤出颜色。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”指采摘，不能说“摘出颜色”。"}], "explanations": {"显": "显：“显出红色”表示脸上露出红色，符合句意。", "吐": "语义：“吐”指从口中排出东西，脸上不会吐出颜色，句子说不通。", "挤": "语义：“挤”指把东西压出来，脸上不会被挤出颜色。", "摘": "搭配：“摘”指采摘，不能说“摘出颜色”。"}, "sentence_index": 6, "correct_answer": "显"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长在大会上显出了比赛结果。", "explanation": "这里应该用〈宣布〉。宣布指正式公开说出消息；“显出”指外在表现，不能用于公布结果。"}, {"text": "老人向我显出了往事。", "explanation": "这里应该用〈诉说〉。诉说指把往事讲给别人听；“显出”指外在样子或迹象露出来，不能对人说出往事。"}, {"text": "他显出了错误。", "explanation": "这里应该用〈承认〉。承认指认可自己的错误；“显出”不能用于错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的眼睛里显得出一丝笑意。", "corrected_sentence": "他的眼睛里显出了一丝笑意。", "error_description": "错误形式“显得出”。“显得”表示看起来，后接形容词或动词短语，不能直接接“出一丝笑意”；此处应用动词“显出”，表示露出、出现，并用“显出了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "远处的山上显了一座小屋。", "corrected_sentence": "远处的山上显出了一座小屋。", "error_description": "错误形式“显了一座小屋”，正确形式“显出了一座小屋”。表示露出、出现的意思要用“显出”，省去“出”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94e4876a-8c77-41e9-8d40-a89b28bf79a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
