INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93085, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "加和是几个数加起来得到的数。", "primary_collocate": null, "pronunciation": "jiā hé", "ipa": "tɕia˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这三个数的加和是一百。", "target_word": "加和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们算出四个数的加和。", "target_word": "加和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把每一行的加和写在最后。", "target_word": "加和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个数的加和比十大。", "target_word": "加和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "表里每一列的加和都是对的。", "target_word": "加和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算错了这五个数的加和。", "target_word": "加和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到五的加和是十五。", "target_word": "加和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些成绩的加和是多少？", "target_word": "加和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加和等于二十，你再检查一下。", "target_word": "加和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明很快就算出了加和。", "target_word": "加和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "几个数相加得到的结果，即总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd75ca80b-1f26-4b15-81d3-10584f1de521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93085, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加和", "is_correct": true, "explanation": "正确。加和指几个数相加得到的数，“这三个数的加和是一百”说的正是三个数相加的结果。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数指人的数量，“这三个数”是数字，不能说人数。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或动物活了多久，数字没有年龄。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：相貌指人的容貌，不能用来说数字。"}], "explanations": {"加和": "正确。加和指几个数相加得到的数，“这三个数的加和是一百”说的正是三个数相加的结果。", "人数": "语义：人数指人的数量，“这三个数”是数字，不能说人数。", "年龄": "语义：年龄指人或动物活了多久，数字没有年龄。", "相貌": "体貌：相貌指人的容貌，不能用来说数字。"}, "sentence_index": 0, "correct_answer": "加和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的加和是灰色的。", "explanation": "这里应该用〈颜色〉。加和指数相加的结果，不能用来说猫的颜色。"}, {"text": "他的加和是三十岁。", "explanation": "这里应该用〈年龄〉。加和只指数相加的结果，不能用来说人的岁数。"}, {"text": "这双鞋的加和是四十二码。", "explanation": "这里应该用〈尺码〉。加和指数相加的结果，说鞋子的大小要用尺码或码数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加和", "is_correct": true, "explanation": "正确。“一到五的加和是十五”说的是这些数相加的结果。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人或物的高度，一到五这些数字没有身高。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动的报酬，数字不会领工资，“一到五的工资是十五”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来说数字。"}], "explanations": {"加和": "正确。“一到五的加和是十五”说的是这些数相加的结果。", "身高": "语义：身高指人或物的高度，一到五这些数字没有身高。", "工资": "语义：工资是劳动的报酬，数字不会领工资，“一到五的工资是十五”说不通。", "身材": "体貌：身材指人的体形，不能用来说数字。"}, "sentence_index": 6, "correct_answer": "加和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的加和很咸。", "explanation": "这里应该用〈味道〉。加和指数相加的结果，不能用来说汤的咸淡。"}, {"text": "这个孩子的加和是一米二。", "explanation": "这里应该用〈身高〉。加和指数相加的结果，不能用来说人有多高。"}, {"text": "今天的加和是三十度。", "explanation": "这里应该用〈温度〉。加和指数相加的结果，说冷热要用温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个数的加和了是十五。", "corrected_sentence": "这几个数的加和是十五。", "error_description": "错误在“加和”后面加了“了”。“加和”是名词，不能带“了”；应说“这几个数的加和是十五”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这组数的一条加和算了两遍。", "corrected_sentence": "我把这组数的加和算了两遍。", "error_description": "错误在“加和”前面加了量词“一条”。加和不用“条”，应直接说“这组数的加和”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
