INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93088, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不加区别；不区分。", "primary_collocate": null, "pronunciation": "bù fēn", "ipa": "pu⁵¹ fən⁵⁵", "syllable_count": 2, "sentences": [{"text": "这家店不分大人小孩，都要买票。", "target_word": "不分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作起来不分白天黑夜。", "target_word": "不分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生不分穷人富人，都认真看病。", "target_word": "不分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生不分男女，一样关心。", "target_word": "不分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不分季节，天天都有人来玩。", "target_word": "不分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不分你我，什么都一起用。", "target_word": "不分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱心不分国家，只要有需要就帮。", "target_word": "不分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律面前，不分高低，人人平等。", "target_word": "不分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不分场合，随便大声说话。", "target_word": "不分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨来了，大家不分男女老少，一起把衣服收进屋。", "target_word": "不分", "complexity_tier": "T3", "furigana": "bù fēn", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "对不同的人或事一视同仁，不加区别对待", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df81c267-6b39-4d12-95ab-3643a04c33bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不分", "is_correct": true, "explanation": "不分：不加区别，与“大人小孩都要买票”的统一收费相符。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：“赶走”大人小孩与后半句“都要买票”的意思矛盾，句意不通。"}, {"text": "免除", "is_correct": false, "explanation": "搭配：“免除”的对象是费用或义务，不能直接以人作宾语说“免除大人小孩”。"}, {"text": "歧视", "is_correct": false, "explanation": "语义：“歧视”含有区别对待、看低某些人的意思，与“都要买票”的平等收费矛盾。"}], "explanations": {"不分": "不分：不加区别，与“大人小孩都要买票”的统一收费相符。", "赶走": "语义：“赶走”大人小孩与后半句“都要买票”的意思矛盾，句意不通。", "免除": "搭配：“免除”的对象是费用或义务，不能直接以人作宾语说“免除大人小孩”。", "歧视": "语义：“歧视”含有区别对待、看低某些人的意思，与“都要买票”的平等收费矛盾。"}, "sentence_index": 0, "correct_answer": "不分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生要不分轻症和重症，安排不同的治疗。", "explanation": "这里应该用〈区分〉。“不分”表示一视同仁、不加区别；后文要“安排不同的治疗”，前后矛盾。"}, {"text": "两队踢到最后，还是不分胜负。", "explanation": "这里是“分不出高下”的意思，指比赛双方难分输赢；本词在这里不表示“不加区别、一视同仁”。"}, {"text": "裁判不分主队和客队，总是判主队赢。", "explanation": "这里应该用〈偏袒〉。“不分”表示公平、一视同仁，与“总是判主队赢”的偏向矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不分", "is_correct": true, "explanation": "不分：不加区别，符合“爱心不分国家”的意思。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：挑选国家意味着有所选择，与后半句“只要有需要就帮”矛盾。"}, {"text": "排斥", "is_correct": false, "explanation": "语义：“排斥”国家与“只要有需要就帮”的态度矛盾，句意不通。"}, {"text": "挑", "is_correct": false, "explanation": "语域：“挑”偏口语，与这句的书面语气不合；“爱心挑国家”也与“只要有需要就帮”矛盾。"}], "explanations": {"不分": "不分：不加区别，符合“爱心不分国家”的意思。", "挑选": "语义：挑选国家意味着有所选择，与后半句“只要有需要就帮”矛盾。", "排斥": "语义：“排斥”国家与“只要有需要就帮”的态度矛盾，句意不通。", "挑": "语域：“挑”偏口语，与这句的书面语气不合；“爱心挑国家”也与“只要有需要就帮”矛盾。"}, "sentence_index": 6, "correct_answer": "不分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感冒了，鼻子不通，常常不分香臭。", "explanation": "这里指闻不出气味的好坏，是“分辨不出”的意思；本词在这里不表示“不加区别、一视同仁”。"}, {"text": "他的味觉不太好，吃东西的时候不分甜咸。", "explanation": "这里指尝不出甜和咸，是“分辨不出”的意思，不是“不加区别”的意思。"}, {"text": "他一喝酒就不分东南西北，连门都找不到。", "explanation": "这里是“分不清方向”的意思，指醉后辨不出东南西北；本词在这里不表示“不加区别、一视同仁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店不分着老少，都要收同样的钱。", "corrected_sentence": "这家店不分老少，都要收同样的钱。", "error_description": "“不分”后不能加动态助词“着”，应说“不分老少”；“不分着老少”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班里不分了男女，大家都一起打扫。", "corrected_sentence": "班里不分男女，大家都一起打扫。", "error_description": "“不分”是否定的动作，不能再加“了”，应说“不分男女”；“不分了”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
