INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "象棋中黑方最小的棋子，过河前只能向前走，过河后也可以左右走。", "primary_collocate": null, "pronunciation": "zú", "ipa": "tsu˧˥", "syllable_count": 1, "sentences": [{"text": "象棋里红方有兵，黑方有卒。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑方还没过河的卒只能向前走。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卒过了河，就可以左右走。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一个卒吃掉了对方的马。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘棋里，我只剩下一个卒。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在象棋里，卒是黑方最小的棋子。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卒虽然小，走到底线也有用。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先把卒向前走了一步。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方的卒挡住了我的车。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，下棋时别小看一个卒。", "target_word": "卒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小卒", "label": "复合"}], "register": "中性", "sense_fingerprint": "象棋里黑方最小的棋子，过河前只能向前走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecaec501-a7ea-4216-b684-7b1fdd95ce2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卒", "is_correct": true, "explanation": "正确答案：卒（zú），即听到的读音。"}, {"text": "竹", "is_correct": false, "explanation": "zhú（第二声）与 zú 的声母不同（zh/z），意思是竹子。"}, {"text": "组", "is_correct": false, "explanation": "zǔ（第三声）与 zú 声调不同，意思是组织。"}, {"text": "祖", "is_correct": false, "explanation": "zǔ（第三声）与 zú 声调不同，意思是祖先。"}, {"text": "烛", "is_correct": false, "explanation": "zhú（第二声）与 zú 声母不同（zh/z），意思是蜡烛。"}], "explanations": {"卒": "正确答案：卒（zú），即听到的读音。", "竹": "zhú（第二声）与 zú 的声母不同（zh/z），意思是竹子。", "组": "zǔ（第三声）与 zú 声调不同，意思是组织。", "祖": "zǔ（第三声）与 zú 声调不同，意思是祖先。", "烛": "zhú（第二声）与 zú 声母不同（zh/z），意思是蜡烛。"}, "sentence_index": null, "correct_answer": "卒"}, "level_3": {"options": [{"text": "卒", "is_correct": true, "explanation": "卒：象棋中黑方最小的棋子，与“黑方有”的所指相符。"}, {"text": "士兵", "is_correct": false, "explanation": "语义：“士兵”指军人，不是象棋中的棋子，与“象棋里……有”的语境不符。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：“棋盘”是棋具的底板，不是棋子，不能说“黑方有棋盘”作为棋子。"}, {"text": "将士", "is_correct": false, "explanation": "语域：“将士”是书面词，指一群军人，与口语化的棋局叙述不搭。"}], "explanations": {"卒": "卒：象棋中黑方最小的棋子，与“黑方有”的所指相符。", "士兵": "语义：“士兵”指军人，不是象棋中的棋子，与“象棋里……有”的语境不符。", "棋盘": "语义：“棋盘”是棋具的底板，不是棋子，不能说“黑方有棋盘”作为棋子。", "将士": "语域：“将士”是书面词，指一群军人，与口语化的棋局叙述不搭。"}, "sentence_index": 0, "correct_answer": "卒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "卒可以走日字。", "explanation": "这里应该用〈马〉。马走日字，卒只能向前走，过河后才能横走，不走日字。"}, {"text": "卒只能走田字。", "explanation": "这里应该用〈象〉。象走田字，卒过河前只能向前，不走田字。"}, {"text": "棋盘上还剩一匹卒。", "explanation": "这里应该用〈个〉。卒是棋子，应配“个”；“匹”是马等牲畜的量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "卒", "is_correct": true, "explanation": "正确答案：卒（zú），即听到的读音。"}, {"text": "租", "is_correct": false, "explanation": "zū（第一声）与 zú 声调不同，意思是租用。"}, {"text": "逐", "is_correct": false, "explanation": "zhú（第二声）与 zú 声母不同（zh/z），意思是追赶。"}, {"text": "阻", "is_correct": false, "explanation": "zǔ（第三声）与 zú 声调不同，意思是阻挡。"}], "explanations": {"卒": "正确答案：卒（zú），即听到的读音。", "租": "zū（第一声）与 zú 声调不同，意思是租用。", "逐": "zhú（第二声）与 zú 声母不同（zh/z），意思是追赶。", "阻": "zǔ（第三声）与 zú 声调不同，意思是阻挡。"}, "sentence_index": null, "correct_answer": "卒"}, "level_3": {"options": [{"text": "卒", "is_correct": true, "explanation": "卒：最小的棋子，能过河后左右走，与“虽然小，走到底线也有用”相符。"}, {"text": "山", "is_correct": false, "explanation": "体貌：“山”体积庞大，与“虽然小”的描写正相反。"}, {"text": "脚", "is_correct": false, "explanation": "语义：“脚”是身体部位，不能“走到底线”作为棋子。"}, {"text": "草", "is_correct": false, "explanation": "语义：“草”是植物，不能“走到底线”，也不是棋子。"}], "explanations": {"卒": "卒：最小的棋子，能过河后左右走，与“虽然小，走到底线也有用”相符。", "山": "体貌：“山”体积庞大，与“虽然小”的描写正相反。", "脚": "语义：“脚”是身体部位，不能“走到底线”作为棋子。", "草": "语义：“草”是植物，不能“走到底线”，也不是棋子。"}, "sentence_index": 6, "correct_answer": "卒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "黑方的卒守住了宫。", "explanation": "这里应该用〈士〉。守宫的是士，卒不能进入九宫。"}, {"text": "卒要隔一个子才能吃子。", "explanation": "这里应该用〈炮〉。炮要隔一个子才能吃子；卒只能向前走一步吃子，不能隔子。"}, {"text": "我的卒是一位将军。", "explanation": "这里应该用〈将〉。卒是黑方最小的棋子，不是统帅黑方的将。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棋盘上黑方还剩两条卒。", "corrected_sentence": "棋盘上黑方还剩两个卒。", "error_description": "错误：量词“条”用于细长的东西，卒作为棋子应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先把卒的往前推了一步。", "corrected_sentence": "我先把卒往前推了一步。", "error_description": "错误：“卒”与动词之间多加了“的”。“往前”作状语，直接放在动词前，不加“的”，应说「我先把卒往前推了一步」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
