INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93091, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主持人是在台上带着大家一起做事的人。", "primary_collocate": null, "pronunciation": "zhǔ chí rén", "ipa": "ʈʂu˨˩˦ ʈʂʰɨ˧˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "台上的主持人笑着和大家打招呼。", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主持人说：“请大家安静，我们开始吧。”", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场活动由一位年轻的主持人主持。", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王是我们班联欢会的主持人。", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主持人请每个小朋友上台唱一首歌。", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的主持人会让大家都觉得高兴。", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，主持人宣布了结果。", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场音乐会的主持人是一位老演员。", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主持人把话筒递给了坐在前面的女孩。", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次当主持人，心里有点儿紧张。", "target_word": "主持人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "节目主持人", "label": "复合词"}, {"form": "婚礼主持人", "label": "复合词"}], "register": "中性", "sense_fingerprint": "在台上带领大家做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4de93c19-9eac-449b-96e7-31ed056a2812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主持人", "is_correct": true, "explanation": "正确：“主持人”在台上带领大家打招呼，符合句中语境。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是人，不会笑着和大家打招呼。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“笑着和大家打招呼”需要有生命的人作主语，“花园”不能这样搭配。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“笑”和“打招呼”需要有意识的施事，“石头”不能作主语。"}], "explanations": {"主持人": "正确：“主持人”在台上带领大家打招呼，符合句中语境。", "蛋糕": "语义：蛋糕不是人，不会笑着和大家打招呼。", "花园": "搭配：“笑着和大家打招呼”需要有生命的人作主语，“花园”不能这样搭配。", "石头": "配价：“笑”和“打招呼”需要有意识的施事，“石头”不能作主语。"}, "sentence_index": 0, "correct_answer": "主持人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位主持人给我检查了牙齿。", "explanation": "这里应该用〈医生〉。主持人在台上主持活动，不做检查牙齿的工作。"}, {"text": "王叔叔是我们家的主持人，每天早上开车送我们。", "explanation": "这里应该用〈司机〉。主持人指主持活动的人，不负责开车。"}, {"text": "这次比赛的主持人负责判断每个动作是否合格，还给选手打分。", "explanation": "这里应该用〈裁判〉。主持人是在台上主持活动的人，不负责判断动作和给选手打分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主持人", "is_correct": true, "explanation": "正确：“主持人”可以宣布比赛结果，符合句中语境。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不能宣布结果。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“宣布”需要有意识的施事，“桌子”不能作主语。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能宣布比赛的结果。"}], "explanations": {"主持人": "正确：“主持人”可以宣布比赛结果，符合句中语境。", "雨": "语义：雨不能宣布结果。", "桌子": "配价：“宣布”需要有意识的施事，“桌子”不能作主语。", "饼干": "语义：饼干不能宣布比赛的结果。"}, "sentence_index": 6, "correct_answer": "主持人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子是我们班的主持人。", "explanation": "〈主持人〉是指人的名词，指在台上带领大家做事的人，这里误用来指物品。这里应该用〈座位〉之类的物品名词。"}, {"text": "工地上的主持人负责搬砖，每天都很辛苦。", "explanation": "这里应该用〈工人〉。主持人是在台上带领大家做事的人，不负责搬砖。"}, {"text": "我们家请了一位主持人，专门照顾孩子。", "explanation": "这里应该用〈保姆〉。主持人是在台上带领大家做事的人，不负责照顾孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班请了一个很好主持人。", "corrected_sentence": "我们班请了一个很好的主持人。", "error_description": "错误：“很好”和名词“主持人”之间漏了“的”。正确应为“一个很好的主持人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是班里最好的一只主持人。", "corrected_sentence": "她是班里最好的一位主持人。", "error_description": "错误：“主持人”指人，量词应用“位”或“个”，不能用“只”（“只”多用于动物）。正确应为“班里最好的一位主持人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93093, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正比", "is_correct": true, "explanation": "正确。正比是两个量同增同减，与反比方向相反，是对立关系。"}, {"text": "函数", "is_correct": false, "explanation": "函数是数学概念，但与反比没有对立关系。"}, {"text": "方程", "is_correct": false, "explanation": "方程是数学中的等式，与反比不构成反义关系。"}, {"text": "概率", "is_correct": false, "explanation": "概率表示可能性大小，与反比不是反义词。"}], "correct_answer": "正比", "explanations": {"正比": "正确。正比是两个量同增同减，与反比方向相反，是对立关系。", "函数": "函数是数学概念，但与反比没有对立关系。", "方程": "方程是数学中的等式，与反比不构成反义关系。", "概率": "概率表示可能性大小，与反比不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93093, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正比", "is_correct": true, "explanation": "正确。正比是两个量同增同减，与反比方向相反，是对立关系。"}, {"text": "几何", "is_correct": false, "explanation": "几何是研究图形的学科，与反比不构成反义关系。"}, {"text": "坐标", "is_correct": false, "explanation": "坐标是确定位置的数值组，与反比没有对立关系。"}, {"text": "指数", "is_correct": false, "explanation": "指数表示幂的次数，与反比不是反义词。"}], "correct_answer": "正比", "explanations": {"正比": "正确。正比是两个量同增同减，与反比方向相反，是对立关系。", "几何": "几何是研究图形的学科，与反比不构成反义关系。", "坐标": "坐标是确定位置的数值组，与反比没有对立关系。", "指数": "指数表示幂的次数，与反比不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93093, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "反比是一个数变大，另一个数就变小。", "primary_collocate": null, "pronunciation": "fǎn bǐ", "ipa": "fan˨˩ pi˨˩", "syllable_count": 2, "sentences": [{"text": "速度越快，时间越短，两者成反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这两个数成反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路程不变，速度和时间成反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个数变大，另一个数变小，这就是反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天学了什么是反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题考的是反比，不是正比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学书上有很多反比的例子。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说出一个反比的例子吗？", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个数成反比，一个大另一个就小。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人越多，做完的时间越短，这是反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反比例", "label": "复合"}], "register": "书面", "sense_fingerprint": "数学中两个数一个变大、另一个变小的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93093, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反比", "is_correct": true, "explanation": "正确。速度越快、时间越短，两者是一增一减的反比关系。"}, {"text": "正比", "is_correct": false, "explanation": "语义：正比表示两个量同增同减，与句中“速度越快、时间越短”的反向变化相矛盾。"}, {"text": "比值", "is_correct": false, "explanation": "搭配：“成”后接的是关系名词，比值是一个数，不能说“两者成比值”。"}, {"text": "比重", "is_correct": false, "explanation": "搭配：比重指部分占整体的比例，不能用于“两者成……”这一关系句式。"}], "explanations": {"反比": "正确。速度越快、时间越短，两者是一增一减的反比关系。", "正比": "语义：正比表示两个量同增同减，与句中“速度越快、时间越短”的反向变化相矛盾。", "比值": "搭配：“成”后接的是关系名词，比值是一个数，不能说“两者成比值”。", "比重": "搭配：比重指部分占整体的比例，不能用于“两者成……”这一关系句式。"}, "sentence_index": 0, "correct_answer": "反比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一个数变大，另一个数也变大，这就是反比。", "explanation": "这里应该用〈正比〉。反比指一增一减，两数同增同减要用正比。"}, {"text": "今年的销售额反比增长了百分之二十。", "explanation": "这里应该用〈同比〉。反比描述一增一减的关系，不说“反比增长”；与去年相比增长要说同比。"}, {"text": "这两个班的男女反比是三比二。", "explanation": "这里应该用〈比例〉。反比指一个量增大另一个量减小的关系，不是两数的比值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反比", "is_correct": true, "explanation": "正确。反比是一个数变大、另一个变小的数学关系，数学书上有很多这样的例子。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：数学书讲的是数学概念，不会以诗歌作为例子。"}, {"text": "美食", "is_correct": false, "explanation": "语义：数学书上讲的是数学规律，不会有美食的例子。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“……的例子”需要抽象的规律或概念，风景不能作为例子的内容。"}], "explanations": {"反比": "正确。反比是一个数变大、另一个变小的数学关系，数学书上有很多这样的例子。", "诗歌": "语义：数学书讲的是数学概念，不会以诗歌作为例子。", "美食": "语义：数学书上讲的是数学规律，不会有美食的例子。", "风景": "搭配：“……的例子”需要抽象的规律或概念，风景不能作为例子的内容。"}, "sentence_index": 6, "correct_answer": "反比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两组的工作效率形成了鲜明的反比。", "explanation": "这里应该用〈对比〉。形成鲜明对比要用对比，反比指两个量一增一减的关系。"}, {"text": "这台机器的产量越高，耗电量越大，两者是反比关系。", "explanation": "这里应该用〈正比〉。产量与耗电量同向变化，应说正比；反比指一增一减。"}, {"text": "甲乙两地的人口反比是五比三。", "explanation": "这里应该用〈比值〉。反比指两个量一增一减的关系，两地人口的比值要说比值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个量反比，一个变大，另一个就变小。", "corrected_sentence": "两个量成反比，一个变大，另一个就变小。", "error_description": "搭配错误：表示两量的关系要说「成反比」，省略「成」后「反比」不能直接作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个量成反比，一个变大，另一个也跟着变大。", "corrected_sentence": "这两个量成反比，一个变大，另一个就变小。", "error_description": "语义错误：反比指一增一减，「另一个也跟着变大」是同增的正比关系，应说「另一个就变小」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93094, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正比", "is_correct": true, "explanation": "正确。正比是两个量同增同减，与反比方向相反，是对立关系。"}, {"text": "电压", "is_correct": false, "explanation": "电压是物理量，与反比没有对立关系。"}, {"text": "电流", "is_correct": false, "explanation": "电流是物理量，与反比不构成反义关系。"}, {"text": "电阻", "is_correct": false, "explanation": "电阻是物理量，与反比不是反义词。"}], "correct_answer": "正比", "explanations": {"正比": "正确。正比是两个量同增同减，与反比方向相反，是对立关系。", "电压": "电压是物理量，与反比没有对立关系。", "电流": "电流是物理量，与反比不构成反义关系。", "电阻": "电阻是物理量，与反比不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93094, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正比", "is_correct": true, "explanation": "正确。正比是两个量同增同减，与反比方向相反，是对立关系。"}, {"text": "压强", "is_correct": false, "explanation": "压强是物理量，与反比没有对立关系。"}, {"text": "密度", "is_correct": false, "explanation": "密度是物理量，与反比不构成反义关系。"}, {"text": "面积", "is_correct": false, "explanation": "面积是几何量，与反比不是反义词。"}], "correct_answer": "正比", "explanations": {"正比": "正确。正比是两个量同增同减，与反比方向相反，是对立关系。", "压强": "压强是物理量，与反比没有对立关系。", "密度": "密度是物理量，与反比不构成反义关系。", "面积": "面积是几何量，与反比不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个量中一个增大另一个按比例减小的关系。", "primary_collocate": null, "pronunciation": "fǎn bǐ", "ipa": "fan˨˩ pi˨˩", "syllable_count": 2, "sentences": [{"text": "在压力不变时，压强和受力面积成反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电压不变，电阻和电流成反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公式表示两个量之间的反比关系。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理课上我们学过反比关系。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们画了一张表示反比的图。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩和玩游戏的时间成反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人数和每人分到的蛋糕成反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个量的变化成反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们找出生活中的反比关系。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格和买的人数不一定成反比。", "target_word": "反比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反比例", "label": "复合"}], "register": "书面", "sense_fingerprint": "两个量之间一增一减、按比例变化的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反比", "is_correct": true, "explanation": "正确。压力不变时，压强与受力面积是一增一减的反比关系。"}, {"text": "正比", "is_correct": false, "explanation": "语义：压力不变时，受力面积越大，压强越小，两者是反比，正比说同增同减，与此不符。"}, {"text": "比重", "is_correct": false, "explanation": "搭配：“成”后要接关系名词，比重表示部分占整体的比例，不能说“成比重”。"}, {"text": "频率", "is_correct": false, "explanation": "搭配：“成”后接的应是“反比”“正比”这类关系名词，频率是次数，不能说“成频率”。"}], "explanations": {"反比": "正确。压力不变时，压强与受力面积是一增一减的反比关系。", "正比": "语义：压力不变时，受力面积越大，压强越小，两者是反比，正比说同增同减，与此不符。", "比重": "搭配：“成”后要接关系名词，比重表示部分占整体的比例，不能说“成比重”。", "频率": "搭配：“成”后接的应是“反比”“正比”这类关系名词，频率是次数，不能说“成频率”。"}, "sentence_index": 0, "correct_answer": "反比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个量同时增大，它们成反比。", "explanation": "这里应该用〈正比〉。反比指一增一减，两个量同增同减要用正比。"}, {"text": "今年的利润反比增长了百分之十。", "explanation": "这里应该用〈同比〉。反比描述一增一减的关系，不说“反比增长”；与去年相比增长要说同比。"}, {"text": "地图上的反比是一比一万。", "explanation": "这里应该用〈比例尺〉。反比指两个量一增一减的关系，地图上的比值要说比例尺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反比", "is_correct": true, "explanation": "正确。人数越多，每人分到的越少，两者成反比。"}, {"text": "比值", "is_correct": false, "explanation": "配价：“成”要求带关系名词，比值是具体数值，不能充当“成”后表示两者关系的成分。"}, {"text": "倍数", "is_correct": false, "explanation": "搭配：“成倍数”不能表示两个量的关系，倍数指倍的数目。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“成”后接关系名词，颜色是事物的属性，不能说“成颜色”。"}], "explanations": {"反比": "正确。人数越多，每人分到的越少，两者成反比。", "比值": "配价：“成”要求带关系名词，比值是具体数值，不能充当“成”后表示两者关系的成分。", "倍数": "搭配：“成倍数”不能表示两个量的关系，倍数指倍的数目。", "颜色": "搭配：“成”后接关系名词，颜色是事物的属性，不能说“成颜色”。"}, "sentence_index": 6, "correct_answer": "反比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两种产品的价格形成鲜明的反比。", "explanation": "这里应该用〈对比〉。形成鲜明对比要用对比，反比指两个量一增一减的关系。"}, {"text": "气温越高，冰淇淋卖得越多，两者是反比关系。", "explanation": "这里应该用〈正比〉。气温高、冰淇淋卖得多是同向变化，应说正比；反比指一增一减。"}, {"text": "两个数的反比是二分之一。", "explanation": "这里应该用〈比值〉。反比是两个量一增一减的关系，两数相除的结果要说比值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "气体温度不变时，压强和体积反比。", "corrected_sentence": "气体温度不变时，压强和体积成反比。", "error_description": "搭配错误：表示两量的关系要说「成反比」，省略「成」后「反比」不能直接作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个变量的乘积保持不变，一个变大，另一个也变大，它们成反比。", "corrected_sentence": "这两个变量的乘积保持不变，一个变大，另一个就变小，它们成反比。", "error_description": "语义错误：乘积保持不变即一增一减，「另一个也变大」是同增，与「成反比」矛盾，应改为「另一个就变小」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
