INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93095, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事项是一件一件要做的事。", "primary_collocate": null, "pronunciation": "shì xiàng", "ipa": "ʂɻ̩˥˩ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我把今天要做的事项写在本子上。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本周的事项很多，我感到有些疲惫。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每做完一个事项，他就画一个圈。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里记着明天的三个事项。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先做最急的事项。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天早上都会看一遍事项。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸上有五个事项，你来选一个。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发前的事项我都做完了。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作事项繁多，他忙得无暇用餐。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把事项按时间顺序排列。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "待办事项", "label": "复合词"}, {"form": "注意事项", "label": "复合词"}, {"form": "重要事项", "label": "复合词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "待办的、一件一件要完成的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459873f2-15f3-4c94-997f-d7fd10d4860f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93095, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事项", "is_correct": true, "explanation": "事项：shì xiàng，要做的事情。"}, {"text": "四项", "is_correct": false, "explanation": "sì xiàng 与 shì xiàng 声母不同（s／sh），意思是“四项”。"}, {"text": "十项", "is_correct": false, "explanation": "shí xiàng 与 shì xiàng 声调不同（第二声与第四声），意思是“十项”。"}, {"text": "试想", "is_correct": false, "explanation": "shì xiǎng 与 shì xiàng 声调不同，意思是“试想”。"}], "explanations": {"事项": "事项：shì xiàng，要做的事情。", "四项": "sì xiàng 与 shì xiàng 声母不同（s／sh），意思是“四项”。", "十项": "shí xiàng 与 shì xiàng 声调不同（第二声与第四声），意思是“十项”。", "试想": "shì xiǎng 与 shì xiàng 声调不同，意思是“试想”。"}, "sentence_index": null, "correct_answer": "事项"}, "level_3": {"options": [{"text": "事项", "is_correct": true, "explanation": "事项：今天要做的事，与“写在本子上”相合。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“要做的风景”说不通，风景不是要完成的事。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是要做的事，与“写在本子上”的待办内容不合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“做颜色”搭配不当，颜色不说“做”。"}], "explanations": {"事项": "事项：今天要做的事，与“写在本子上”相合。", "风景": "语义：“要做的风景”说不通，风景不是要完成的事。", "月亮": "语义：月亮不是要做的事，与“写在本子上”的待办内容不合。", "颜色": "搭配：“做颜色”搭配不当，颜色不说“做”。"}, "sentence_index": 0, "correct_answer": "事项"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一张事项要做。", "explanation": "这里应该用〈个〉。量词“张”用于纸张等平面的东西，不能修饰事项。"}, {"text": "他有很多事项，都很好吃。", "explanation": "这里应该用〈菜〉。“好吃”说的是食物，“事项”是要做的条目，不能说好吃。"}, {"text": "他一口气吃完了三项事项。", "explanation": "这里“事项”用作吃的对象，应换成食物，如〈饭〉。“事项”指要做的条目，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事项", "is_correct": true, "explanation": "事项：纸上列出的、需要选择的条目，与“五个”相合。"}, {"text": "狗", "is_correct": false, "explanation": "语义：纸上不能有“五个狗”让人选一个，与语境不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能写在纸上让人“选一个”，也不用“五个”计数。"}, {"text": "情绪", "is_correct": false, "explanation": "搭配：“情绪”一般不用量词“个”计数，且“选一个”说不通。"}], "explanations": {"事项": "事项：纸上列出的、需要选择的条目，与“五个”相合。", "狗": "语义：纸上不能有“五个狗”让人选一个，与语境不合。", "天气": "语义：天气不能写在纸上让人“选一个”，也不用“五个”计数。", "情绪": "搭配：“情绪”一般不用量词“个”计数，且“选一个”说不通。"}, "sentence_index": 6, "correct_answer": "事项"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天有一座事项要做。", "explanation": "这里应该用〈个〉。量词“座”用于山、楼等大型固定的东西，不能修饰事项。"}, {"text": "他唱了一个事项，大家都很感动。", "explanation": "这里应该用〈歌〉。唱的是歌，“事项”指要做的条目，不能唱。"}, {"text": "我有一只事项要办。", "explanation": "这里应该用〈个〉。量词“只”用于动物等，不能修饰事项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经完成了两本事项。", "corrected_sentence": "他已经完成了两个事项。", "error_description": "量词“本”用于书册，不能修饰事项，应说“两个事项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把出发前得事项都做完了。", "corrected_sentence": "他把出发前的事项都做完了。", "error_description": "“出发前的事项”中的“的”不能写成“得”。修饰名词要用“的”，“得”只用于动词后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
