INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情的项目。", "primary_collocate": null, "pronunciation": "shì xiàng", "ipa": "ʂɻ̩˥˩ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "请看一下今天的事项。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会有三个主要事项。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把明天的事项写在了黑板上。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些事项都很重要，请别忘了。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表格里有几个事项还没填。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，经理看了一下所有事项。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请签证要办哪些事项？", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经谈完了第一个事项。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家前有很多事项要想好。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在纸上写下需要办的事项。", "target_word": "事项", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注意事项", "label": "复合词"}, {"form": "重要事项", "label": "复合词"}, {"form": "具体事项", "label": "复合词"}, {"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "会议、表格、手续中分条列出的事情项目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459873f2-15f3-4c94-997f-d7fd10d4860f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事项", "is_correct": true, "explanation": "事项：shì xiàng，分条列出的事情项目。"}, {"text": "四项", "is_correct": false, "explanation": "sì xiàng 与 shì xiàng 声母不同（s／sh），意思是“四项”。"}, {"text": "十项", "is_correct": false, "explanation": "shí xiàng 与 shì xiàng 声调不同（第二声与第四声），意思是“十项”。"}, {"text": "试想", "is_correct": false, "explanation": "shì xiǎng 与 shì xiàng 声调不同，意思是“试想”。"}], "explanations": {"事项": "事项：shì xiàng，分条列出的事情项目。", "四项": "sì xiàng 与 shì xiàng 声母不同（s／sh），意思是“四项”。", "十项": "shí xiàng 与 shì xiàng 声调不同（第二声与第四声），意思是“十项”。", "试想": "shì xiǎng 与 shì xiàng 声调不同，意思是“试想”。"}, "sentence_index": null, "correct_answer": "事项"}, "level_3": {"options": [{"text": "事项", "is_correct": true, "explanation": "事项：分条列出的要办的事项，与“请看一下”相合。"}, {"text": "爱情", "is_correct": false, "explanation": "搭配：“看”不搭配“爱情”，“今天的爱情”说不通。"}, {"text": "脚", "is_correct": false, "explanation": "语义：“今天的脚”说不通，“请看一下”不能用于脚。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“看”不搭配“气味”，应说“闻”。"}], "explanations": {"事项": "事项：分条列出的要办的事项，与“请看一下”相合。", "爱情": "搭配：“看”不搭配“爱情”，“今天的爱情”说不通。", "脚": "语义：“今天的脚”说不通，“请看一下”不能用于脚。", "气味": "搭配：“看”不搭配“气味”，应说“闻”。"}, "sentence_index": 0, "correct_answer": "事项"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个会议有一位事项要讨论。", "explanation": "这里应该用〈项〉。量词“位”只用于人，不能修饰事项。"}, {"text": "这本书的事项很有意思。", "explanation": "这里应该用〈内容〉。“事项”指分条列出的要办的事，说书有意思要用“内容”。"}, {"text": "他把事项藏在口袋里。", "explanation": "这里应该用〈东西〉。“藏”用于实物，“事项”是要做的条目，不能藏在口袋里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事项", "is_correct": true, "explanation": "事项：需要办理的事项，与“申请签证要办”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是需要办理的事，与“要办”不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是需要办理的事，与“申请签证”无关。"}, {"text": "兴趣", "is_correct": false, "explanation": "搭配：“办”不能搭配“兴趣”，兴趣应说“培养”。"}], "explanations": {"事项": "事项：需要办理的事项，与“申请签证要办”相合。", "颜色": "语义：“颜色”不是需要办理的事，与“要办”不合。", "歌曲": "语义：“歌曲”不是需要办理的事，与“申请签证”无关。", "兴趣": "搭配：“办”不能搭配“兴趣”，兴趣应说“培养”。"}, "sentence_index": 6, "correct_answer": "事项"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们今天要讨论一支事项。", "explanation": "这里应该用〈项〉。量词“支”用于笔、队伍等，不能修饰事项。"}, {"text": "这条事项很响亮，大家都记住了。", "explanation": "这里应该用〈口号〉。“事项”是要办的条目，不能说响亮，口号才能响亮。"}, {"text": "他讲了一个事项，大家都笑了。", "explanation": "这里应该用〈笑话〉。讲的是笑话，“事项”是要办的条目，不能讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议上有三只事项要讨论。", "corrected_sentence": "会议上有三个事项要讨论。", "error_description": "量词“只”用于动物等，不能修饰事项，应说“三个事项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们下午还要讨论两只事项。", "corrected_sentence": "我们下午还要讨论两个事项。", "error_description": "量词“只”用于动物等，不能修饰事项，应说“两个事项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0467a9e3-058f-419a-b5a6-d29bdf1a979d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
