INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93097, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "丛林是长了很多树和草的大树林。", "primary_collocate": null, "pronunciation": "cóng lín", "ipa": "tsʰʊŋ˧˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "那片丛林里长满了树和草。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不敢一个人进丛林。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丛林里的路很难走。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳光很难照进丛林。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电影里看过丛林。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟住在丛林里。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小在丛林边长大。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用刀在丛林里开了一条路。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的丛林里有很多水。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山下面是一大片丛林。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "叢林", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长满树和草的大树林", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丛林", "is_correct": true, "explanation": "正确：丛林是长满树和草的大树林，“那片丛林里长满了树和草”符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，里面不会长满树和草。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“那片”不能修饰汽车，量词与名词不搭。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，里面不会长满树和草。"}], "explanations": {"丛林": "正确：丛林是长满树和草的大树林，“那片丛林里长满了树和草”符合句意。", "厨房": "语义：厨房是房间，里面不会长满树和草。", "汽车": "搭配：“那片”不能修饰汽车，量词与名词不搭。", "电脑": "语义：电脑是机器，里面不会长满树和草。"}, "sentence_index": 0, "correct_answer": "丛林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "丛林里有很多书架，大家都在安静地看书。", "explanation": "这里应该用〈图书馆〉。丛林是长满树和草的大树林，有书架、大家安静看书的是图书馆。"}, {"text": "丛林里没有树，阳光直接晒在沙子上。", "explanation": "这里应该用〈海滩〉。丛林里树木茂密，“没有树、阳光直晒在沙子上”的是海滩。"}, {"text": "丛林里高楼很多，车也很多。", "explanation": "这里应该用〈城市〉。丛林是树木茂密的大树林，高楼林立、车水马龙的是城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丛林", "is_correct": true, "explanation": "正确：他从小在丛林边长大，“丛林边”是地点，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是人可以长大的地方。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车是交通工具，不是人长大的地方。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：「…边」要求地点名词，作业不是地点。"}], "explanations": {"丛林": "正确：他从小在丛林边长大，“丛林边”是地点，符合句意。", "冰箱": "语义：冰箱不是人可以长大的地方。", "公交车": "语义：公交车是交通工具，不是人长大的地方。", "作业": "搭配：「…边」要求地点名词，作业不是地点。"}, "sentence_index": 6, "correct_answer": "丛林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "丛林里人很多，飞机一架接一架地起飞。", "explanation": "这里应该用〈机场〉。丛林是树木茂密的大树林，飞机起降、人来人往的是机场。"}, {"text": "丛林里很冷，连草都长不出来。", "explanation": "这里应该用〈冰山〉。丛林长满了树和草，“连草都长不出来”的是冰山。"}, {"text": "丛林里有很多过山车，孩子们玩得很开心。", "explanation": "这里应该用〈游乐场〉。过山车和游乐设施属于游乐场，丛林是树木茂密的大树林。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那棵丛林很深，我们找不到出口。", "corrected_sentence": "那片丛林很深，我们找不到出口。", "error_description": "量词错误：“丛林”是大片地方，应说“那片丛林”；“棵”用于树，不能修饰丛林。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "丛林们深处有一条河。", "corrected_sentence": "丛林深处有一条河。", "error_description": "复数标记错误：“们”只用于指人的名词，“丛林”是地方，不能加“们”，应说“丛林深处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
