INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "茂密的森林；树木杂草密集生长的地方。", "primary_collocate": null, "pronunciation": "cóng lín", "ipa": "tsʰʊŋ˧˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "我们走进了一片丛林。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丛林里很热，也很潮湿。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在丛林上方飞过。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丛林里有很多我们没见过的动物。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在丛林里迷了路。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带丛林的树又高又密。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片丛林很大，走了一天也没走完。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "探险队穿过了丛林。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丛林里的草长得比人还高。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的丛林很安静。", "target_word": "丛林", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "叢林", "label": "繁体"}], "register": "中性", "sense_fingerprint": "树木杂草茂密生长的森林地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丛林", "is_correct": true, "explanation": "正确：丛林是树木杂草茂密的森林地带，“走进了一片丛林”符合句意。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，人不能走进沙发。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：量词“片”不用于房间，应说“一间教室”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是看不见的气体，不能说走进。"}], "explanations": {"丛林": "正确：丛林是树木杂草茂密的森林地带，“走进了一片丛林”符合句意。", "沙发": "语义：沙发是家具，人不能走进沙发。", "教室": "搭配：量词“片”不用于房间，应说“一间教室”。", "空气": "语义：空气是看不见的气体，不能说走进。"}, "sentence_index": 0, "correct_answer": "丛林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "丛林里有很多商店，人们在里面买衣服。", "explanation": "这里应该用〈商场〉。丛林是树木杂草茂密的森林，有很多商店、买衣服的是商场。"}, {"text": "丛林里几乎没有树和草，只有沙子。", "explanation": "这里应该用〈沙漠〉。丛林指树木杂草茂密的森林，没有树和草、只有沙子的是沙漠。"}, {"text": "丛林里的海浪一阵阵涌上来，人们在白色的沙子上堆沙堡。", "explanation": "这里应该用〈海滩〉。丛林树木茂密，不会有海浪和白沙；海浪、白沙、堆沙堡的是海滩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丛林", "is_correct": true, "explanation": "正确：丛林很大，能走一天也走不完，符合句意。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：量词“片”不用于课本，课本也不能“走完”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是习题，不能用“走”来衡量大小。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不能被走完，句子与“走了一天”冲突。"}], "explanations": {"丛林": "正确：丛林很大，能走一天也走不完，符合句意。", "课本": "搭配：量词“片”不用于课本，课本也不能“走完”。", "作业": "语义：作业是习题，不能用“走”来衡量大小。", "雨水": "语义：雨水不能被走完，句子与“走了一天”冲突。"}, "sentence_index": 6, "correct_answer": "丛林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "丛林里的草很矮，一眼就能看到远处。", "explanation": "这里应该用〈草原〉。丛林草木茂密、视线受阻；草很矮、一眼望远的是草原。"}, {"text": "丛林里很冷，连一棵树都看不见。", "explanation": "这里应该用〈雪山〉。丛林树木茂密，“连一棵树都看不见”的是雪山。"}, {"text": "丛林里有很多病床，医生正在给病人看病。", "explanation": "这里应该用〈医院〉。丛林是树木杂草茂密的森林，有病床、医生看病的是医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条丛林没有路，很难穿过。", "corrected_sentence": "这片丛林没有路，很难穿过。", "error_description": "量词错误：“丛林”是大片地方，应说“这片丛林”；“条”用于细长的东西，不能修饰丛林。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那片的丛林很深，我们一天也走不出去。", "corrected_sentence": "那片丛林很深，我们一天也走不出去。", "error_description": "助词错误：“那片”直接修饰名词，中间不能加“的”，应说“那片丛林”，不能说“那片的丛林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
