INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93099, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "创立是第一次把一个新的东西建起来。", "primary_collocate": null, "pronunciation": "chuàng lì", "ipa": "ʈʂʰu̯ɑŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他创立了一家小公司。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师在这里创立了第一所学校。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个学校是一百年前创立的。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想创立自己的公司。", "target_word": "创立", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们三个人一起创立了这家网站。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她创立过一个读书会。", "target_word": "创立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时创立了这家饭店。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家银行创立的时间很早。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们决定在北京创立新的学校。", "target_word": "创立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把所有的钱都用来创立这家医院。", "target_word": "创立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创立了", "label": "体标（了）"}, {"form": "创立过", "label": "体标（过）"}, {"form": "创立者", "label": "复合词"}, {"form": "创立人", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "第一次建起公司、学校等机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1bf60fe-067d-49a1-bd98-e843615aaeb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93099, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创立", "is_correct": true, "explanation": "正确：“创立”指第一次建起公司，符合“他……了一家小公司”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，公司不能被吃。"}, {"text": "盖", "is_correct": false, "explanation": "搭配：“盖”搭配房屋、建筑，不说盖公司。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“一家小公司”作宾语。"}], "explanations": {"创立": "正确：“创立”指第一次建起公司，符合“他……了一家小公司”的语境。", "吃": "语义：“吃”的对象应是食物，公司不能被吃。", "盖": "搭配：“盖”搭配房屋、建筑，不说盖公司。", "散步": "配价：“散步”是不及物动词，不能带“一家小公司”作宾语。"}, "sentence_index": 0, "correct_answer": "创立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他创立了一台新机器。", "explanation": "这里应该用〈发明〉。创立用于公司、学校等机构，制造机器要用发明。"}, {"text": "他们创立了友好关系。", "explanation": "这里应该用〈建立〉。创立指新设机构，“友好关系”这类抽象联系要用建立。"}, {"text": "她创立了一座新桥。", "explanation": "这里应该用〈修建〉。创立用于机构，桥梁这类建筑要用修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创立", "is_correct": true, "explanation": "正确：“创立”指第一次建起饭店，符合“爷爷年轻时……了这家饭店”的语境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象应是饮品，饭店不能被喝。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“这家饭店”作宾语。"}, {"text": "嫁", "is_correct": false, "explanation": "搭配：“嫁”的对象是人，不能说嫁了一家饭店。"}], "explanations": {"创立": "正确：“创立”指第一次建起饭店，符合“爷爷年轻时……了这家饭店”的语境。", "喝": "语义：“喝”的对象应是饮品，饭店不能被喝。", "睡": "配价：“睡”是不及物动词，不能带“这家饭店”作宾语。", "嫁": "搭配：“嫁”的对象是人，不能说嫁了一家饭店。"}, "sentence_index": 6, "correct_answer": "创立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她创立了一场婚礼。", "explanation": "这里应该用〈举办〉。创立用于公司、学校等机构，婚礼要用举办。"}, {"text": "他创立了一幅油画。", "explanation": "这里应该用〈绘制〉。创立用于机构，作品要用绘制。"}, {"text": "这位工人创立了一条新公路。", "explanation": "这里应该用〈修建〉。创立用于机构，道路要用修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们三年前创立着这家网站。", "corrected_sentence": "他们三年前创立了这家网站。", "error_description": "“着”错误：“创立”表示一次完成的动作，不能用“着”表示持续状态，应把“创立着”改为“创立了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院是她几年前了创立的。", "corrected_sentence": "这家医院是她几年前创立的。", "error_description": "“了”位置错误：“了”不能插在“创立”之前。“是……的”句式中的动词后不加“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
