INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93101, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93101, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "各方是每一边、每一个地方的人。", "primary_collocate": null, "pronunciation": "gè fāng", "ipa": "kɤ˥˩ fɑŋ˥", "syllable_count": 2, "sentences": [{"text": "各方的朋友都来参加他的婚礼。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，各方的亲戚都来看奶奶。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来自各方的客人请坐，我们马上开饭。", "target_word": "各方", "complexity_tier": "T3", "furigana": "lái zì gè fāng de kè rén qǐng zuò, wǒ men mǎ shàng kāi fàn.", "sentence_source": "generated"}, {"text": "这次会议请来了来自各方的专家。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各方客人都到了，我们开始吃饭吧。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这里住过很多年，认识各方的人。", "target_word": "各方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来自各方的同学都同意今天下午开会。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来自各方的游客都在广场上拍照。", "target_word": "各方", "complexity_tier": "T3", "furigana": "lái zì gè fāng de yóu kè dōu zài guǎng chǎng shàng pāi zhào.", "sentence_source": "generated"}, {"text": "各方来的同学都到齐了，我们出发吧。", "target_word": "各方", "complexity_tier": "T3", "furigana": "gè fāng lái de tóng xué dōu dào qí le, wǒ men chū fā ba.", "sentence_source": "generated"}, {"text": "各方的人围着桌子，一边喝茶一边聊天。", "target_word": "各方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "各方：来自每一边、每一个地方的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93101, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各方", "is_correct": true, "explanation": "“各方”指来自各个方面、各个地方的人，可以修饰“朋友”，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有朋友，“石头的朋友”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“朋友”的领属语应为人或团体，“天气”不能与之搭配。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不会有朋友，这个句子说不通。"}], "explanations": {"各方": "“各方”指来自各个方面、各个地方的人，可以修饰“朋友”，句意通顺。", "石头": "语义：石头没有朋友，“石头的朋友”不成立。", "天气": "搭配：“朋友”的领属语应为人或团体，“天气”不能与之搭配。", "数字": "语义：数字不会有朋友，这个句子说不通。"}, "sentence_index": 0, "correct_answer": "各方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子的各方都贴着标签。", "explanation": "这里应该用〈各面〉。“各方”指人或单位，不指物体的侧面，说物体的各个面要用〈各面〉。"}, {"text": "这种水果各方都有。", "explanation": "这里应该用〈各地〉。“各方”指每一边、每一地方的人，不指地点本身；说这种水果各地都有，应用〈各地〉。"}, {"text": "这些树各方都长满了叶子。", "explanation": "这里应该用〈各处〉。“各方”指每一边、每一地方的人，不用来指树木的位置；说各处都长满叶子，应用〈各处〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各方", "is_correct": true, "explanation": "“各方”指来自每一边、每个地方的人，“来自各方的同学”句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：同学不会“来自桌子”，“来自”后面应是地方或方面。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“来自电脑的同学”说不通，“来自”后面应是地方或方面。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”不能和“来自……的同学”一起表达同学来自各地，这个句子说不通。"}], "explanations": {"各方": "“各方”指来自每一边、每个地方的人，“来自各方的同学”句意通顺。", "桌子": "语义：同学不会“来自桌子”，“来自”后面应是地方或方面。", "电脑": "搭配：“来自电脑的同学”说不通，“来自”后面应是地方或方面。", "房间": "语义：“房间”不能和“来自……的同学”一起表达同学来自各地，这个句子说不通。"}, "sentence_index": 6, "correct_answer": "各方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画用了各方颜色。", "explanation": "这里应该用〈各种〉。“各方”指人或单位，不能修饰“颜色”，说各种颜色要用〈各种〉。"}, {"text": "我们要从各方看这件事。", "explanation": "这里的“各方”指各个方面，是另一个义项，应说〈各个方面〉，与“每一边的人”的意思不同。"}, {"text": "这家店的各方饼干很香。", "explanation": "这里应该用〈各种〉。“各方”指人，不能修饰“饼干”；说各种饼干，应用〈各种〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次会议请来了一个各方的代表。", "corrected_sentence": "这次会议请来了各方的代表。", "error_description": "“各方”本身已表示多方，前面不能再加数量词“一个”；应说“各方的代表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来自各方们的同学都到齐了。", "corrected_sentence": "来自各方的同学都到齐了。", "error_description": "“各方”本身已表示多方，后面不能再加“们”；应说“来自各方的同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
