INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "各个方面；有关的各个单位或各个人。", "primary_collocate": null, "pronunciation": "gè fāng", "ipa": "kɤ˥˩ fɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这件事需要各方一起努力。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各方都对这个结果很满意。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过各方的帮助，问题终于解决了。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要听听各方的意见，再做决定。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各方的消息都说明，他今年不会来。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把各方的要求都写在了纸上。", "target_word": "各方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划得到了各方的支持。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作受到各方的关注。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各方好不容易坐下来谈了一次。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了这个活动，各方都准备了很久。", "target_word": "各方", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "各方：有关的各个单位、各个人或各个方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各方", "is_correct": true, "explanation": "“各方”指有关的各个单位或人，可以一起努力，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会努力，“一起努力”的主体应为人或单位。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能“努力”，“一起努力”的主体应为人或单位。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“一起努力”多与人或团体搭配，“数字”不能作“努力”的主体。"}], "explanations": {"各方": "“各方”指有关的各个单位或人，可以一起努力，句意通顺。", "石头": "语义：石头不会努力，“一起努力”的主体应为人或单位。", "天气": "语义：天气不能“努力”，“一起努力”的主体应为人或单位。", "数字": "搭配：“一起努力”多与人或团体搭配，“数字”不能作“努力”的主体。"}, "sentence_index": 0, "correct_answer": "各方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼的各方窗户都很大。", "explanation": "这里应该用〈各扇〉。“各方”不用来修饰物件；说每扇窗都很大，应用〈各扇〉。"}, {"text": "各方的天气都很好。", "explanation": "这里应该用〈各地〉。“各方”指有关的人或单位，不修饰“天气”；说各地的天气都好，应用〈各地〉。"}, {"text": "院子里各方的花都开了。", "explanation": "这里应该用〈各色〉。“各方”指人或单位，不用来修饰花，说各种颜色的花要用〈各色〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各方", "is_correct": true, "explanation": "“各方”指有关的各个单位或人，可以给予支持，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会给予支持，“支持”的施事应为人或单位。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能给予支持，这个句子说不通。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：“得到……的支持”要求人或团体作施事，“夏天”不能与之搭配。"}], "explanations": {"各方": "“各方”指有关的各个单位或人，可以给予支持，句意通顺。", "桌子": "语义：桌子不会给予支持，“支持”的施事应为人或单位。", "空气": "语义：空气不能给予支持，这个句子说不通。", "夏天": "搭配：“得到……的支持”要求人或团体作施事，“夏天”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "各方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街上各方的小狗很活泼。", "explanation": "这里应该用〈各家〉。“各方”指人或单位，不指动物，说各家养的小狗要用〈各家〉。"}, {"text": "街边的各方果汁很多。", "explanation": "这里应该用〈各种〉。“各方”指人或单位，不能修饰饮料，说各种果汁要用〈各种〉。"}, {"text": "这家店卖各方点心。", "explanation": "这里应该用〈各种〉。“各方”不能修饰“点心”，说各种点心要用〈各种〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了这个项目，各方们都做出了努力。", "corrected_sentence": "为了这个项目，各方都做出了努力。", "error_description": "“各方”本身已表示多方，后面不能再加“们”；应说“各方都做出了努力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的新规定征求了一个各方的意见。", "corrected_sentence": "学校的新规定征求了各方的意见。", "error_description": "“各方”前面不能加数量词“一个”，因为“各方”本身已表示多方；应说“征求了各方的意见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93103, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲", "is_correct": true, "explanation": "正确。喜（高兴）与悲（伤心）是反义词。"}, {"text": "亮", "is_correct": false, "explanation": "亮（明亮）与喜（高兴）没有反义关系，不能作为“喜”的反义词。"}, {"text": "远", "is_correct": false, "explanation": "远（距离大）与喜（高兴）没有反义关系，不是反义词。"}, {"text": "软", "is_correct": false, "explanation": "软（不硬）与喜（高兴）没有反义关系，不是反义词。"}], "correct_answer": "悲", "explanations": {"悲": "正确。喜（高兴）与悲（伤心）是反义词。", "亮": "亮（明亮）与喜（高兴）没有反义关系，不能作为“喜”的反义词。", "远": "远（距离大）与喜（高兴）没有反义关系，不是反义词。", "软": "软（不硬）与喜（高兴）没有反义关系，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93103, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲", "is_correct": true, "explanation": "正确。喜（高兴）与悲（伤心）是反义词。"}, {"text": "暗", "is_correct": false, "explanation": "暗（光线弱）与喜（高兴）没有反义关系，不是反义词。"}, {"text": "高", "is_correct": false, "explanation": "高（位置或程度上方）与喜（高兴）没有反义关系，不是反义词。"}, {"text": "冷", "is_correct": false, "explanation": "冷（温度低）与喜（高兴）没有反义关系，不是反义词。"}], "correct_answer": "悲", "explanations": {"悲": "正确。喜（高兴）与悲（伤心）是反义词。", "暗": "暗（光线弱）与喜（高兴）没有反义关系，不是反义词。", "高": "高（位置或程度上方）与喜（高兴）没有反义关系，不是反义词。", "冷": "冷（温度低）与喜（高兴）没有反义关系，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93103, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "喜是心里高兴。", "primary_collocate": null, "pronunciation": "xǐ", "ipa": "ɕi˨˩˦", "syllable_count": 1, "sentences": [{"text": "听到这个好消息，她又惊又喜。", "target_word": "喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到儿子回来，妈妈心中一喜。", "target_word": "喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他先是一喜，后来又担心起来。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试通过了，我又喜又怕。", "target_word": "喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她转悲为喜，脸上又有了笑容。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让他既喜又忧。", "target_word": "喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "收到礼物，孩子心里一喜，马上打开了。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完电话，她先喜后忧。", "target_word": "喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看完成绩单，他心里一喜一忧。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天我心情很复杂，又喜又悲。", "target_word": "喜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "惊喜", "label": "复合词"}, {"form": "欢喜", "label": "复合词"}], "register": "中性", "sense_fingerprint": "心里高兴、感到喜悦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喜", "is_correct": true, "explanation": "正确。喜（xǐ）表示心里高兴。"}, {"text": "系", "is_correct": false, "explanation": "xì（第四声）与 xǐ（第三声）声调不同，意思是联系、系列。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 xǐ（第三声）声调不同，意思是戏剧、游戏。"}, {"text": "西", "is_correct": false, "explanation": "xī（第一声）与 xǐ（第三声）声调不同，意思是西方。"}, {"text": "稀", "is_correct": false, "explanation": "xī（第一声）与 xǐ（第三声）声调不同，意思是稀少、稀薄。"}], "explanations": {"喜": "正确。喜（xǐ）表示心里高兴。", "系": "xì（第四声）与 xǐ（第三声）声调不同，意思是联系、系列。", "戏": "xì（第四声）与 xǐ（第三声）声调不同，意思是戏剧、游戏。", "西": "xī（第一声）与 xǐ（第三声）声调不同，意思是西方。", "稀": "xī（第一声）与 xǐ（第三声）声调不同，意思是稀少、稀薄。"}, "sentence_index": null, "correct_answer": "喜"}, "level_3": {"options": [{"text": "喜", "is_correct": true, "explanation": "正确。“又惊又喜”表示又吃惊又高兴。"}, {"text": "怒", "is_correct": false, "explanation": "语义：听到好消息应当高兴，“又惊又怒”与句意不相符。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写身材，不能用来描写心情，与“惊”并列不通。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”不能与“惊”并列描写心情，句子不通顺。"}], "explanations": {"喜": "正确。“又惊又喜”表示又吃惊又高兴。", "怒": "语义：听到好消息应当高兴，“又惊又怒”与句意不相符。", "胖": "体貌：“胖”描写身材，不能用来描写心情，与“惊”并列不通。", "冷": "搭配：“冷”不能与“惊”并列描写心情，句子不通顺。"}, "sentence_index": 0, "correct_answer": "喜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他收到录取通知，喜欢得跳了起来。", "explanation": "这里应该用〈高兴〉。“喜欢”表示爱好、偏爱，不用来形容一时的兴奋心情。"}, {"text": "他今天很喜，见到谁都笑。", "explanation": "这里用法不对。“喜”作形容词单用时不说“很喜”，应说“很高兴”。"}, {"text": "这个消息让我又喜了一下，就没再说话。", "explanation": "这里用法不对。“喜”作形容词，不能用“又喜了一下”这种动作性说法，应说“高兴了一下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93103, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "喜", "is_correct": true, "explanation": "正确。喜（xǐ）表示心里高兴。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xǐ（第三声）声调不同，意思是练习、习惯。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xǐ（第三声）声调不同，意思是座位、宴席。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 xǐ（第三声）声调不同，意思是戏剧。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 xǐ（第三声）声母不同（q 与 x），意思是起来、站起。"}], "explanations": {"喜": "正确。喜（xǐ）表示心里高兴。", "习": "xí（第二声）与 xǐ（第三声）声调不同，意思是练习、习惯。", "席": "xí（第二声）与 xǐ（第三声）声调不同，意思是座位、宴席。", "戏": "xì（第四声）与 xǐ（第三声）声调不同，意思是戏剧。", "起": "qǐ（第三声）与 xǐ（第三声）声母不同（q 与 x），意思是起来、站起。"}, "sentence_index": null, "correct_answer": "喜"}, "level_3": {"options": [{"text": "喜", "is_correct": true, "explanation": "正确。“心里一喜”表示心里突然高兴。"}, {"text": "愁", "is_correct": false, "explanation": "语义：收到礼物应当高兴，“心里一愁”与句意相反。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指身体的感觉，不能说“心里一饿”，句意不通。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”描写身材，不能描写心情，“心里一胖”不通。"}], "explanations": {"喜": "正确。“心里一喜”表示心里突然高兴。", "愁": "语义：收到礼物应当高兴，“心里一愁”与句意相反。", "饿": "语义：“饿”指身体的感觉，不能说“心里一饿”，句意不通。", "胖": "语义：“胖”描写身材，不能描写心情，“心里一胖”不通。"}, "sentence_index": 6, "correct_answer": "喜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息让她又喜了一下，又很怕。", "explanation": "这里用法不对。“喜”作形容词，不能加“了一下”表示短暂动作，应说“高兴了一下”。"}, {"text": "妹妹听到消息，喜欢得跳了起来。", "explanation": "这里应该用〈高兴〉。“喜欢”表示爱好，不表示一时的心情。"}, {"text": "这个结果让她很喜，就不说话了。", "explanation": "这里用法不对。“喜”作形容词单用时不说“很喜”，应说“很高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到录取通知，他心里一喜欢。", "corrected_sentence": "听到录取通知，他心里一喜。", "error_description": "用词错误：“心里一喜”中的“喜”表示心里高兴，后面不能加“欢”。“喜欢”是另一个词，意思是“爱好”。正确说法是“心里一喜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到录取通知，他后喜先忧。", "corrected_sentence": "听到录取通知，他先喜后忧。", "error_description": "顺序错误：“先……后……”结构中，“喜”应在前，说“先喜后忧”；“后喜先忧”的顺序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93104, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "讨厌", "is_correct": true, "explanation": "正确。“喜”（喜欢、偏爱）与“讨厌”意思相反。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“喜欢”没有反义关系，不是反义词。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”与“喜欢”没有反义关系，不是反义词。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“喜欢”没有反义关系，不是反义词。"}], "correct_answer": "讨厌", "explanations": {"讨厌": "正确。“喜”（喜欢、偏爱）与“讨厌”意思相反。", "跑": "“跑”与“喜欢”没有反义关系，不是反义词。", "唱": "“唱”与“喜欢”没有反义关系，不是反义词。", "写": "“写”与“喜欢”没有反义关系，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
