INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "喜欢、偏爱某种事物或环境。", "primary_collocate": null, "pronunciation": "xǐ", "ipa": "ɕi˨˩˦", "syllable_count": 1, "sentences": [{"text": "这种花喜阳光，怕多浇水。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷喜绿茶，不喜咖啡。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜静不喜动，周末常在家看书。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兰花喜阴，不要放在太阳下。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫喜干净，常常自己洗脸。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜甜，妈妈却喜辣。", "target_word": "喜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鱼喜冷水，夏天要常换水。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜热闹，常常请朋友来家里。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人多喜面食，南方人多喜米饭。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜玩水，一到河边就不想走。", "target_word": "喜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喜欢", "label": "复合词"}, {"form": "喜爱", "label": "复合词"}], "register": "中性", "sense_fingerprint": "喜欢、偏爱某种东西或环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93104, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喜", "is_correct": true, "explanation": "正确。喜（xǐ）表示喜欢、偏爱。"}, {"text": "西", "is_correct": false, "explanation": "xī（第一声）与 xǐ（第三声）声调不同，意思是西边。"}, {"text": "稀", "is_correct": false, "explanation": "xī（第一声）与 xǐ（第三声）声调不同，意思是稀少。"}, {"text": "系", "is_correct": false, "explanation": "xì（第四声）与 xǐ（第三声）声调不同，意思是联系。"}, {"text": "细", "is_correct": false, "explanation": "xì（第四声）与 xǐ（第三声）声调不同，意思是细小。"}], "explanations": {"喜": "正确。喜（xǐ）表示喜欢、偏爱。", "西": "xī（第一声）与 xǐ（第三声）声调不同，意思是西边。", "稀": "xī（第一声）与 xǐ（第三声）声调不同，意思是稀少。", "系": "xì（第四声）与 xǐ（第三声）声调不同，意思是联系。", "细": "xì（第四声）与 xǐ（第三声）声调不同，意思是细小。"}, "sentence_index": null, "correct_answer": "喜"}, "level_3": {"options": [{"text": "喜", "is_correct": true, "explanation": "正确。“喜阳光”表示这种花喜欢阳光。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”不能与“阳光”搭配，句子不通。"}, {"text": "骂", "is_correct": false, "explanation": "语义：花不会去骂阳光，这与植物生长的常识不符，句意不通。"}, {"text": "吞", "is_correct": false, "explanation": "语义：植物不会吞下阳光，这与常识不符，句意不通。"}], "explanations": {"喜": "正确。“喜阳光”表示这种花喜欢阳光。", "听": "搭配：“听”不能与“阳光”搭配，句子不通。", "骂": "语义：花不会去骂阳光，这与植物生长的常识不符，句意不通。", "吞": "语义：植物不会吞下阳光，这与常识不符，句意不通。"}, "sentence_index": 0, "correct_answer": "喜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盆兰花被喜了阴，长得很慢。", "explanation": "这里用法不对。“喜”是动词，表示喜欢，不用于“被”字句，应说“喜阴”。"}, {"text": "他拿到奖学金，喜欢得跳了起来。", "explanation": "这里应该用〈高兴〉。“喜欢”表示爱好，不表示一时的兴奋心情。"}, {"text": "妹妹听了，喜了一下，就不说话了。", "explanation": "这里用法不对。“喜”表示喜欢时是持续的爱好，不能用“喜了一下”这种短暂动作说法，应说“很喜欢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93104, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "喜", "is_correct": true, "explanation": "正确。喜（xǐ）表示喜欢、偏爱。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xǐ（第三声）声调不同，意思是习惯。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xǐ（第三声）声调不同，意思是座位。"}, {"text": "许", "is_correct": false, "explanation": "xǔ（第三声）与 xǐ（第三声）韵母不同（ǔ 与 ǐ），意思是允许。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 xǐ（第三声）声母不同（q 与 x），意思是起来。"}], "explanations": {"喜": "正确。喜（xǐ）表示喜欢、偏爱。", "习": "xí（第二声）与 xǐ（第三声）声调不同，意思是习惯。", "席": "xí（第二声）与 xǐ（第三声）声调不同，意思是座位。", "许": "xǔ（第三声）与 xǐ（第三声）韵母不同（ǔ 与 ǐ），意思是允许。", "起": "qǐ（第三声）与 xǐ（第三声）声母不同（q 与 x），意思是起来。"}, "sentence_index": null, "correct_answer": "喜"}, "level_3": {"options": [{"text": "喜", "is_correct": true, "explanation": "正确。“喜冷水”表示这种鱼喜欢冷水。"}, {"text": "唱", "is_correct": false, "explanation": "语义：鱼不会唱冷水，这与句子的意思不符，句意不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”通常用于衣服，不说“穿冷水”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮冷水”不合常理，与“夏天要常换水”的语境不符。"}], "explanations": {"喜": "正确。“喜冷水”表示这种鱼喜欢冷水。", "唱": "语义：鱼不会唱冷水，这与句子的意思不符，句意不通。", "穿": "搭配：“穿”通常用于衣服，不说“穿冷水”。", "煮": "语义：“煮冷水”不合常理，与“夏天要常换水”的语境不符。"}, "sentence_index": 6, "correct_answer": "喜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子听到好消息，喜欢得直往河边跑。", "explanation": "这里应该用〈高兴〉。“喜欢”表示爱好，不表示听到好消息后的兴奋心情。"}, {"text": "孩子喜了一下，一到河边就不想走。", "explanation": "这里用法不对。“喜”表示喜欢时是持续的爱好，不能用“喜了一下”，应说“很喜欢”。"}, {"text": "孩子喜了玩水，一到河边就不想走。", "explanation": "这里用法不对。“喜”表示喜欢时后面直接接宾语，“喜了玩水”的“了”用错了位置，应说“喜玩水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盆兰花喜了阴，长得很慢。", "corrected_sentence": "这盆兰花喜阴，长得很慢。", "error_description": "助词错误：“喜”是动词，表示“喜欢”，后面不能直接加“了”。正确说法是“喜阴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟喜了玩水，每次都不肯回家。", "corrected_sentence": "弟弟喜玩水，每次都不肯回家。", "error_description": "助词错误：“喜”是动词，后面直接接宾语“玩水”，不能加“了”；应说“喜玩水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
