INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同一国家内部不同政治集团或阶级之间的战争。", "primary_collocate": null, "pronunciation": "guó nèi zhàn zhēng", "ipa": "kuo˧˥ nei˥˩ ʈʂan˥˩ ʈʂəŋ˥", "syllable_count": 4, "sentences": [{"text": "这个国家发生过一次国内战争。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内战争让很多人失去了家。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场国内战争打了四年。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里写着这场国内战争的原因。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内战争结束后，国家慢慢恢复了。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的政治集团之间爆发了国内战争。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲过美国的国内战争。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家人在国内战争中搬到了国外。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内战争使这个国家的经济很困难。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个阶级的矛盾最后变成了国内战争。", "target_word": "国内战争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场国内战争", "label": "量词"}], "register": "书面语", "sense_fingerprint": "一国之内不同政治集团或阶级之间发生的战争", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd141117f-2ae9-4d90-a8b3-bebfc4f77083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国内战争", "is_correct": true, "explanation": "正确：「国内战争」指一国之内不同政治集团之间的战争，可以“发生”。"}, {"text": "哲学", "is_correct": false, "explanation": "语义：哲学是思想体系，不能“发生”，句意不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学不是事件，不能说“发生过一次数学”。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“发生过一次”后接的应是事件，“友谊”不能这样搭配。"}], "explanations": {"国内战争": "正确：「国内战争」指一国之内不同政治集团之间的战争，可以“发生”。", "哲学": "语义：哲学是思想体系，不能“发生”，句意不通。", "数学": "语义：数学不是事件，不能说“发生过一次数学”。", "友谊": "搭配：“发生过一次”后接的应是事件，“友谊”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "国内战争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国之间的国内战争越来越严重。", "explanation": "这里应该用〈冲突〉。国内战争只指一国之内的战争，“两国之间”应用冲突。"}, {"text": "两国边境的国内战争已经停止了。", "explanation": "这里应该用〈战斗〉。“国内”指一国之内，“两国边境”应用战斗。"}, {"text": "两国之间的国内战争很难解决。", "explanation": "这里应该用〈纠纷〉。国内战争不能发生在两国之间，“很难解决”的两国问题应用纠纷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国内战争", "is_correct": true, "explanation": "正确：「国内战争」指一国之内的战争，是“讲过”的历史话题。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不是可以“讲”的历史事件，句意不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是饮食，不能作为“讲过美国的”历史内容。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“讲”一般接故事、历史等，不接“脚步”。"}], "explanations": {"国内战争": "正确：「国内战争」指一国之内的战争，是“讲过”的历史话题。", "眼睛": "语义：眼睛不是可以“讲”的历史事件，句意不通。", "早饭": "语义：早饭是饮食，不能作为“讲过美国的”历史内容。", "脚步": "搭配：“讲”一般接故事、历史等，不接“脚步”。"}, "sentence_index": 6, "correct_answer": "国内战争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的国内战争很激烈。", "explanation": "这里应该用〈竞赛〉。“国内战争”指一国之内不同政治集团之间的战争，不指班级里的比赛。"}, {"text": "他在国内战争中找到了工作。", "explanation": "这里应该用〈招聘〉。“国内战争”是战争，不能用来找工作。"}, {"text": "这次国内战争的比分是三比零。", "explanation": "这里应该用〈比赛〉。“国内战争”没有比分，不能用来计分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个国家去年经历了一个国内战争。", "corrected_sentence": "那个国家去年经历了一场国内战争。", "error_description": "错误：“战争”的量词应为“场”，不能用“个”。正确：“那个国家去年经历了一场国内战争。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国内战争持续了很久。", "corrected_sentence": "这场国内战争持续了很久。", "error_description": "量词错误：“国内战争”前的量词应为“场”，不能用“个”。正确：“这场国内战争持续了很久。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
