INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "划定的、集中设置企业、学校等的区域。", "primary_collocate": null, "pronunciation": "yuán qū", "ipa": "ɥɛn˧˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "市政府划出一块地，建了新的工业园区。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个园区里有很多外国企业。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学城园区集中了五所学校。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园区为小公司提供便宜的办公室。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新园区明年开始招商。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司搬进了开发区的软件园区。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产业园区有一百多家企业。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想把工厂都放到园区里。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "园区的建设让这个城市发展得更快。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校搬到了新建的教育园区。", "target_word": "园区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "園區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "划定的集中设置企业学校的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8173b1b7-e271-40b8-a04e-530729132fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "园区", "is_correct": true, "explanation": "正确。“市政府划出一块地，建了新的工业园区”中，“园区”指划定的集中设置企业的区域。"}, {"text": "赛车场", "is_correct": false, "explanation": "语义：赛车场是供赛车比赛的场地，不是集中设置企业的区域，“建了新的工业……”说不通。"}, {"text": "墓园", "is_correct": false, "explanation": "语义：墓园是埋葬死者的地方，不是工业用地，与“建了新的工业……”不合。"}, {"text": "游乐园", "is_correct": false, "explanation": "语义：游乐园是娱乐场所，不是工业用地，与“建了新的工业……”不合。"}], "explanations": {"园区": "正确。“市政府划出一块地，建了新的工业园区”中，“园区”指划定的集中设置企业的区域。", "赛车场": "语义：赛车场是供赛车比赛的场地，不是集中设置企业的区域，“建了新的工业……”说不通。", "墓园": "语义：墓园是埋葬死者的地方，不是工业用地，与“建了新的工业……”不合。", "游乐园": "语义：游乐园是娱乐场所，不是工业用地，与“建了新的工业……”不合。"}, "sentence_index": 0, "correct_answer": "园区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校为新生提供便宜的园区。", "explanation": "这里应该用〈宿舍〉。“园区”是划定的区域，不能作为给新生住的房间。"}, {"text": "市里新建了一栋园区。", "explanation": "这里应该用〈个〉。“园区”用“个”计量，不用“栋”。"}, {"text": "园区为病人检查身体。", "explanation": "这里应该用〈医生〉。“园区”是区域，不能为病人检查身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "园区", "is_correct": true, "explanation": "正确。“这个产业园区有一百多家企业”中，“园区”指集中设置企业的区域。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆陈列文物，不会有一百多家企业，与“企业”的语义冲突。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园饲养动物，不是企业聚集的地方，与“一百多家企业”不合。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“产业”与“医院”搭配不当，医院一般不说“有一百多家企业”。"}], "explanations": {"园区": "正确。“这个产业园区有一百多家企业”中，“园区”指集中设置企业的区域。", "博物馆": "语义：博物馆陈列文物，不会有一百多家企业，与“企业”的语义冲突。", "动物园": "语义：动物园饲养动物，不是企业聚集的地方，与“一百多家企业”不合。", "医院": "搭配：“产业”与“医院”搭配不当，医院一般不说“有一百多家企业”。"}, "sentence_index": 6, "correct_answer": "园区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把作业交给了新园区。", "explanation": "这里应该用〈老师〉。“园区”是划定的大片区域，不是人，不能接收作业；交作业要交给老师。"}, {"text": "我每天坐新园区去上班。", "explanation": "这里应该用〈地铁〉。“园区”是划定的大片区域，不是交通工具，不能用“坐”；坐着去上班要说“坐地铁”。"}, {"text": "我把书放进了新园区。", "explanation": "这里应该用〈书包〉。“园区”是划定的大片区域，不能用来装书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府划出一块地，建了一栋新的工业园区。", "corrected_sentence": "市政府划出一块地，建了一个新的工业园区。", "error_description": "错误在于量词。“园区”是地方，应用“个”计量，不用“栋”，应改为“建了一个新的工业园区。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她园区里工作，每天很忙。", "corrected_sentence": "她在园区里工作，每天很忙。", "error_description": "错误在于漏掉了介词“在”。表示工作地点的“园区里”前要加“在”，应改为“她在园区里工作，每天很忙。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29b77f53-c4e8-4e1a-bd01-fe9be5f8cc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
