INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93109, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地主是有很多很多土地的人。", "primary_collocate": null, "pronunciation": "dì zhǔ", "ipa": "ti˥˩ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个地主有很多土地。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前，村子里有一位地主。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地主的房子又大又漂亮。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个地主每年都收很多米。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "穷人给地主做工，很辛苦。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位地主有一百多亩地。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地主家里有很多人帮他做事。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爷爷以前是地主。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地主把一块地给了他的儿子。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个地主住在山下的大房子里。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "大地主", "label": "复合"}], "register": "中性", "sense_fingerprint": "拥有大量土地的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地主", "is_correct": true, "explanation": "正确。地主指拥有大量土地的人，与听到的读音一致。"}, {"text": "地址", "is_correct": false, "explanation": "zhǐ（第三声）与 zhǔ（第三声）韵母不同（i 与 u），意思是“地址”，不是拥有大量土地的人。"}, {"text": "地处", "is_correct": false, "explanation": "chǔ（第三声）与 zhǔ（第三声）声母不同（ch 与 zh），意思是“位于”，不是“地主”。"}, {"text": "寄主", "is_correct": false, "explanation": "jì（第四声）与 dì（第四声）声母不同（j 与 d），意思是寄生物所依附的生物。"}, {"text": "自主", "is_correct": false, "explanation": "zì（第四声）与 dì（第四声）声母不同（z 与 d），意思是“自己做主”。"}], "explanations": {"地主": "正确。地主指拥有大量土地的人，与听到的读音一致。", "地址": "zhǐ（第三声）与 zhǔ（第三声）韵母不同（i 与 u），意思是“地址”，不是拥有大量土地的人。", "地处": "chǔ（第三声）与 zhǔ（第三声）声母不同（ch 与 zh），意思是“位于”，不是“地主”。", "寄主": "jì（第四声）与 dì（第四声）声母不同（j 与 d），意思是寄生物所依附的生物。", "自主": "zì（第四声）与 dì（第四声）声母不同（z 与 d），意思是“自己做主”。"}, "sentence_index": null, "correct_answer": "地主"}, "level_3": {"options": [{"text": "地主", "is_correct": true, "explanation": "正确。地主指拥有大量土地的人，与“有很多土地”搭配，句意通顺。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐没有土地，与“有很多土地”矛盾。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，不能拥有土地。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不能作“拥有土地”的主语，“这个天空有很多土地”不成立。"}], "explanations": {"地主": "正确。地主指拥有大量土地的人，与“有很多土地”搭配，句意通顺。", "乞丐": "语义：乞丐没有土地，与“有很多土地”矛盾。", "铅笔": "语义：铅笔是文具，不能拥有土地。", "天空": "搭配：“天空”不能作“拥有土地”的主语，“这个天空有很多土地”不成立。"}, "sentence_index": 0, "correct_answer": "地主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在街口开了一家小店，是个地主。", "explanation": "这里应该用〈店主〉。地主指拥有大量土地的人，开小店的人不能称作地主。"}, {"text": "我每个月都要去找地主交房租。", "explanation": "这里应该用〈房东〉。地主指拥有大量土地的人，收房屋租金的人要说〈房东〉。"}, {"text": "这家公司的老板是个地主。", "explanation": "这里不能用〈地主〉指企业的负责人。地主指拥有大量土地的人，公司老板要说〈老板〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地主", "is_correct": true, "explanation": "正确。地主家里有人帮忙做事，句意通顺。"}, {"text": "囚犯", "is_correct": false, "explanation": "语义：囚犯被关在牢里，家里不会有很多人帮他做事。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“家里”指家庭或住户，不能说“饭店家里”。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“家里”指家庭，学校不能说“学校家里”。"}], "explanations": {"地主": "正确。地主家里有人帮忙做事，句意通顺。", "囚犯": "语义：囚犯被关在牢里，家里不会有很多人帮他做事。", "饭店": "搭配：“家里”指家庭或住户，不能说“饭店家里”。", "学校": "搭配：“家里”指家庭，学校不能说“学校家里”。"}, "sentence_index": 6, "correct_answer": "地主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位地主每天在学校里当校长。", "explanation": "这里应该用〈校长〉。地主指拥有大量土地、靠出租土地收租的人，不能用来指学校的管理者。"}, {"text": "地主每天在医院里救人。", "explanation": "这里应该用〈医生〉。地主指拥有大量土地的人，不能用来指在医院救人的医务人员。"}, {"text": "地主每天在学校里教书。", "explanation": "这里应该用〈老师〉。地主指拥有大量土地的人，不能用来指在学校教书的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只地主住在村东头。", "corrected_sentence": "那个地主住在村东头。", "error_description": "“地主”指人，量词应用“个”或“位”。“只”用于动物，这里应改为“那个地主住在村东头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他爷爷以前是过地主。", "corrected_sentence": "他爷爷以前当过地主。", "error_description": "错误：“过”前的动词“当”被换成了“是”，“是过地主”不成立。正确：应说“当过地主”，“过”接在动词“当”后，表示曾经有过这样的经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
