INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93110, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "占有大量土地、靠出租土地获取收入的人。", "primary_collocate": null, "pronunciation": "dì zhǔ", "ipa": "ti˥˩ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "地主把土地租给农民种。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民每年要给地主交租。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地主不种地，靠收租过日子。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地主租出了很多地。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的地主靠收租变得很有钱。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家以前是地主，有很多出租的田。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民没有地，只好向地主租地。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地主每年秋天都去村里收租。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位地主租地给五十多户人家。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老地主靠出租土地得到很多钱。", "target_word": "地主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "大地主", "label": "复合"}], "register": "中性", "sense_fingerprint": "占有大量土地并靠出租土地收租为生的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地主", "is_correct": true, "explanation": "正确。地主指占有大量土地、靠出租土地收租的人，与听到的读音一致。"}, {"text": "地址", "is_correct": false, "explanation": "zhǐ（第三声）与 zhǔ（第三声）韵母不同（i 与 u），意思是“地址”，不是地主。"}, {"text": "地处", "is_correct": false, "explanation": "chǔ（第三声）与 zhǔ（第三声）声母不同（ch 与 zh），意思是“位于”，不是地主。"}, {"text": "寄主", "is_correct": false, "explanation": "jì（第四声）与 dì（第四声）声母不同（j 与 d），意思是寄生物所依附的生物。"}, {"text": "自主", "is_correct": false, "explanation": "zì（第四声）与 dì（第四声）声母不同（z 与 d），意思是“自己做主”。"}], "explanations": {"地主": "正确。地主指占有大量土地、靠出租土地收租的人，与听到的读音一致。", "地址": "zhǐ（第三声）与 zhǔ（第三声）韵母不同（i 与 u），意思是“地址”，不是地主。", "地处": "chǔ（第三声）与 zhǔ（第三声）声母不同（ch 与 zh），意思是“位于”，不是地主。", "寄主": "jì（第四声）与 dì（第四声）声母不同（j 与 d），意思是寄生物所依附的生物。", "自主": "zì（第四声）与 dì（第四声）声母不同（z 与 d），意思是“自己做主”。"}, "sentence_index": null, "correct_answer": "地主"}, "level_3": {"options": [{"text": "地主", "is_correct": true, "explanation": "正确。地主是出租土地的人，“把土地租给农民种”句意通顺。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能拥有或出租土地，“地主把土地租给农民种”句意不通。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，不能出租土地。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“把……租给”需要有人作出租方，“天空”不能出租土地。"}], "explanations": {"地主": "正确。地主是出租土地的人，“把土地租给农民种”句意通顺。", "汽车": "语义：汽车不能拥有或出租土地，“地主把土地租给农民种”句意不通。", "铅笔": "语义：铅笔是文具，不能出租土地。", "天空": "搭配：“把……租给”需要有人作出租方，“天空”不能出租土地。"}, "sentence_index": 0, "correct_answer": "地主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地主每个月都来收房租。", "explanation": "这里应该用〈房东〉。地主靠出租土地收租，收房屋租金的人要说〈房东〉。"}, {"text": "地主每天在学校里教学生写字。", "explanation": "这里应该用〈老师〉。地主靠出租土地收租，不能用来指在学校教书的人。"}, {"text": "这个地主昨天在电影院里卖票。", "explanation": "这里不能用〈地主〉指卖票的人。地主靠出租土地收租，与电影院的工作无关，这类人应说〈售票员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地主", "is_correct": true, "explanation": "正确。“向地主租地”句意通顺，地主是出租土地的人。"}, {"text": "囚犯", "is_correct": false, "explanation": "语义：囚犯被关在牢里，不能把土地租给农民。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不能出租土地，“向老虎租地”不成立。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“向……租地”要求出租方是人或机构，不说“向河流租地”。"}], "explanations": {"地主": "正确。“向地主租地”句意通顺，地主是出租土地的人。", "囚犯": "语义：囚犯被关在牢里，不能把土地租给农民。", "老虎": "语义：老虎不能出租土地，“向老虎租地”不成立。", "河流": "搭配：“向……租地”要求出租方是人或机构，不说“向河流租地”。"}, "sentence_index": 6, "correct_answer": "地主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地主每天在工厂里装配机器。", "explanation": "这里应该用〈工人〉。地主靠出租土地收租，不能用来指在工厂里干活的人。"}, {"text": "地主每天在菜市场卖菜。", "explanation": "这里应该用〈小贩〉。地主靠出租土地收租，不能用来指在菜市场卖菜的人。"}, {"text": "地主每天在图书馆里管理借书。", "explanation": "这里应该用〈图书管理员〉。地主靠出租土地收租，不能用来指在图书馆工作的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那棵地主一直住在村里。", "corrected_sentence": "那位地主一直住在村里。", "error_description": "“地主”指人，量词应用“位”或“个”。“棵”用于植物，应改为“那位地主一直住在村里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他地主，家里很有钱。", "corrected_sentence": "他是地主，家里很有钱。", "error_description": "判断句缺少系动词“是”，应说“他是地主”，不能直接用“地主”作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93111, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
