INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93111, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "报到是到了一个地方，告诉那里的人我来了。", "primary_collocate": null, "pronunciation": "bào dào", "ipa": "pau˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "我到了教室，先向老师报到。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李一进公司就去人事部报到。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的老师今天到学校报到。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，所以晚了一天报到。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了夏令营，孩子们先报到。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐了一天车，终于到学校报到了。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开学那天，同学们都来报到。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到了工作的地方，要先去报到。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新兵们在门口排队报到。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说明天早上八点来报到。", "target_word": "报到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报了到", "label": "体标"}, {"form": "报过到", "label": "体标"}, {"form": "报到处", "label": "复合"}], "register": "中性", "sense_fingerprint": "到了一个地方，告诉那里的人自己已经来了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd75ca80b-1f26-4b15-81d3-10584f1de521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93111, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "报到", "is_correct": true, "explanation": "正确。报到 bào dào 指到了一个地方后告诉那里的人自己已经来了。"}, {"text": "报告", "is_correct": false, "explanation": "bàogào（第四声）与 bàodào 的声母不同，意思是汇报。"}, {"text": "报导", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，意思是报道。"}, {"text": "宝岛", "is_correct": false, "explanation": "bǎo 与 bào、dǎo 与 dào 声调不同，意思是台湾岛。"}, {"text": "宝刀", "is_correct": false, "explanation": "bǎo 与 bào、dāo 与 dào 声调不同，意思是珍贵的刀。"}], "explanations": {"报到": "正确。报到 bào dào 指到了一个地方后告诉那里的人自己已经来了。", "报告": "bàogào（第四声）与 bàodào 的声母不同，意思是汇报。", "报导": "dǎo（第三声）与 dào（第四声）声调不同，意思是报道。", "宝岛": "bǎo 与 bào、dǎo 与 dào 声调不同，意思是台湾岛。", "宝刀": "bǎo 与 bào、dāo 与 dào 声调不同，意思是珍贵的刀。"}, "sentence_index": null, "correct_answer": "报到"}, "level_3": {"options": [{"text": "报到", "is_correct": true, "explanation": "正确。“先向老师报到”指到教室后先告诉老师自己已经来了。"}, {"text": "下课", "is_correct": false, "explanation": "语义：下课指一节课结束，不能说先向老师下课。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休指离开工作岗位，不能说先向老师退休。"}, {"text": "举行", "is_correct": false, "explanation": "配价：“举行”后要带宾语，如“举行仪式”，不能单独说“先向老师举行”。"}], "explanations": {"报到": "正确。“先向老师报到”指到教室后先告诉老师自己已经来了。", "下课": "语义：下课指一节课结束，不能说先向老师下课。", "退休": "语义：退休指离开工作岗位，不能说先向老师退休。", "举行": "配价：“举行”后要带宾语，如“举行仪式”，不能单独说“先向老师举行”。"}, "sentence_index": 0, "correct_answer": "报到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影晚上八点报到。", "explanation": "这里应该用〈开演〉。报到是人到达后告知对方自己已经来了，电影开始放映应说开演。"}, {"text": "演唱会晚上十点报到。", "explanation": "这里应该用〈散场〉。报到是人向别人告知自己已到，演唱会结束应说散场。"}, {"text": "商店晚上九点报到。", "explanation": "这里应该用〈打烊〉。报到是人到达后登记，商店关门应说打烊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报到", "is_correct": true, "explanation": "正确。“开学那天，同学们都来报到”说同学们到校登记。"}, {"text": "颁发", "is_correct": false, "explanation": "配价：“颁发”需要带宾语，如“颁发证书”，不能单独说“都来颁发”。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，同学们不能来下雨。"}, {"text": "散场", "is_correct": false, "explanation": "语义：散场指活动结束，开学那天不能说同学们都来散场。"}], "explanations": {"报到": "正确。“开学那天，同学们都来报到”说同学们到校登记。", "颁发": "配价：“颁发”需要带宾语，如“颁发证书”，不能单独说“都来颁发”。", "下雨": "语义：下雨是天气现象，同学们不能来下雨。", "散场": "语义：散场指活动结束，开学那天不能说同学们都来散场。"}, "sentence_index": 6, "correct_answer": "报到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花明天上午报到。", "explanation": "这里应该用〈开〉。报到是人到达后登记，花开放要说开。"}, {"text": "飞机明天早上八点报到。", "explanation": "这里应该用〈降落〉。报到是人到达后登记，飞机落地应说降落。"}, {"text": "车子明天早上七点报到。", "explanation": "这里应该用〈发车〉。报到是人到达后登记，车子出发应说发车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新来的同学今天下午报到宿舍。", "corrected_sentence": "新来的同学今天下午报到。", "error_description": "错误在“报到”后直接加了处所宾语“宿舍”。“报到”是不及物动词，不能直接带处所宾语；删去“宿舍”即可。若要说明地点，应说“去宿舍报到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他那天不报到，因为堵车了。", "corrected_sentence": "他那天没报到，因为堵车了。", "error_description": "错误在否定词。“报到”说已经发生的事，否定要用“没”，不用“不”；应说“他那天没报到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d6f31f7-85e0-48c7-809f-8008f4fefba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
