INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93113, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "多民族是说一个地方有很多不同的民族一起生活。", "primary_collocate": null, "pronunciation": "duō mín zú", "ipa": "tuɔ˥ min˧˥ tsu˧˥", "syllable_count": 3, "sentences": [{"text": "中国是一个多民族的国家。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多民族的小镇里，有汉族、回族和藏族。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校是多民族学校，同学来自很多民族。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多民族的村子里，节日特别多。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新疆是一个多民族地区。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多民族的社区里，人们说好几种话。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多民族国家的人们要互相尊重。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生在多民族的城市，会说三种语言。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是多民族的大家庭，大家像一家人。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云南是多民族省份，每个民族的衣服都不一样。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多民族国家", "label": "复合"}], "register": "正式", "sense_fingerprint": "一个地方有许多不同民族共同居住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f25efb-a327-4991-90ce-e83d14deee0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93113, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晴朗", "is_correct": false, "explanation": "搭配：“晴朗”形容天气，不能用来修饰国家。"}, {"text": "多民族", "is_correct": true, "explanation": "正确。中国是多个民族共同生活的国家，“多民族”正好描述这一点。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”指感情或滋味，与描述国家的民族构成不相干。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”多用于人的身材，不能用来形容国家。"}], "explanations": {"晴朗": "搭配：“晴朗”形容天气，不能用来修饰国家。", "多民族": "正确。中国是多个民族共同生活的国家，“多民族”正好描述这一点。", "甜蜜": "语义：“甜蜜”指感情或滋味，与描述国家的民族构成不相干。", "矮小": "体貌：“矮小”多用于人的身材，不能用来形容国家。"}, "sentence_index": 0, "correct_answer": "多民族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的风景多民族。", "explanation": "这里应该用〈多样〉。多民族指由不同民族共同生活的地区或国家，不用来形容风景；风景的种类多应说多样。"}, {"text": "这个社会的观点多民族。", "explanation": "这里应该用〈多元〉。多民族强调民族构成，观点的种类多应说多元，不能用多民族修饰观点。"}, {"text": "这次考试的时间多民族。", "explanation": "这里应该用〈漫长〉。多民族只说由多个民族构成的地区或国家，时间的长短应说漫长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高挑", "is_correct": false, "explanation": "体貌：“高挑”形容人的身材，不能用来修饰国家。"}, {"text": "多民族", "is_correct": true, "explanation": "正确。“多民族国家”指由多个民族组成的国家，与“人们要互相尊重”相符。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能修饰国家。"}, {"text": "腼腆", "is_correct": false, "explanation": "语义：“腼腆”形容人的性格，不能用来形容国家。"}], "explanations": {"高挑": "体貌：“高挑”形容人的身材，不能用来修饰国家。", "多民族": "正确。“多民族国家”指由多个民族组成的国家，与“人们要互相尊重”相符。", "咸": "搭配：“咸”形容味道，不能修饰国家。", "腼腆": "语义：“腼腆”形容人的性格，不能用来形容国家。"}, "sentence_index": 6, "correct_answer": "多民族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的情况多民族。", "explanation": "这里应该用〈复杂〉。多民族只说由多个民族构成的地区或国家，不能用来形容情况的难易。"}, {"text": "这张桌子上的书多民族。", "explanation": "这里应该用〈繁多〉。多民族强调民族构成，书的数量多应说繁多，不能说书多民族。"}, {"text": "这次活动的规模多民族。", "explanation": "这里应该用〈庞大〉。多民族不能形容活动的规模，规模大应说庞大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "云南是一个多民族着的省份。", "corrected_sentence": "云南是一个多民族的省份。", "error_description": "错误：形容词“多民族”修饰“省份”时应用“的”，不能用“着”。“着”一般接在动词后，表示动作的持续或状态，不接在“多民族”这类表示类别的形容词后面。正确形式是“多民族的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新加坡是一个多民族地国家。", "corrected_sentence": "新加坡是一个多民族的国家。", "error_description": "错误：形容词“多民族”修饰“国家”时应用“的”，不能用“地”。“地”用于修饰动词或形容词，放在名词前面是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
