INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93114, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由多个民族共同构成的。", "primary_collocate": null, "pronunciation": "duō mín zú", "ipa": "tuɔ˥ min˧˥ tsu˧˥", "syllable_count": 3, "sentences": [{"text": "这是一个由五十六个民族组成的多民族国家。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多民族的国家需要公平的法律。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多民族国家的历史是各民族共同写成的。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家是多民族的，不是只有一个民族。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是一个多民族国家的历史。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多民族的军队里有不同民族的士兵。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究多民族国家的语言政策。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有十几个民族，是多民族国家。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多民族的社会需要大家互相理解。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片介绍了一支多民族的消防队。", "target_word": "多民族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多民族国家", "label": "复合"}], "register": "正式", "sense_fingerprint": "国家或社会由多个民族共同构成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f25efb-a327-4991-90ce-e83d14deee0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消瘦", "is_correct": false, "explanation": "体貌：“消瘦”形容人的身材，不能用来形容国家。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”形容声音或笑容，不能修饰国家。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一个民族，与“由五十六个民族组成”矛盾。"}, {"text": "多民族", "is_correct": true, "explanation": "正确。“由五十六个民族组成的多民族国家”与句意一致。"}], "explanations": {"消瘦": "体貌：“消瘦”形容人的身材，不能用来形容国家。", "甜美": "搭配：“甜美”形容声音或笑容，不能修饰国家。", "单一": "语义：“单一”指只有一个民族，与“由五十六个民族组成”矛盾。", "多民族": "正确。“由五十六个民族组成的多民族国家”与句意一致。"}, "sentence_index": 0, "correct_answer": "多民族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林的树种多民族。", "explanation": "这里应该用〈多样〉。多民族只用来说由多个民族构成的国家或社会，树种的种类多应说多样。"}, {"text": "这所学校的学费多民族。", "explanation": "这里应该用〈昂贵〉。多民族只用于由多个民族构成的地区或国家，学费的数额高应说昂贵。"}, {"text": "两国之间的关系多民族。", "explanation": "这里应该用〈复杂〉。关系的错综应说复杂，多民族不能用来形容两国之间的关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多民族", "is_correct": true, "explanation": "正确。“多民族国家”是由多个民族组成的国家，可以研究它的语言政策。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，不能修饰国家。"}, {"text": "调皮", "is_correct": false, "explanation": "语义：“调皮”形容人或孩子的性格，不能用来形容国家。"}, {"text": "驼背", "is_correct": false, "explanation": "体貌：“驼背”形容人的身体姿态，不能用来形容国家。"}], "explanations": {"多民族": "正确。“多民族国家”是由多个民族组成的国家，可以研究它的语言政策。", "辣": "搭配：“辣”形容味道，不能修饰国家。", "调皮": "语义：“调皮”形容人或孩子的性格，不能用来形容国家。", "驼背": "体貌：“驼背”形容人的身体姿态，不能用来形容国家。"}, "sentence_index": 6, "correct_answer": "多民族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的成绩多民族。", "explanation": "这里应该用〈高〉。多民族不能修饰成绩，成绩好或分数高应说高。"}, {"text": "这种现象多民族。", "explanation": "这里应该用〈普遍〉。现象的普遍程度应说普遍，多民族不能用来形容现象。"}, {"text": "这家餐厅的服务态度多民族。", "explanation": "这里应该用〈热情〉。多民族不能修饰服务态度，服务好应说热情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市是不多民族的。", "corrected_sentence": "这座城市是多民族的。", "error_description": "错误：“多民族”表示民族构成的类别，不能像“大”“好”那样直接在前面加“不”来否定。否定应说“不是多民族的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "印度是一个多民族地国家。", "corrected_sentence": "印度是一个多民族的国家。", "error_description": "错误：形容词“多民族”修饰“国家”时应用“的”，不能用“地”。“地”放在名词前面是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f1ba74c-3a11-4bcb-904b-2e1ea4ec7fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小类", "is_correct": true, "explanation": "正确。“小类”是把大类再细分后的较小类别，与“大类”构成层级上的反义。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是家具，与“大类”的类别无关，不构成反义。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是地理事物，与“大类”不构成反义关系。"}, {"text": "数量", "is_correct": false, "explanation": "“数量”指多少，与大类的类别层级无关，不是反义词。"}], "correct_answer": "小类", "explanations": {"小类": "正确。“小类”是把大类再细分后的较小类别，与“大类”构成层级上的反义。", "桌子": "“桌子”是家具，与“大类”的类别无关，不构成反义。", "河流": "“河流”是地理事物，与“大类”不构成反义关系。", "数量": "“数量”指多少，与大类的类别层级无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小类", "is_correct": true, "explanation": "正确。“小类”是把大类再细分后的较小类别，与“大类”构成层级上的反义。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”是建筑部件，与“大类”不构成反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "“海洋”是地理事物，与“大类”的类别无关，不构成反义。"}, {"text": "方法", "is_correct": false, "explanation": "“方法”指做事的途径，与大类的类别层级无关，不是反义词。"}], "correct_answer": "小类", "explanations": {"小类": "正确。“小类”是把大类再细分后的较小类别，与“大类”构成层级上的反义。", "窗户": "“窗户”是建筑部件，与“大类”不构成反义关系。", "海洋": "“海洋”是地理事物，与“大类”的类别无关，不构成反义。", "方法": "“方法”指做事的途径，与大类的类别层级无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按性质划分的较大的类别。", "primary_collocate": null, "pronunciation": "dà lèi", "ipa": "ta˥˩ lei˥˩", "syllable_count": 2, "sentences": [{"text": "动物可以分成两个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典把词分成几个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物属于生物的一个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的课程分为文科和理科两大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把病人的问题分成了几个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大类是按性质划分的，分得很清楚。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这些商品属于同一个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里的书先按大类摆好。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把工作分成三个大类来做。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告里分出了五个大类。", "target_word": "大类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个大类", "label": "量词"}], "register": "书面语", "sense_fingerprint": "按性质划分出来的范围较大的类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd141117f-2ae9-4d90-a8b3-bebfc4f77083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大类", "is_correct": true, "explanation": "正确。“动物可以分成两个大类”指按性质划分出的较大类别。"}, {"text": "大厅", "is_correct": false, "explanation": "语义：“大厅”是房间，动物不能分成两个大厅。"}, {"text": "大学", "is_correct": false, "explanation": "语义：“大学”是高等学校，不能用来说动物的分类。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“大海”要用“片”计量，不说“两个大海”。"}], "explanations": {"大类": "正确。“动物可以分成两个大类”指按性质划分出的较大类别。", "大厅": "语义：“大厅”是房间，动物不能分成两个大厅。", "大学": "语义：“大学”是高等学校，不能用来说动物的分类。", "大海": "搭配：“大海”要用“片”计量，不说“两个大海”。"}, "sentence_index": 0, "correct_answer": "大类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个大类的教室里坐着五十个学生。", "explanation": "这里应该用〈大班〉。“大类”指类别，不指班级。"}, {"text": "学校的图书馆一下子来了大类的人。", "explanation": "这里应该用〈大批〉。“大类”指类别，不表示人数多。"}, {"text": "学校的大类每天都来上课。", "explanation": "这里应该用〈老师〉。“大类”指类别，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大类", "is_correct": true, "explanation": "正确。“属于同一个大类”指商品被归入同一个较大的类别。"}, {"text": "大脑", "is_correct": false, "explanation": "语义：“大脑”是器官，商品不能属于同一个大脑。"}, {"text": "大洲", "is_correct": false, "explanation": "语义：“大洲”是地理区域，商品不能按大洲归入同一类。"}, {"text": "大树", "is_correct": false, "explanation": "搭配：“树”用“棵”计量，不说“同一个大树”。"}], "explanations": {"大类": "正确。“属于同一个大类”指商品被归入同一个较大的类别。", "大脑": "语义：“大脑”是器官，商品不能属于同一个大脑。", "大洲": "语义：“大洲”是地理区域，商品不能按大洲归入同一类。", "大树": "搭配：“树”用“棵”计量，不说“同一个大树”。"}, "sentence_index": 6, "correct_answer": "大类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣太小了，我想换个大类的。", "explanation": "这里应该用〈大号〉。“大类”指类别，不指衣服的尺码。"}, {"text": "他一口气吃了一大类饭。", "explanation": "这里应该用〈大份〉。“大类”指类别，不指食物的份量。"}, {"text": "大类都很喜欢这份报告。", "explanation": "这里应该用〈大家〉。“大类”指类别，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把课程分成了两本大类。", "corrected_sentence": "学校把课程分成了两个大类。", "error_description": "量词错误：“大类”的量词应为“个”，“本”只用于书籍，不能用于大类。正确：“学校把课程分成了两个大类。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些商品属于同一条大类。", "corrected_sentence": "这些商品属于同一个大类。", "error_description": "量词错误：“大类”的量词应为“个”，“条”用于细长的东西，不能用于大类。正确：“这些商品属于同一个大类。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
