INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93117, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示经过很长时间或很多困难，最后才实现。", "primary_collocate": null, "pronunciation": "hǎo róng yì", "ipa": "xaʊ̯˨˩˦ ɻʊŋ˧˥ i˥˩", "syllable_count": 3, "sentences": [{"text": "好容易等到周末，我却病了。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他好容易才考上了大学。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我好容易才说服了爸爸。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明好容易才把作业写完。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好容易攒够了钱，她买了新手机。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找了一年，他好容易才找到工作。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子好容易才开口说话。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们好容易才见了一面，别吵架了。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好容易盼到放假，大家都很高兴。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她好容易才戒了烟。", "target_word": "好容易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "经过很长时间的困难，最后才做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd141117f-2ae9-4d90-a8b3-bebfc4f77083') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好容易", "is_correct": true, "explanation": "“好容易”表示经过很长时间的困难才做到，与“等到周末”的语境相合。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示庆幸，后句“我却病了”是遗憾，语义相反。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示马上，不能与“等到周末”这种长时间的等待搭配。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，与后句“我却病了”的转折不合。"}], "explanations": {"好容易": "“好容易”表示经过很长时间的困难才做到，与“等到周末”的语境相合。", "幸亏": "语义：“幸亏”表示庆幸，后句“我却病了”是遗憾，语义相反。", "立刻": "搭配：“立刻”表示马上，不能与“等到周末”这种长时间的等待搭配。", "果然": "语义：“果然”表示与预料相符，与后句“我却病了”的转折不合。"}, "sentence_index": 0, "correct_answer": "好容易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明好容易才十分钟就写完了作业。", "explanation": "这里应该用〈很快〉。好容易表示费了很大力气才做成，与“十分钟就写完”所说的迅速相矛盾。"}, {"text": "小明好容易就把作业写完了。", "explanation": "好容易强调费力才做成，与“就”表示轻松的语气矛盾。这里应该用〈很快〉。"}, {"text": "小明好容易才把作业写完，因为题目很简单。", "explanation": "这里应该用〈轻松〉。好容易表示费力才做成，与“题目很简单”所说的轻松相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好容易", "is_correct": true, "explanation": "“好容易”表示费了很大力气才开口，与“这个孩子”的语境相合。"}, {"text": "很快", "is_correct": false, "explanation": "语义：“很快”表示速度快，与费了很长时间才开口的语义相反。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能与“才”一起表示经过努力后才达成。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸，句中并没有值得庆幸的事。"}], "explanations": {"好容易": "“好容易”表示费了很大力气才开口，与“这个孩子”的语境相合。", "很快": "语义：“很快”表示速度快，与费了很长时间才开口的语义相反。", "一直": "搭配：“一直”表示持续，不能与“才”一起表示经过努力后才达成。", "幸好": "语义：“幸好”表示庆幸，句中并没有值得庆幸的事。"}, "sentence_index": 6, "correct_answer": "好容易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她轻轻松松地好容易才戒了烟。", "explanation": "这里应该用〈轻易〉。好容易表示费了很大力气才做成，与“轻轻松松”所表示的不费力相反。"}, {"text": "她戒烟的过程很顺利，好容易才戒掉了。", "explanation": "这里应该用〈轻易〉。好容易表示费了很大力气，与“很顺利”所说的顺畅相矛盾。"}, {"text": "她好容易才戒了烟，这件事很简单。", "explanation": "这里应该用〈轻易〉。好容易表示费了很大力气，与“这件事很简单”所说的轻松相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2958baa-1e9b-4db9-98e7-b43678a2862c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
