INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93119, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好运是遇到让你高兴的好事。", "primary_collocate": null, "pronunciation": "hǎo yùn", "ipa": "xɑu˨˩˦ yn˥˩", "syllable_count": 2, "sentences": [{"text": "昨天我中了奖，真是好运。", "target_word": "好运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "捡到钱包还给别人，后来他也遇到了好运。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好运让全家人都很高兴。", "target_word": "好运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她买的彩票中了奖，这个好运来得太突然。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能认识你，是我一生中最大的好运。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨前正好到家，真是好运。", "target_word": "好运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板今天请客，这是我们的好运。", "target_word": "好运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他遇到好运后，马上告诉了父母。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好运降临到了他们家。", "target_word": "好运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没想到我也有过这样的好运。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好运气", "label": "复合词"}], "register": "中性", "sense_fingerprint": "遇到的让人高兴的好事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好运", "is_correct": true, "explanation": "「真是好运」表示中奖是幸运的事，符合语境。"}, {"text": "好人", "is_correct": false, "explanation": "语义：「好人」指品行好的人，不能用来形容中奖这件事。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：「礼物」是送出或得到的东西，不是遇到的好事。"}, {"text": "奖金", "is_correct": false, "explanation": "搭配：「真是……」后接的是对情况的评价，「奖金」是具体的钱，不能用来评价运气。"}], "explanations": {"好运": "「真是好运」表示中奖是幸运的事，符合语境。", "好人": "语义：「好人」指品行好的人，不能用来形容中奖这件事。", "礼物": "语义：「礼物」是送出或得到的东西，不是遇到的好事。", "奖金": "搭配：「真是……」后接的是对情况的评价，「奖金」是具体的钱，不能用来评价运气。"}, "sentence_index": 0, "correct_answer": "好运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年我的好运一直不太好。", "explanation": "这里应该用〈运气〉。「好运」指让人高兴的好事，不能用来说运气好坏；表示运气的好坏要用〈运气〉。"}, {"text": "这是一只好运，让我很开心。", "explanation": "这里应该用〈份〉。「只」不能数抽象的「好运」，应说「一份好运」。"}, {"text": "他把好运拿去修理了。", "explanation": "「修理」的对象是器物，好运不能被修理，这里不能用这个动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好运", "is_correct": true, "explanation": "「这是我们的好运」表示请客是一件好事，符合语境。"}, {"text": "负担", "is_correct": false, "explanation": "语义：请客是高兴的事，「负担」是压力，与语境相反。"}, {"text": "支出", "is_correct": false, "explanation": "语义：老板请客，钱由老板出，不是“我们的支出”，与语境不符。"}, {"text": "损失", "is_correct": false, "explanation": "语义：「损失」是失去的东西，与老板请客带来的好处相反。"}], "explanations": {"好运": "「这是我们的好运」表示请客是一件好事，符合语境。", "负担": "语义：请客是高兴的事，「负担」是压力，与语境相反。", "支出": "语义：老板请客，钱由老板出，不是“我们的支出”，与语境不符。", "损失": "语义：「损失」是失去的东西，与老板请客带来的好处相反。"}, "sentence_index": 6, "correct_answer": "好运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她递给我一把好运。", "explanation": "「把」用于有柄的器具，不能数抽象的「好运」，应说「一份好运」。"}, {"text": "多锻炼对身体有好运。", "explanation": "这里应该用〈好处〉。「好运」指让人高兴的好事，不能说对身体有好运；说对身体有益要用「好处」。"}, {"text": "他把好运完成了一半。", "explanation": "「完成」用于任务、工作等，好运不能被完成，这里不能用这个动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只好运来得正是时候。", "corrected_sentence": "这份好运来得正是时候。", "error_description": "错误：「这只好运」；正确：「这份好运」。「只」不能用于抽象的好运，要用量词「份」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
