INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好的运气；顺利如意的机遇。", "primary_collocate": null, "pronunciation": "hǎo yùn", "ipa": "xɑu˨˩˦ yn˥˩", "syllable_count": 2, "sentences": [{"text": "祝你考试好运！", "target_word": "好运", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他最近好运不断，工作和生活都很顺利。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我真有好运，刚到车站，车就来了。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这只小猫会带来好运。", "target_word": "好运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的好运终于来了，找到了好工作。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色在中国常常代表好运。", "target_word": "好运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，朋友们都对我说：“好运！”", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直相信自己会有好运。", "target_word": "好运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没有什么好运，只能努力工作。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门旅行，愿你一路都有好运。", "target_word": "好运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好运气", "label": "复合词"}], "register": "中性", "sense_fingerprint": "好的运气、顺利的机遇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好运", "is_correct": true, "explanation": "「祝……好运」是常见的祝福说法，「好运」指顺利的机遇，符合语境。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」不是可以拿来祝愿的内容，「祝你考试味道」说不通。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：「奖金」是发给人的钱，不能作为考试的祝愿对象。"}, {"text": "分数", "is_correct": false, "explanation": "搭配：祝愿语不能直接接「分数」，要说「考出好分数」或「考试顺利」。"}], "explanations": {"好运": "「祝……好运」是常见的祝福说法，「好运」指顺利的机遇，符合语境。", "味道": "语义：「味道」不是可以拿来祝愿的内容，「祝你考试味道」说不通。", "奖金": "语义：「奖金」是发给人的钱，不能作为考试的祝愿对象。", "分数": "搭配：祝愿语不能直接接「分数」，要说「考出好分数」或「考试顺利」。"}, "sentence_index": 0, "correct_answer": "好运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "多吃蔬菜对身体有好运。", "explanation": "这里应该用〈好处〉。「好运」指运气，不能说对身体有好运；说对身体有益要用「好处」。"}, {"text": "他今年有了一只好运。", "explanation": "这里应该用〈份〉。「只」用于动物或成对的物件，不能数抽象的「好运」，应说「一份好运」。"}, {"text": "这次比赛我要参加好运。", "explanation": "「参加」要接比赛、活动等具体事件，「好运」不是可以参加的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好运", "is_correct": true, "explanation": "「好运！」是赛前鼓励的常用说法，符合语境。"}, {"text": "失败", "is_correct": false, "explanation": "语义：「失败」是不好的结果，赛前不能用来鼓励比赛。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：奖杯是比赛结束后得到的奖品，赛前不能这样说。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与比赛鼓励无关，不能作为赛前用语。"}], "explanations": {"好运": "「好运！」是赛前鼓励的常用说法，符合语境。", "失败": "语义：「失败」是不好的结果，赛前不能用来鼓励比赛。", "奖杯": "语义：奖杯是比赛结束后得到的奖品，赛前不能这样说。", "体重": "语义：体重与比赛鼓励无关，不能作为赛前用语。"}, "sentence_index": 6, "correct_answer": "好运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天的好运一直不太好。", "explanation": "这里应该用〈运气〉。「好运」已经指好的运气，不能说“好运不好”；说运气的好坏要用〈运气〉。"}, {"text": "我们收到了一把好运。", "explanation": "「把」用于有柄的器具，不能数抽象的「好运」，应说「一份好运」。"}, {"text": "他把好运提前完成了。", "explanation": "「完成」用于任务、工作等，好运不能被完成，这里不能用这个动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今年有一只好运，考上了大学。", "corrected_sentence": "他今年有一份好运，考上了大学。", "error_description": "错误：「一只好运」；正确：「一份好运」。「只」用于动物或成对的物件，抽象的「好运」要用量词「份」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面试前，老师笑着对我说：“好运们！”", "corrected_sentence": "面试前，老师笑着对我说：“好运！”", "error_description": "错误：「好运们」；正确：「好运」。「好运」是抽象名词，不能加复数后缀「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
