INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "协定是两边说好、都要照着做的约定。", "primary_collocate": null, "pronunciation": "xié dìng", "ipa": "ɕjɛ˧˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们两家有一个协定，每周轮流做饭。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个公司签了一项协定。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的协定，双方都要遵守。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同学有个协定：上课不玩手机。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们没有照着协定做，所以老板生气了。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和我签了一项协定，工作满一年就加钱。", "target_word": "协定", "complexity_tier": "T3", "furigana": "lǎobǎn hé wǒ qiān le yí xiàng xiédìng, gōngzuò mǎn yì nián jiù jiā qián.", "sentence_source": "generated"}, {"text": "这个协定对大家都有好处。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方达成了协定，不再吵架了。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照协定，我们明天九点见面。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟俩的协定是，谁先回家谁做饭。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项协定", "label": "量词（项）"}, {"form": "協定", "label": "繁体"}], "register": "书面", "sense_fingerprint": "协定：双方说好、都要遵守的约定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93121, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协定", "is_correct": true, "explanation": "协定：双方说好、都要照着做的约定，即正确答案。"}, {"text": "鞋钉", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，意思是鞋钉。"}, {"text": "写定", "is_correct": false, "explanation": "xiě（第三声）与 xié（第二声）声调不同，意思是写好并定稿。"}, {"text": "谢顶", "is_correct": false, "explanation": "xiè dǐng（第四声、第三声）与 xié dìng（第二声、第四声）声调不同，意思是头顶的头发脱落。"}], "explanations": {"协定": "协定：双方说好、都要照着做的约定，即正确答案。", "鞋钉": "dīng（第一声）与 dìng（第四声）声调不同，意思是鞋钉。", "写定": "xiě（第三声）与 xié（第二声）声调不同，意思是写好并定稿。", "谢顶": "xiè dǐng（第四声、第三声）与 xié dìng（第二声、第四声）声调不同，意思是头顶的头发脱落。"}, "sentence_index": null, "correct_answer": "协定"}, "level_3": {"options": [{"text": "故事", "is_correct": false, "explanation": "语义：“故事”是讲述的内容，不是双方说好的约定，不能说“我们两家有一个故事”。"}, {"text": "协定", "is_correct": true, "explanation": "协定：双方说好、都要遵守的约定，与“有一个”搭配，符合两家轮流做饭的安排。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，不是约定，不能指两家轮流做饭的安排。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”指性情，不能与“每周轮流做饭”这样的安排搭配。"}], "explanations": {"故事": "语义：“故事”是讲述的内容，不是双方说好的约定，不能说“我们两家有一个故事”。", "协定": "协定：双方说好、都要遵守的约定，与“有一个”搭配，符合两家轮流做饭的安排。", "手机": "语义：“手机”是物品，不是约定，不能指两家轮流做饭的安排。", "脾气": "搭配：“脾气”指性情，不能与“每周轮流做饭”这样的安排搭配。"}, "sentence_index": 0, "correct_answer": "协定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在群里发了一个协定：明天有考试。", "explanation": "这里应该用〈通知〉。协定须双方协商订立，老师单方面发布的消息用通知。"}, {"text": "妈妈给我讲了一个协定，讲的是一只小兔子。", "explanation": "这里应该用〈故事〉。讲出来的、有情节的内容是故事，协定是双方说好要遵守的约定。"}, {"text": "他向我许下一个协定，保证以后不再迟到。", "explanation": "这里应该用〈诺言〉。协定需要双方共同订立，一个人的承诺用诺言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "噪音", "is_correct": false, "explanation": "语义：“噪音”是让人烦躁的声音，不能对大家有好处。"}, {"text": "协定", "is_correct": true, "explanation": "协定：双方订立、共同遵守的约定，与“这个”搭配，符合“对大家都有好处”。"}, {"text": "病菌", "is_correct": false, "explanation": "搭配：“对……有好处”搭配的是有益的事物，“病菌”不能这样搭配。"}, {"text": "废话", "is_correct": false, "explanation": "语义：“废话”指没有实际内容的话，不能对大家有好处。"}], "explanations": {"噪音": "语义：“噪音”是让人烦躁的声音，不能对大家有好处。", "协定": "协定：双方订立、共同遵守的约定，与“这个”搭配，符合“对大家都有好处”。", "病菌": "搭配：“对……有好处”搭配的是有益的事物，“病菌”不能这样搭配。", "废话": "语义：“废话”指没有实际内容的话，不能对大家有好处。"}, "sentence_index": 6, "correct_answer": "协定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长作出了一个协定，取消了周末补课。", "explanation": "这里应该用〈决定〉。协定须经双方协商订立，校长单方面作出的决定用“决定”。"}, {"text": "我制定了一个协定，每天背二十个词。", "explanation": "这里应该用〈计划〉。个人为自己安排的事用计划，协定须由双方订立。"}, {"text": "他定了一个协定：一年内减重十公斤。", "explanation": "这里应该用〈目标〉。协定是双方共同遵守的约定，个人的努力方向用目标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司正在签了一项协定，明年开始执行。", "corrected_sentence": "两家公司正在签一项协定，明年开始执行。", "error_description": "体标错误：“正在”表示动作进行中，不能与完成体“了”同用，应说“正在签一项协定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个俱乐部签了一封协定，互相不抢会员。", "corrected_sentence": "这两个俱乐部签了一项协定，互相不抢会员。", "error_description": "量词错误：“协定”的量词应用“项”，不能用“封”（“封”多用于信件）。正确：这两个俱乐部签了一项协定，互相不抢会员。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
