INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家或团体之间经过协商而订立的共同遵守的条文。", "primary_collocate": null, "pronunciation": "xié dìng", "ipa": "ɕjɛ˧˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "两个国家签订了和平协定。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项协定明年一月开始。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国代表在会上讨论了贸易协定。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的协定写着，双方不打仗。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协定需要两国政府同意。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保协定要求各国少用煤。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个团体签了合作协定。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协定上写着，双方每年见一次面。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家之间的协定，大家都要遵守。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的协定让两国的关系更好了。", "target_word": "协定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项协定", "label": "量词（项）"}, {"form": "協定", "label": "繁体"}], "register": "书面", "sense_fingerprint": "协定：国家或团体之间协商订立的正式条文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93122, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协定", "is_correct": true, "explanation": "协定：国家或团体之间协商订立的共同遵守的条文，即正确答案。"}, {"text": "鞋钉", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，意思是鞋钉。"}, {"text": "写定", "is_correct": false, "explanation": "xiě（第三声）与 xié（第二声）声调不同，意思是写好并定稿。"}, {"text": "结订", "is_correct": false, "explanation": "jié 与 xié 声母不同（j 与 x），意思是订立（合同、协议）。"}], "explanations": {"协定": "协定：国家或团体之间协商订立的共同遵守的条文，即正确答案。", "鞋钉": "dīng（第一声）与 dìng（第四声）声调不同，意思是鞋钉。", "写定": "xiě（第三声）与 xié（第二声）声调不同，意思是写好并定稿。", "结订": "jié 与 xié 声母不同（j 与 x），意思是订立（合同、协议）。"}, "sentence_index": null, "correct_answer": "协定"}, "level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是唱的作品，不能被签订。"}, {"text": "协定", "is_correct": true, "explanation": "协定：国家之间协商订立的条文，与“签订了和平”搭配。"}, {"text": "计划", "is_correct": false, "explanation": "搭配：“签订”多用于协议、条约，计划通常说“制定”，不说“签订”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”是食物，不能被签订。"}], "explanations": {"歌曲": "语义：“歌曲”是唱的作品，不能被签订。", "协定": "协定：国家之间协商订立的条文，与“签订了和平”搭配。", "计划": "搭配：“签订”多用于协议、条约，计划通常说“制定”，不说“签订”。", "蛋糕": "语义：“蛋糕”是食物，不能被签订。"}, "sentence_index": 0, "correct_answer": "协定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家在街头喊出了一个协定：保护地球。", "explanation": "这里应该用〈口号〉。协定是双方订立的约定，街头喊出的话用口号。"}, {"text": "两国足球队踢了一场协定，比分是二比一。", "explanation": "这里应该用〈比赛〉。踢的是比赛，协定是国家或团体之间订立的条文，不能踢。"}, {"text": "各国发表了一份协定，呼吁减少排放。", "explanation": "这里应该用〈宣言〉。“发表”搭配宣言、声明等公开表态，协定需要各方签订，不能发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灯泡", "is_correct": false, "explanation": "语义：“灯泡”是照明的物品，不能与“合作”搭配作修饰语。"}, {"text": "协定", "is_correct": true, "explanation": "协定：双方共同遵守的条文，与“签了合作”搭配，符合两个团体签约的语境。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“合作”修饰的名词应指可以共同进行的事，“眼镜”不能这样搭配。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不是可以共同合作的事，不能说“合作感冒”。"}], "explanations": {"灯泡": "语义：“灯泡”是照明的物品，不能与“合作”搭配作修饰语。", "协定": "协定：双方共同遵守的条文，与“签了合作”搭配，符合两个团体签约的语境。", "眼镜": "搭配：“合作”修饰的名词应指可以共同进行的事，“眼镜”不能这样搭配。", "感冒": "语义：“感冒”是疾病，不是可以共同合作的事，不能说“合作感冒”。"}, "sentence_index": 6, "correct_answer": "协定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国召开了一次协定，讨论边境问题。", "explanation": "这里应该用〈会议〉。召开的是会议，协定是双方订立的文件，不能召开。"}, {"text": "两国之间爆发了协定。", "explanation": "这里应该用〈战争〉。爆发的是战争、冲突等，协定不能爆发。"}, {"text": "两国展开了激烈的协定。", "explanation": "这里应该用〈竞争〉。“激烈”形容竞争、斗争，协定不能用“激烈”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国正在签了一项和平协定，边境终于安静了。", "corrected_sentence": "两国正在签一项和平协定，边境终于安静了。", "error_description": "体标错误：“正在”表示动作进行中，不能与完成体“了”同用，应说“正在签一项和平协定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两家工厂签了一只协定，共同使用一个仓库。", "corrected_sentence": "这两家工厂签了一项协定，共同使用一个仓库。", "error_description": "量词错误：“协定”的量词是“项”，“只”多用于动物等，不能用来数协定。应说“一项协定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
