INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93123, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "妨碍是挡在前面，让别人做不了事。", "primary_collocate": null, "pronunciation": "fáng ài", "ipa": "fɑŋ˧˥ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "你站在门口，妨碍别人进来了。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车停在路中间，妨碍大家走路。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的人站起来，妨碍了我看电影。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别把包放在这儿，会妨碍别人走过去。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的大箱子妨碍了后面的人。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子放在门前，妨碍我们出去。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你坐在中间，妨碍我们过去。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一棵大树长在路边，妨碍车往前开。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩站在车前，妨碍司机开车。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要把东西堆在楼梯上，会妨碍大家上楼。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "妨碍了", "label": "完成体"}, {"form": "妨碍着", "label": "持续体"}, {"form": "妨碍过", "label": "经历体"}, {"form": "妨礙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或物挡在前面，让别人无法通过或做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93123, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妨碍", "is_correct": true, "explanation": "正确。妨碍指挡在前面，使别人无法进来，与句意相符。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：站在门口拥抱别人进来，句意不通。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的对象不是正在进门的人，这句话不成立。"}, {"text": "欢送", "is_correct": false, "explanation": "搭配：“欢送”是送别离开的人，与“进来”方向矛盾。"}], "explanations": {"妨碍": "正确。妨碍指挡在前面，使别人无法进来，与句意相符。", "拥抱": "语义：站在门口拥抱别人进来，句意不通。", "参观": "语义：“参观”的对象不是正在进门的人，这句话不成立。", "欢送": "搭配：“欢送”是送别离开的人，与“进来”方向矛盾。"}, "sentence_index": 0, "correct_answer": "妨碍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一把大伞妨碍了雨水。", "explanation": "这里应该用〈挡住〉。妨碍用于阻碍人或事情，不能说“妨碍雨水”。"}, {"text": "我每天早上妨碍一杯牛奶。", "explanation": "这里应该用〈喝〉。妨碍表示挡住别人做事，不能用于喝牛奶。"}, {"text": "我们一起妨碍了这个下午。", "explanation": "这里应该用〈浪费〉。妨碍的对象是事情，不能说“妨碍这个下午”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妨碍", "is_correct": true, "explanation": "正确。“你坐在中间，妨碍我们过去”句意通顺，表示挡住了路。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：坐在中间不能“挑选”我们过去，句意不通。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识我们过去”没有意义，与“坐在中间”不搭。"}, {"text": "关闭", "is_correct": false, "explanation": "搭配：“关闭”通常搭配门、路等对象，不能说“关闭我们过去”。"}], "explanations": {"妨碍": "正确。“你坐在中间，妨碍我们过去”句意通顺，表示挡住了路。", "挑选": "语义：坐在中间不能“挑选”我们过去，句意不通。", "认识": "语义：“认识我们过去”没有意义，与“坐在中间”不搭。", "关闭": "搭配：“关闭”通常搭配门、路等对象，不能说“关闭我们过去”。"}, "sentence_index": 6, "correct_answer": "妨碍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "麻烦您了，我妨碍您一下。", "explanation": "这里应该用〈打扰〉。妨碍表示使事情受阻，不能用于礼貌地占用别人的时间。"}, {"text": "老师认真地妨碍学生。", "explanation": "这里应该用〈指导〉。妨碍表示阻碍，老师的职责是帮助学生，“老师妨碍学生”与常理相反。"}, {"text": "他妨碍了坏掉的门。", "explanation": "这里应该用〈修理〉。妨碍的对象是人或事情，不能用于门这样的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车停在路口，被妨碍了大家通行。", "corrected_sentence": "车停在路口，妨碍了大家通行。", "error_description": "“被”字句要以受事作主语，这里“车”是施事，不能在“妨碍”前加“被”。应去掉“被”，说“车停在路口，妨碍了大家通行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前面的树倒了，妨碍。", "corrected_sentence": "前面的树倒了，妨碍车辆通行。", "error_description": "“妨碍”是及物动词，后面需要带宾语，说明被妨碍的对象。句中缺少宾语，应补为“妨碍车辆通行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93124, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "促进", "is_correct": true, "explanation": "正确。促进与“妨碍”意思相反，指推动事情顺利进行。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是动词，但与“妨碍”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理是动词，但与“妨碍”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察是动词，但与“妨碍”没有反义关系。"}], "correct_answer": "促进", "explanations": {"促进": "正确。促进与“妨碍”意思相反，指推动事情顺利进行。", "讨论": "讨论是动词，但与“妨碍”没有反义关系。", "整理": "整理是动词，但与“妨碍”没有反义关系。", "观察": "观察是动词，但与“妨碍”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
