INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93124, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使事情不能顺利进行；阻碍。", "primary_collocate": null, "pronunciation": "fáng ài", "ipa": "fɑŋ˧˥ aɪ˥˩", "syllable_count": 2, "sentences": [{"text": "大雨妨碍了我们的比赛。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧习惯会妨碍你进步。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的车太多，妨碍了交通。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噪音妨碍他认真学习。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要妨碍我工作。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏天气妨碍了飞机起飞。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小问题不会妨碍大家的计划。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡得太少会妨碍身体健康。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话太大声，妨碍了别人休息。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事一点也不妨碍我们见面。", "target_word": "妨碍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "妨碍了", "label": "完成体"}, {"form": "妨碍着", "label": "持续体"}, {"form": "妨碍过", "label": "经历体"}, {"form": "妨礙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使事情、计划或工作无法顺利进行的阻碍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妨碍", "is_correct": true, "explanation": "正确。妨碍指使事情不能顺利进行，“大雨妨碍了我们的比赛”句意通顺。"}, {"text": "加快", "is_correct": false, "explanation": "语义：大雨只会让比赛变慢，不能“加快”比赛。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”需要有人作施事，“大雨”不能参加比赛。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：大雨不会帮助比赛顺利进行，句意与常理相反。"}], "explanations": {"妨碍": "正确。妨碍指使事情不能顺利进行，“大雨妨碍了我们的比赛”句意通顺。", "加快": "语义：大雨只会让比赛变慢，不能“加快”比赛。", "参加": "配价：“参加”需要有人作施事，“大雨”不能参加比赛。", "帮助": "语义：大雨不会帮助比赛顺利进行，句意与常理相反。"}, "sentence_index": 0, "correct_answer": "妨碍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "对不起，我妨碍你一下，可以问个问题吗？", "explanation": "这里应该用〈打扰〉。妨碍指使事情不能顺利进行，不能用于礼貌地占用别人的时间。"}, {"text": "我很喜欢妨碍音乐。", "explanation": "这里应该用〈听〉。妨碍是使事情不能顺利进行，不能表示喜欢听音乐。"}, {"text": "他一下午都在妨碍时间。", "explanation": "这里应该用〈浪费〉。妨碍的对象是事情的进行，不能说“妨碍时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妨碍", "is_correct": true, "explanation": "正确。妨碍表示阻碍，“这点小问题不会妨碍大家的计划”句意通顺。"}, {"text": "支持", "is_correct": false, "explanation": "语义：小问题不能“支持”计划，句意与常理不符。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”通常搭配人或建议，不说“欢迎计划”。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：小问题不会赞美计划，这个词与句子的语境不符。"}], "explanations": {"妨碍": "正确。妨碍表示阻碍，“这点小问题不会妨碍大家的计划”句意通顺。", "支持": "语义：小问题不能“支持”计划，句意与常理不符。", "欢迎": "搭配：“欢迎”通常搭配人或建议，不说“欢迎计划”。", "赞美": "语义：小问题不会赞美计划，这个词与句子的语境不符。"}, "sentence_index": 6, "correct_answer": "妨碍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们去妨碍老朋友。", "explanation": "这里应该用〈拜访〉。妨碍是使事情受阻，不能用于去看望朋友。"}, {"text": "护士认真地妨碍病人。", "explanation": "这里应该用〈照顾〉。妨碍表示阻碍，护士的职责是照顾病人，“护士妨碍病人”与常理相反。"}, {"text": "我每天晚上都妨碍一本书。", "explanation": "这里应该用〈看〉。妨碍是使事情受阻，不能用于读书这件事本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事被妨碍了我们的工作。", "corrected_sentence": "这件事妨碍了我们的工作。", "error_description": "“被”字句要以受事作主语，这里“这件事”是施事，不能在“妨碍”前加“被”。应去掉“被”，说“这件事妨碍了我们的工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场大雨妨碍。", "corrected_sentence": "这场大雨妨碍我们出去玩。", "error_description": "“妨碍”是及物动词，后面需要带宾语，说明被妨碍的事。句中缺少宾语，应补为“妨碍我们出去玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
