INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "怀有身孕的妇女。", "primary_collocate": null, "pronunciation": "yùn fù", "ipa": "yn˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "孕妇应该定期去医院检查身体。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅为孕妇准备了特别的菜。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕妇不能喝酒，也不能抽烟。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位怀孕八个月的孕妇。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车上的孕妇扶着座位站着。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给孕妇安排了轻松的工作。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁车厢里设有孕妇专座。", "target_word": "孕妇", "complexity_tier": "T3", "furigana": "dì tiě chē xiāng lǐ shè yǒu yùnfù zhuānzuò。", "sentence_source": "generated"}, {"text": "医院里有很多孕妇在排队。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孕妇吃药前要先问医生。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律保护孕妇的工作权利。", "target_word": "孕妇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "孕妇装", "label": "复合"}], "register": "中性", "sense_fingerprint": "怀有身孕的妇女，常用于医疗、公共服务等场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecaec501-a7ea-4216-b684-7b1fdd95ce2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孕妇", "is_correct": true, "explanation": "孕妇：怀孕的妇女，应定期去医院做检查，与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不去医院检查身体，应去修车厂保养。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“检查身体”的主语必须是有身体的生物，石头不能作主语。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有身体，也不会去医院检查。"}], "explanations": {"孕妇": "孕妇：怀孕的妇女，应定期去医院做检查，与句意相符。", "汽车": "语义：汽车不去医院检查身体，应去修车厂保养。", "石头": "配价：“检查身体”的主语必须是有身体的生物，石头不能作主语。", "窗户": "语义：窗户没有身体，也不会去医院检查。"}, "sentence_index": 0, "correct_answer": "孕妇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位孕妇刚出月子，正在家里休养。", "explanation": "这里应该用〈产妇〉。出月子、休养的是刚生完孩子的妈妈；孕妇还没生，不能说“出月子”。"}, {"text": "孕妇在肚子里翻了个身。", "explanation": "这里应该用〈胎儿〉。翻身的是肚子里的胎儿，孕妇是怀孕的妈妈。"}, {"text": "孕妇一出生就哭个不停。", "explanation": "这里应该用〈婴儿〉。刚出生就哭个不停的是婴儿；孕妇是怀孕的妈妈，不能说“一出生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孕妇", "is_correct": true, "explanation": "孕妇：怀孕的妇女，“孕妇专座”是为她们设的座位。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是坐的人，“专座”指供人坐的座位。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能坐，与“专座”的用途相矛盾。"}, {"text": "老虎", "is_correct": false, "explanation": "搭配：“专座”是给人坐的，不能说“老虎专座”。"}], "explanations": {"孕妇": "孕妇：怀孕的妇女，“孕妇专座”是为她们设的座位。", "垃圾": "语义：垃圾不是坐的人，“专座”指供人坐的座位。", "玻璃": "语义：玻璃不能坐，与“专座”的用途相矛盾。", "老虎": "搭配：“专座”是给人坐的，不能说“老虎专座”。"}, "sentence_index": 6, "correct_answer": "孕妇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "候车室里坐着一条孕妇。", "explanation": "这里应该用〈位〉或〈个〉。“条”用于细长的东西，不能用来数人。"}, {"text": "公园里走来一头孕妇。", "explanation": "这里应该用〈位〉或〈个〉。“头”多用于大型牲畜，不能用来数人。"}, {"text": "广场上站着一块孕妇。", "explanation": "这里应该用〈位〉或〈个〉。“块”用于块状的东西，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位孕妇们在医院门口等着。", "corrected_sentence": "两位孕妇在医院门口等着。", "error_description": "错误：数量词“两位”后又加了“们”。正确：“两位孕妇”。有数量词时，名词后不再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地铁车厢里还坐着一只孕妇。", "corrected_sentence": "地铁车厢里还坐着一位孕妇。", "error_description": "错误：量词“只”。正确：“位”。指人应用“位”或“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
