INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93130, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问处所。", "primary_collocate": null, "pronunciation": "nǎr", "ipa": "nɑɻ˨˩˦", "syllable_count": 1, "sentences": [{"text": "你去哪儿？", "target_word": "哪儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你家住在哪儿？", "target_word": "哪儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末你想去哪儿玩？", "target_word": "哪儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是从哪儿来的？", "target_word": "哪儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你在哪儿工作？", "target_word": "哪儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们明天在哪儿见面？", "target_word": "哪儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你在哪儿学的汉语？", "target_word": "哪儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你去过哪儿？", "target_word": "哪儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件衣服你是在哪儿买的？", "target_word": "哪儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "放假的时候，你打算去哪儿旅游？", "target_word": "哪儿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "哪兒", "label": "繁体"}], "register": "口语", "sense_fingerprint": "疑问代词，询问处所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df81c267-6b39-4d12-95ab-3643a04c33bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哪儿", "is_correct": true, "explanation": "哪儿（nǎ er，实际多读作 nǎr），疑问代词，问处所。"}, {"text": "那儿", "is_correct": false, "explanation": "nàr（第四声）与 nǎr（第三声）声调不同，意思是“那儿”，指示某处，不是疑问。"}, {"text": "拿", "is_correct": false, "explanation": "ná（第二声），没有儿化，与 nǎr 声调不同；意思是“用手取”，是动词。"}, {"text": "那", "is_correct": false, "explanation": "nà（第四声），没有儿化，与 nǎr 声调不同；是指示代词，不是疑问。"}, {"text": "纳", "is_correct": false, "explanation": "nà（第四声），与 nǎr 声调不同；意思是“接受、收入”，与处所无关。"}], "explanations": {"哪儿": "哪儿（nǎ er，实际多读作 nǎr），疑问代词，问处所。", "那儿": "nàr（第四声）与 nǎr（第三声）声调不同，意思是“那儿”，指示某处，不是疑问。", "拿": "ná（第二声），没有儿化，与 nǎr 声调不同；意思是“用手取”，是动词。", "那": "nà（第四声），没有儿化，与 nǎr 声调不同；是指示代词，不是疑问。", "纳": "nà（第四声），与 nǎr 声调不同；意思是“接受、收入”，与处所无关。"}, "sentence_index": null, "correct_answer": "哪儿"}, "level_3": {"options": [{"text": "哪儿", "is_correct": true, "explanation": "“你去哪儿”问去的地方，与“去”搭配，句意通顺，是正确答案。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“去”要接处所，不能接人，“你去谁”句意不通。"}, {"text": "哪位", "is_correct": false, "explanation": "语义：“哪位”问哪一个人，不问去的地方。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：“哪些”问多个事物，不问去的地方，句意不通。"}], "explanations": {"哪儿": "“你去哪儿”问去的地方，与“去”搭配，句意通顺，是正确答案。", "谁": "配价：“去”要接处所，不能接人，“你去谁”句意不通。", "哪位": "语义：“哪位”问哪一个人，不问去的地方。", "哪些": "语义：“哪些”问多个事物，不问去的地方，句意不通。"}, "sentence_index": 0, "correct_answer": "哪儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这三件衣服里，你最喜欢哪儿？", "explanation": "这里应该用〈哪件〉。“哪儿”问处所，从几件衣服里挑一件要用“哪件”。"}, {"text": "你哪儿这么着急？", "explanation": "这里应该用〈为什么〉或〈怎么〉。“哪儿”问处所，问原因不能用“哪儿”。"}, {"text": "这几个朋友里，你最信任哪儿？", "explanation": "这里应该用〈哪一位〉或〈哪个〉。“哪儿”问处所，从几个人中选一个要用“哪位”或“哪个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93130, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哪儿", "is_correct": true, "explanation": "哪儿（nǎ er，实际多读作 nǎr），疑问代词，问处所。"}, {"text": "钠", "is_correct": false, "explanation": "nà（第四声），没有儿化，与 nǎr 声调不同；是一种化学元素，与处所无关。"}, {"text": "捺", "is_correct": false, "explanation": "nà（第四声），与 nǎr 声调不同；指汉字笔画“捺”或用手按，不是疑问词。"}, {"text": "奶", "is_correct": false, "explanation": "nǎi（第三声），声调与 nǎr 相同，但韵母是 ai，不是儿化的 ar；意思是“奶、牛奶”。"}], "explanations": {"哪儿": "哪儿（nǎ er，实际多读作 nǎr），疑问代词，问处所。", "钠": "nà（第四声），没有儿化，与 nǎr 声调不同；是一种化学元素，与处所无关。", "捺": "nà（第四声），与 nǎr 声调不同；指汉字笔画“捺”或用手按，不是疑问词。", "奶": "nǎi（第三声），声调与 nǎr 相同，但韵母是 ai，不是儿化的 ar；意思是“奶、牛奶”。"}, "sentence_index": null, "correct_answer": "哪儿"}, "level_3": {"options": [{"text": "哪儿", "is_correct": true, "explanation": "“你在哪儿学的汉语”问学习的地方，与“在”搭配，句意通顺，是正确答案。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”问事物，不问学习的场所，“在什么学”句意不通。"}, {"text": "多少", "is_correct": false, "explanation": "搭配：“多少”是数量，不能作“在”的处所，句意不通。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”问具体哪一个，不问学习的地方。"}], "explanations": {"哪儿": "“你在哪儿学的汉语”问学习的地方，与“在”搭配，句意通顺，是正确答案。", "什么": "语义：“什么”问事物，不问学习的场所，“在什么学”句意不通。", "多少": "搭配：“多少”是数量，不能作“在”的处所，句意不通。", "哪个": "语义：“哪个”问具体哪一个，不问学习的地方。"}, "sentence_index": 6, "correct_answer": "哪儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两道题里，哪儿更难？", "explanation": "这里应该用〈哪道〉或〈哪个〉。“哪儿”问处所，从几道题中选一道要用“哪道”。"}, {"text": "这几种水果里，哪儿最好吃？", "explanation": "这里应该用〈哪种〉。“哪儿”问处所，从几种水果中挑一种要用“哪种”。"}, {"text": "这三个方案里，你选哪儿？", "explanation": "这里应该用〈哪个〉。“哪儿”问处所，选的是方案，要问具体哪一个用“哪个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你明天想哪儿吃饭？", "corrected_sentence": "你明天想去哪儿吃饭？", "error_description": "“想”后面不能直接接“哪儿”，表示处所前要先加介词“在”或动词“去”。应说“想去哪儿吃饭”或“想在哪儿吃饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你在哪儿里买的书？", "corrected_sentence": "你在哪儿买的书？", "error_description": "“哪儿”后面不能再加“里”，多出的“里”是多余的。应说“在哪儿买的书”，去掉“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72d4ba4f-26a6-401a-a7cf-4f3bd8c05067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "货运", "is_correct": true, "explanation": "货运：运送货物，与运送旅客的客运正相对，是反义关系。"}, {"text": "书籍", "is_correct": false, "explanation": "书籍：印刷的书本，与客运没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气：大气的冷暖阴晴，与客运无关，不是反义词。"}, {"text": "花园", "is_correct": false, "explanation": "花园：种植花草的场地，与客运没有反义关系。"}], "correct_answer": "货运", "explanations": {"货运": "货运：运送货物，与运送旅客的客运正相对，是反义关系。", "书籍": "书籍：印刷的书本，与客运没有反义关系。", "天气": "天气：大气的冷暖阴晴，与客运无关，不是反义词。", "花园": "花园：种植花草的场地，与客运没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "货运", "is_correct": true, "explanation": "货运：运送货物，与运送旅客的客运正相对，是反义关系。"}, {"text": "课桌", "is_correct": false, "explanation": "课桌：学生用来写字的桌子，与客运没有反义关系。"}, {"text": "雨水", "is_correct": false, "explanation": "雨水：从天上落下的水，与客运无关，不是反义词。"}, {"text": "窗帘", "is_correct": false, "explanation": "窗帘：挂在窗户上遮光的布，与客运没有反义关系。"}], "correct_answer": "货运", "explanations": {"货运": "货运：运送货物，与运送旅客的客运正相对，是反义关系。", "课桌": "课桌：学生用来写字的桌子，与客运没有反义关系。", "雨水": "雨水：从天上落下的水，与客运无关，不是反义词。", "窗帘": "窗帘：挂在窗户上遮光的布，与客运没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "客运是用车、船、飞机来送人。", "primary_collocate": null, "pronunciation": "kè yùn", "ipa": "kʰɤ˥˩ yn˥˩", "syllable_count": 2, "sentences": [{"text": "这辆大车只做客运，不拉货。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河上的客运很方便，天天有船。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机客运比火车客运快。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做客运，也做货运。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，火车客运特别忙。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的客运只有一辆小巴。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的客运很发达，地铁和公交都很方便。", "target_word": "客运", "complexity_tier": "T3", "furigana": "zhè zuò chéng shì de kèyùn hěn fādá, dìtiě hé gōngjiāo dōu hěn fāngbiàn。", "sentence_source": "generated"}, {"text": "海上客运今天因为大风停了。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车以前运货，现在改做客运了。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小岛上的客运靠一条小船。", "target_word": "客运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "客運", "label": "繁体"}, {"form": "客运站", "label": "复合"}], "register": "中性", "sense_fingerprint": "用车、船、飞机运送乘客这件事，与货运相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecaec501-a7ea-4216-b684-7b1fdd95ce2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客运", "is_correct": true, "explanation": "客运：运送乘客的运输业务，与“不拉货”不矛盾。"}, {"text": "货运", "is_correct": false, "explanation": "语义：货运就是拉货，与“不拉货”正好相反。"}, {"text": "快递", "is_correct": false, "explanation": "语义：快递是运送货物，与“不拉货”相矛盾。"}, {"text": "广告", "is_correct": false, "explanation": "搭配：大车“只做”的应是运输业务，不宜说“只做广告”。"}], "explanations": {"客运": "客运：运送乘客的运输业务，与“不拉货”不矛盾。", "货运": "语义：货运就是拉货，与“不拉货”正好相反。", "快递": "语义：快递是运送货物，与“不拉货”相矛盾。", "广告": "搭配：大车“只做”的应是运输业务，不宜说“只做广告”。"}, "sentence_index": 0, "correct_answer": "客运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车上的客运很多，大家都挤不动。", "explanation": "这里应该用〈旅客〉。客运是运输业务，不指乘车的人。"}, {"text": "这家公司的客运连货物也运，很划算。", "explanation": "这里应该用〈运输〉。客运专指运送旅客的业务，连货物也运要说〈运输〉，不能用“客运”。"}, {"text": "这家公司今天来了很多客运，大家都在招待。", "explanation": "这里应该用〈客人〉。客运是运输业务，不指来访的人，不能说“来了很多客运”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客运", "is_correct": true, "explanation": "客运：运送旅客的运输业务，这里指城市的客运业务很发达。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不能用“发达”来形容，与句意不合。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠与地铁、公交的方便程度无关，句意不通。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“发达”一般不修饰雨水，且与地铁和公交的便利无关。"}], "explanations": {"客运": "客运：运送旅客的运输业务，这里指城市的客运业务很发达。", "海洋": "语义：海洋不能用“发达”来形容，与句意不合。", "沙漠": "语义：沙漠与地铁、公交的方便程度无关，句意不通。", "雨水": "搭配：“发达”一般不修饰雨水，且与地铁和公交的便利无关。"}, "sentence_index": 6, "correct_answer": "客运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "岸边停着一条客运，我们马上就要上去了。", "explanation": "这里应该用〈客船〉。停在岸边、可以上去的是船；客运是运送旅客的业务，不是具体的船。"}, {"text": "我坐的客运在高速路上开得很快。", "explanation": "这里应该用〈客车〉。在路上开的是车；客运是运输业务，不能“开”。"}, {"text": "客运们排着队上车。", "explanation": "这里应该用〈旅客〉。排队上车的是人；客运是运输业务，不指乘客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司地客运业务发展得很快。", "corrected_sentence": "这家公司的客运业务发展得很快。", "error_description": "错误：修饰名词“客运业务”应用“的”，不用“地”。正确：「这家公司的客运业务发展得很快。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐客运去了海边。", "corrected_sentence": "我们坐客车去了海边。", "error_description": "错误：“坐客运”。正确：“坐客车”。客运是运送旅客的业务，人坐的是车，不能“坐客运”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
