INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天坐客运去上班。", "corrected_sentence": "他每天坐客车去上班。", "error_description": "错误：“坐客运”。正确：“坐客车”。客运指运送旅客的业务，人坐的是车，不能“坐客运”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c186f8d-509b-4e07-97b6-af0c203e1648') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93133, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "罕见", "is_correct": true, "explanation": "罕见：与“寻常”构成反义，指很少见，与“常常能见到”相反。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：清楚形容明白，与“寻常”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：干净形容洁净，与“寻常”没有反义关系。"}, {"text": "响亮", "is_correct": false, "explanation": "无关：响亮形容声音大，与“寻常”没有反义关系。"}], "correct_answer": "罕见", "explanations": {"罕见": "罕见：与“寻常”构成反义，指很少见，与“常常能见到”相反。", "清楚": "无关：清楚形容明白，与“寻常”没有反义关系。", "干净": "无关：干净形容洁净，与“寻常”没有反义关系。", "响亮": "无关：响亮形容声音大，与“寻常”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93133, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少见", "is_correct": true, "explanation": "少见：与“寻常”构成反义，指不常见。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：柔软形容质地，与“寻常”没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：寒冷形容温度，与“寻常”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：明亮形容光线，与“寻常”没有反义关系。"}], "correct_answer": "少见", "explanations": {"少见": "少见：与“寻常”构成反义，指不常见。", "柔软": "无关：柔软形容质地，与“寻常”没有反义关系。", "寒冷": "无关：寒冷形容温度，与“寻常”没有反义关系。", "明亮": "无关：明亮形容光线，与“寻常”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93133, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "寻常是很普通，常常能见到。", "primary_collocate": null, "pronunciation": "xún cháng", "ipa": "ɕyn˧˥ ʈʂʰaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "在我们那里，吃面条是很寻常的事。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小鸟很寻常，公园里到处都有。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住在一间寻常的小房子里。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在，手机支付已经很寻常了。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的雨天，在南方十分寻常。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寻常人家的孩子也能上大学了。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是一道寻常的家常菜，各家餐桌上都能见到。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天做着寻常的工作，没有什么特别的。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果很寻常，菜市场里随处可见。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年吃饺子，在北方是再寻常不过的事。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不寻常", "label": "否定"}], "register": "书面", "sense_fingerprint": "寻常：很普通，常常能见到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93133, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寻常", "is_correct": true, "explanation": "寻常：很普通、常常能见到。句中指在那里吃面条很普遍。"}, {"text": "高大", "is_correct": false, "explanation": "语义：高大形容体型或规模，不能用来形容吃面条这件事。"}, {"text": "方正", "is_correct": false, "explanation": "搭配：“方正”形容形状，不能说“很方正的事”。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：清澈形容液体或声音透明，不能用来形容事情。"}], "explanations": {"寻常": "寻常：很普通、常常能见到。句中指在那里吃面条很普遍。", "高大": "语义：高大形容体型或规模，不能用来形容吃面条这件事。", "方正": "搭配：“方正”形容形状，不能说“很方正的事”。", "清澈": "语义：清澈形容液体或声音透明，不能用来形容事情。"}, "sentence_index": 0, "correct_answer": "寻常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种宝石非常寻常，很难找到。", "explanation": "这里应该用〈稀有〉。稀有指数量很少，与“很难找到”相合；寻常表示普通，与之矛盾。"}, {"text": "十月下雪，这在当地十分寻常，大家都很惊讶。", "explanation": "这里应该用〈反常〉。反常指不合常规，与“大家都很惊讶”相合；寻常表示普通，与之矛盾。"}, {"text": "他的做法很寻常，大家都在笑他。", "explanation": "这里应该用〈奇特〉。奇特指与众不同，与“大家都在笑他”相合；寻常表示普通，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93133, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寻常", "is_correct": true, "explanation": "寻常：普通、常见。句中指这是一道普通的家常菜。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：辽阔形容面积大，不能用来形容菜。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：嘹亮形容声音，不能用来形容菜。"}, {"text": "崎岖", "is_correct": false, "explanation": "语义：崎岖形容道路不平，不能用来形容菜。"}], "explanations": {"寻常": "寻常：普通、常见。句中指这是一道普通的家常菜。", "辽阔": "语义：辽阔形容面积大，不能用来形容菜。", "嘹亮": "语义：嘹亮形容声音，不能用来形容菜。", "崎岖": "语义：崎岖形容道路不平，不能用来形容菜。"}, "sentence_index": 6, "correct_answer": "寻常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种病在本地很寻常，医生也很惊讶。", "explanation": "这里应该用〈少见〉。少见指不常见，与“医生也很惊讶”相合；寻常表示普通，与之矛盾。"}, {"text": "这次的成绩很寻常，老师都吃了一惊。", "explanation": "这里应该用〈惊人〉。惊人指令人吃惊，与“老师都吃了一惊”相合；寻常表示普通，与之矛盾。"}, {"text": "这个礼物很寻常，只有他能想出来。", "explanation": "这里应该用〈特别〉。特别指与众不同，与“只有他能想出来”相合；寻常表示普通，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种饭菜在我家寻常。", "corrected_sentence": "这种饭菜在我家很寻常。", "error_description": "缺少程度副词：形容词“寻常”作谓语一般需带程度副词，正确为“很寻常”，不说单独的“寻常”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天的生活并没寻常。", "corrected_sentence": "他每天的生活并不寻常。", "error_description": "否定误用：形容词“寻常”前应用“并不”，不用“并没”，正确为“并不寻常”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
