INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93134, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非凡", "is_correct": true, "explanation": "非凡：与“寻常”构成反义，指超出一般。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：柔软形容质地，与“寻常”没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：寒冷形容温度，与“寻常”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：明亮形容光线，与“寻常”没有反义关系。"}], "correct_answer": "非凡", "explanations": {"非凡": "非凡：与“寻常”构成反义，指超出一般。", "柔软": "无关：柔软形容质地，与“寻常”没有反义关系。", "寒冷": "无关：寒冷形容温度，与“寻常”没有反义关系。", "明亮": "无关：明亮形容光线，与“寻常”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93134, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "平常；普通。", "primary_collocate": null, "pronunciation": "xún cháng", "ipa": "ɕyn˧˥ ʈʂʰaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这件事看起来很寻常，其实不简单。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对寻常百姓来说，平安就是最大的幸福。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的天气很不寻常，十月竟然下雪了。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着一件很寻常的灰色外套。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个小镇，下雨天停电是寻常事。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个寻常的星期二，我照常去上班。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的声音有点不寻常，好像哭过。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜很寻常，但是味道不错。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种症状不是寻常的感冒。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张一辈子过着寻常人的日子。", "target_word": "寻常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不寻常", "label": "否定"}], "register": "书面", "sense_fingerprint": "寻常：平常、普通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寻常", "is_correct": true, "explanation": "寻常：平常、普通。句中指这件事表面看起来普通，与“其实不简单”形成对照。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：明亮形容光线或颜色，不能用来形容事情看起来的样子。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：潮湿形容含水多的状态，不能用来形容事情看起来的样子。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：冰凉形容温度低，不能用来形容事情。"}], "explanations": {"寻常": "寻常：平常、普通。句中指这件事表面看起来普通，与“其实不简单”形成对照。", "明亮": "语义：明亮形容光线或颜色，不能用来形容事情看起来的样子。", "潮湿": "语义：潮湿形容含水多的状态，不能用来形容事情看起来的样子。", "冰凉": "语义：冰凉形容温度低，不能用来形容事情。"}, "sentence_index": 0, "correct_answer": "寻常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的声音很寻常，好像刚哭过。", "explanation": "这里应该用〈异常〉。异常指与平常不同的反常状态；寻常表示普通，与“好像刚哭过”的反常情形矛盾。"}, {"text": "他的表演很寻常，全场观众都站了起来。", "explanation": "这里应该用〈非凡〉。非凡指超出一般，与“全场观众都站了起来”相合；寻常表示普通，与之矛盾。"}, {"text": "这种花十分寻常，只在高山上才能看到。", "explanation": "这里应该用〈罕见〉。罕见指很少见，与“只在高山上才能看到”相合；寻常表示普通，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寻常", "is_correct": true, "explanation": "寻常：平常、普通。句中“不寻常”指声音和平常不一样，好像哭过。"}, {"text": "高大", "is_correct": false, "explanation": "语义：高大形容体型或事物的规模，不能用来形容声音。"}, {"text": "方正", "is_correct": false, "explanation": "搭配：“方正”形容形状，不能说“声音有点不方正”。"}, {"text": "笔直", "is_correct": false, "explanation": "搭配：“笔直”形容线条或姿态，不能用于声音。"}], "explanations": {"寻常": "寻常：平常、普通。句中“不寻常”指声音和平常不一样，好像哭过。", "高大": "语义：高大形容体型或事物的规模，不能用来形容声音。", "方正": "搭配：“方正”形容形状，不能说“声音有点不方正”。", "笔直": "搭配：“笔直”形容线条或姿态，不能用于声音。"}, "sentence_index": 6, "correct_answer": "寻常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个发现很寻常，同行都吃了一惊。", "explanation": "这里应该用〈惊人〉。惊人指令人吃惊，与“同行都吃了一惊”相合；寻常表示普通，与之矛盾。"}, {"text": "他的经历很寻常，很少有人能理解。", "explanation": "这里应该用〈奇特〉。奇特指与众不同，与“很少有人能理解”相合；寻常表示普通，与之矛盾。"}, {"text": "这种情况很寻常，医生也很吃惊。", "explanation": "这里应该用〈少有〉。少有指很少见，与“医生也很吃惊”相合；寻常表示普通，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事寻常，我没有太在意。", "corrected_sentence": "这件事很寻常，我没有太在意。", "error_description": "缺少程度副词：形容词“寻常”作谓语一般需带程度副词，正确为“很寻常”，不说单独的“这件事寻常”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的反应一点都没寻常。", "corrected_sentence": "他的反应一点都不寻常。", "error_description": "否定误用：形容词“寻常”前应用“不”，不用“没”，正确为“不寻常”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
