INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93141, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大人是已经长大的人。", "primary_collocate": null, "pronunciation": "dà ren", "ipa": "ta˥˩ ʐən", "syllable_count": 2, "sentences": [{"text": "这个游戏大人也喜欢玩。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大人和孩子都来了。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已经是大人了，要自己做决定。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书是给大人看的。", "target_word": "大人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子睡了，大人还在聊天。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大人坐前面，小孩坐后面。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电影票大人五十块，小孩三十块。", "target_word": "大人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想快点长成大人。", "target_word": "大人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈说这是大人的事，小孩别问。", "target_word": "大人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩要跟着大人过马路。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大人们", "label": "复数"}, {"form": "一位大人", "label": "量词"}], "register": "口语", "sense_fingerprint": "大人：与小孩相对的成年人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8d98bf-ca56-4497-b80d-a8800a5dfbfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93141, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大人", "is_correct": true, "explanation": "正确：大人（dà ren）指与小孩相对的成年人。"}, {"text": "打人", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是殴打他人。"}, {"text": "达人", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是在某方面很有造诣的人。"}, {"text": "带人", "is_correct": false, "explanation": "dài 与 dà 韵母不同（ai 与 a），意思是带领他人。"}], "explanations": {"大人": "正确：大人（dà ren）指与小孩相对的成年人。", "打人": "dǎ（第三声）与 dà（第四声）声调不同，意思是殴打他人。", "达人": "dá（第二声）与 dà（第四声）声调不同，意思是在某方面很有造诣的人。", "带人": "dài 与 dà 韵母不同（ai 与 a），意思是带领他人。"}, "sentence_index": null, "correct_answer": "大人"}, "level_3": {"options": [{"text": "大树", "is_correct": false, "explanation": "语义：“大树”指植物，不能作“喜欢玩”的主语。"}, {"text": "大人", "is_correct": true, "explanation": "正确：“大人”指成年人，与“也喜欢玩”搭配自然。"}, {"text": "大学", "is_correct": false, "explanation": "语义：“大学”是学校，不能作“喜欢玩”的主语。"}, {"text": "大米", "is_correct": false, "explanation": "搭配：“大米”是食物，不能与“喜欢玩”搭配。"}], "explanations": {"大树": "语义：“大树”指植物，不能作“喜欢玩”的主语。", "大人": "正确：“大人”指成年人，与“也喜欢玩”搭配自然。", "大学": "语义：“大学”是学校，不能作“喜欢玩”的主语。", "大米": "搭配：“大米”是食物，不能与“喜欢玩”搭配。"}, "sentence_index": 0, "correct_answer": "大人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位大人是我的同学，很和气。", "explanation": "这里不能用〈大人〉指同学。“大人”作尊称时指长辈或官员，不能用来称呼同龄人；指同学要说“同学”。"}, {"text": "我的邻居是一条大人。", "explanation": "这里应该用〈位〉或〈个〉。“大人”指人，量词用“位”或“个”，“条”不能用于人。"}, {"text": "夜校开设了大人英语课。", "explanation": "这里应该用〈成人〉。“大人”是口语用词，不能修饰“英语课”这类书面词；应说“成人英语课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大海", "is_correct": false, "explanation": "语义：“大海”指海洋，不是票的种类，不能作票价的主语。"}, {"text": "大人", "is_correct": true, "explanation": "正确：“大人票”指成人的票，与“小孩三十块”对应。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：“大楼”指建筑，不能作票价的主语。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：“大门”是建筑部件，与“票”和“五十块”搭配不当。"}], "explanations": {"大海": "语义：“大海”指海洋，不是票的种类，不能作票价的主语。", "大人": "正确：“大人票”指成人的票，与“小孩三十块”对应。", "大楼": "语义：“大楼”指建筑，不能作票价的主语。", "大门": "搭配：“大门”是建筑部件，与“票”和“五十块”搭配不当。"}, "sentence_index": 6, "correct_answer": "大人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只小狗已经是大人了。", "explanation": "这里不能用〈大人〉指动物。“大人”只指人，指狗要说“成年的狗”。"}, {"text": "学校下午召开大人会。", "explanation": "这里应该用〈家长〉。“家长会”是固定说法，不能换成“大人会”。"}, {"text": "我弟弟才两岁，已经是大人了。", "explanation": "这里不能用〈大人〉。“大人”指已经长大的成年人，两岁的孩子还是小孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口站着一只大人。", "corrected_sentence": "门口站着一位大人。", "error_description": "错误：“大人”指人，量词应用“位”，“只”用于动物，应说“一位大人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些大人们们都很关心孩子。", "corrected_sentence": "这些大人们都很关心孩子。", "error_description": "错误：“大人们”已表示复数，“们”不能重复，应说“大人们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
