INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93142, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成年人；也尊称长辈。", "primary_collocate": null, "pronunciation": "dà ren", "ipa": "ta˥˩ ʐən", "syllable_count": 2, "sentences": [{"text": "家里的大人都出去工作了。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明很听大人的话。", "target_word": "大人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过马路时，要拉住大人的手。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大人们坐在院子里喝茶。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就知道要尊敬大人。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有事就告诉大人，别自己害怕。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子问大人为什么天是蓝的。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们先玩，大人还有事要谈。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大人说话的时候，小孩别插嘴。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大人们都说他很懂事。", "target_word": "大人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大人们", "label": "复数"}, {"form": "一位大人", "label": "量词"}], "register": "口语", "sense_fingerprint": "大人：家里的成年人、长辈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8d98bf-ca56-4497-b80d-a8800a5dfbfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大人", "is_correct": true, "explanation": "正确：大人（dà ren）指家里的成年人或长辈，是这个义项的本义。"}, {"text": "打人", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是殴打他人。"}, {"text": "达人", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是在某方面很有造诣的人。"}, {"text": "带人", "is_correct": false, "explanation": "dài 与 dà 韵母不同（ai 与 a），意思是带领他人。"}], "explanations": {"大人": "正确：大人（dà ren）指家里的成年人或长辈，是这个义项的本义。", "打人": "dǎ（第三声）与 dà（第四声）声调不同，意思是殴打他人。", "达人": "dá（第二声）与 dà（第四声）声调不同，意思是在某方面很有造诣的人。", "带人": "dài 与 dà 韵母不同（ai 与 a），意思是带领他人。"}, "sentence_index": null, "correct_answer": "大人"}, "level_3": {"options": [{"text": "大海", "is_correct": false, "explanation": "语义：“大海”指海洋，不能出去工作。"}, {"text": "大人", "is_correct": true, "explanation": "正确：“大人”指家里的成年人，可以出去工作。"}, {"text": "大树", "is_correct": false, "explanation": "语义：“大树”指植物，不能出去工作。"}, {"text": "大米", "is_correct": false, "explanation": "搭配：“大米”是食物，不能与“出去工作”搭配。"}], "explanations": {"大海": "语义：“大海”指海洋，不能出去工作。", "大人": "正确：“大人”指家里的成年人，可以出去工作。", "大树": "语义：“大树”指植物，不能出去工作。", "大米": "搭配：“大米”是食物，不能与“出去工作”搭配。"}, "sentence_index": 0, "correct_answer": "大人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个三岁的孩子已经是大人了。", "explanation": "这里不能用〈大人〉。“大人”指成年人或长辈，三岁的孩子还没有长大。"}, {"text": "院子里站着一只大人。", "explanation": "这里应该用〈位〉或〈个〉。“大人”指人，量词用“位”或“个”，“只”用于动物。"}, {"text": "小王，大人，你今天怎么样？", "explanation": "这里不能用〈大人〉称呼同辈朋友。“大人”只用于尊称长辈，对平辈应直接叫名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大学", "is_correct": false, "explanation": "语义：“大学”是学校，不能回答孩子的问题。"}, {"text": "大人", "is_correct": true, "explanation": "正确：“大人”指长辈或家里的成年人，可以回答孩子的问题。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：“大楼”是建筑，不能回答孩子的问题。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：“大门”是建筑部件，不能与“问……为什么”搭配。"}], "explanations": {"大学": "语义：“大学”是学校，不能回答孩子的问题。", "大人": "正确：“大人”指长辈或家里的成年人，可以回答孩子的问题。", "大楼": "语义：“大楼”是建筑，不能回答孩子的问题。", "大门": "搭配：“大门”是建筑部件，不能与“问……为什么”搭配。"}, "sentence_index": 6, "correct_answer": "大人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两位大人是我的同学，正在里面写作业。", "explanation": "这里不能用〈大人〉指同学。“大人”用作尊称时指长辈或官员，不能用来称呼同龄人；指同学要说“同学”。"}, {"text": "我家的小猫都大人了。", "explanation": "这里不能用〈大人〉指动物。“大人”只指人，指猫要说“长大的猫”。"}, {"text": "这家影院只放大人电影。", "explanation": "这里应该用〈成人〉。“大人”不能修饰“电影”这类分类词；说成人电影要用〈成人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里的大人们们都在聊天。", "corrected_sentence": "院子里的大人们都在聊天。", "error_description": "错误：“大人们”已表示复数，“们”不能重复，应说“大人们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路口走来几只大人。", "corrected_sentence": "路口走来几位大人。", "error_description": "错误：“大人”指人，量词应用“位”，“只”用于动物，应说“几位大人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
