INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93145, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93145, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好走是路平平的，走起来不累。", "primary_collocate": null, "pronunciation": "hǎo zǒu", "ipa": "xɑʊ̯˨˩ tsoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这条路很平，非常好走。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的山路不太好走。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新修的马路比老路好走多了。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路又平又干净，很好走。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪以后，路不好走，慢一点。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走大路吧，大路比小路好走。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的路平平的，特别好走。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段山路又陡又滑，一点也不好走。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换了一条更好走的路。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草多了，田里的小路不好走。", "target_word": "好走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不好走", "label": "否定"}, {"form": "更好走", "label": "比较"}], "register": "口语", "sense_fingerprint": "路面平坦，走起来省力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93145, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好走", "is_correct": true, "explanation": "好走：路面平坦，走起来省力，与“这条路很平”的语境相符。"}, {"text": "陡", "is_correct": false, "explanation": "语义：“陡”指坡度大，与“这条路很平”直接矛盾。"}, {"text": "险", "is_correct": false, "explanation": "语义：“险”指有危险，与“很平”的路况相矛盾。"}, {"text": "烂", "is_correct": false, "explanation": "搭配：“烂”多形容破损或质量差，不能与“很平”搭配来描述路面。"}], "explanations": {"好走": "好走：路面平坦，走起来省力，与“这条路很平”的语境相符。", "陡": "语义：“陡”指坡度大，与“这条路很平”直接矛盾。", "险": "语义：“险”指有危险，与“很平”的路况相矛盾。", "烂": "搭配：“烂”多形容破损或质量差，不能与“很平”搭配来描述路面。"}, "sentence_index": 0, "correct_answer": "好走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌很好走。", "explanation": "这里应该用〈好听〉。好走只形容道路平坦、走起来省力，不能用来评价歌曲。"}, {"text": "这把椅子坐起来很好走。", "explanation": "这里应该用〈舒服〉。好走描述道路通行是否省力，不用于描述椅子的坐感。"}, {"text": "这个蛋糕很好走。", "explanation": "这里应该用〈好吃〉。好走只形容道路，不能用来形容食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93145, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好走", "is_correct": true, "explanation": "好走：路面平坦，走起来省力，与“河边的路平平的”相符。"}, {"text": "崎岖", "is_correct": false, "explanation": "语域：“崎岖”偏书面，口语句中不自然，且与“平平的”矛盾。"}, {"text": "坑洼", "is_correct": false, "explanation": "语义：“坑洼”指路面凹凸不平，与“平平的”的描述相矛盾。"}, {"text": "坎坷", "is_correct": false, "explanation": "语义：“坎坷”指道路高低不平，与“平平的”的路况相反。"}], "explanations": {"好走": "好走：路面平坦，走起来省力，与“河边的路平平的”相符。", "崎岖": "语域：“崎岖”偏书面，口语句中不自然，且与“平平的”矛盾。", "坑洼": "语义：“坑洼”指路面凹凸不平，与“平平的”的描述相矛盾。", "坎坷": "语义：“坎坷”指道路高低不平，与“平平的”的路况相反。"}, "sentence_index": 6, "correct_answer": "好走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次面试很好走。", "explanation": "这里应该用〈顺利〉。好走只说道路通行是否省力，不能用来说事情进展。"}, {"text": "这道题很好走。", "explanation": "这里应该用〈容易〉。好走是描述道路的，不能用来描述题目的难易。"}, {"text": "这份工作很好走。", "explanation": "这里应该用〈轻松〉。好走用于道路，不能用来形容工作的轻松程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条土路下过雨以后就没好走了。", "corrected_sentence": "这条土路下过雨以后就不好走了。", "error_description": "“好走”是形容词，表示否定要用“不”，不能用“没”。正确说法是“不好走了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条土路比那条山路最好走。", "corrected_sentence": "这条土路比那条山路更好走。", "error_description": "“比”字句中表示程度加深要用“更”，不能用“最”。正确说法是“比那条山路更好走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
