INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93147, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "市场调查是问问大家喜欢买什么东西。", "primary_collocate": null, "pronunciation": "shì chǎng diào chá", "ipa": "ʂɻ̩˥˩ tʂʰɑŋ˨˩˦ tjɑʊ˥˩ tʂʰa˧˥", "syllable_count": 4, "sentences": [{"text": "公司做市场调查，问大家喜欢买什么。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场调查的结果是年轻人爱喝茶。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店先做市场调查，再开门。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天在街上做市场调查。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场调查要问很多人。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工作是做市场调查。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板看了市场调查，决定卖新鞋。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次市场调查问了一百个人。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加市场调查的人，可以得到一杯茶。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们去商店做市场调查。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市場調查", "label": "繁体"}, {"form": "次", "label": "量词"}, {"form": "市场调查报告", "label": "复合"}], "register": "中性", "sense_fingerprint": "问大家喜欢买什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93147, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市场调查", "is_correct": true, "explanation": "正确。“做市场调查”指通过问卷等方式了解大家喜欢买什么。"}, {"text": "手术", "is_correct": false, "explanation": "语义：公司不做手术，与“问大家喜欢买什么”的商业活动不相符。"}, {"text": "口号", "is_correct": false, "explanation": "搭配：“做”不与“口号”搭配，应说“喊口号”或“提口号”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的任务，公司不会做作业，句意不通。"}], "explanations": {"市场调查": "正确。“做市场调查”指通过问卷等方式了解大家喜欢买什么。", "手术": "语义：公司不做手术，与“问大家喜欢买什么”的商业活动不相符。", "口号": "搭配：“做”不与“口号”搭配，应说“喊口号”或“提口号”。", "作业": "语义：作业是学生的任务，公司不会做作业，句意不通。"}, "sentence_index": 0, "correct_answer": "市场调查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给他做了一次市场调查。", "explanation": "这里应该用〈体检〉。市场调查用来了解市场和顾客，不用来检查病人的身体。"}, {"text": "市场调查每天早上六点开门。", "explanation": "这里把“市场调查”理解成了“市场”（买卖东西的场所）。市场调查是一种活动，不能开门。"}, {"text": "妈妈昨天吃了市场调查。", "explanation": "这里把“市场调查”理解成了可以吃的食品。市场调查是一种了解市场和顾客需求的活动，不是食物，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93147, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市场调查", "is_correct": true, "explanation": "正确。“看了市场调查”指看了调查结果，然后决定进货。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是医生记录病情的材料，老板看了病历与“决定卖新鞋”没有关系。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“看”不与“歌声”搭配，应说“听歌声”。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱讲的是做菜的方法，看了食谱推不出“决定卖新鞋”。"}], "explanations": {"市场调查": "正确。“看了市场调查”指看了调查结果，然后决定进货。", "病历": "语义：病历是医生记录病情的材料，老板看了病历与“决定卖新鞋”没有关系。", "歌声": "搭配：“看”不与“歌声”搭配，应说“听歌声”。", "食谱": "语义：食谱讲的是做菜的方法，看了食谱推不出“决定卖新鞋”。"}, "sentence_index": 6, "correct_answer": "市场调查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察去商店做市场调查，寻找偷东西的人。", "explanation": "这里“调查”用的是查案的意思。市场调查是了解顾客需要的活动，查找罪犯应说“侦查”。"}, {"text": "学生们去工厂做市场调查，了解机器的工作原理。", "explanation": "这里应该用〈参观〉。市场调查了解的是市场和顾客的需求，了解机器的工作原理应说“参观”。"}, {"text": "学生们去商店做市场调查，把它喝了。", "explanation": "这里把「市场调查」理解成了可以喝的东西。市场调查是一种活动，不是饮料，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们下周要在商场门口做一只市场调查。", "corrected_sentence": "他们下周要在商场门口做一次市场调查。", "error_description": "量词错误：“市场调查”是一种活动，应该用量词“次”，不能用“只”（“只”多用于动物等）。正确说法是“做一次市场调查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们去超市一次市场调查。", "corrected_sentence": "同学们去超市做一次市场调查。", "error_description": "漏掉动词：“市场调查”前面要有动词“做”，应说“做一次市场调查”，不能直接在“一次”后接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
