INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "有目的地收集并分析市场信息、了解顾客需求的活动。", "primary_collocate": null, "pronunciation": "shì chǎng diào chá", "ipa": "ʂɻ̩˥˩ tʂʰɑŋ˨˩˦ tjɑʊ˥˩ tʂʰa˧˥", "syllable_count": 4, "sentences": [{"text": "公司请专家做了一次市场调查。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场调查可以帮公司了解顾客的需要。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做新产品以前，要先做市场调查。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次市场调查用了三个月的时间。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场调查的数据，经理已经分析过了。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们根据市场调查决定产品的价格。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的市场调查要收集很多信息。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份市场调查说明，顾客想要便宜的手机。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场调查让我们知道谁会买这个产品。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做市场调查的人要会分析数字。", "target_word": "市场调查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市場調查", "label": "繁体"}, {"form": "次", "label": "量词"}, {"form": "市场调查报告", "label": "复合"}], "register": "中性", "sense_fingerprint": "收集分析市场信息、了解顾客需求的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '599121f6-7aa3-4196-b677-939c72d4cb34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市场调查", "is_correct": true, "explanation": "正确。“做了一次市场调查”指进行了一次收集市场信息的活动。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：「做」不与「电话」搭配，应说「打电话」。"}, {"text": "手术", "is_correct": false, "explanation": "语义：请专家做手术与句子中的商业背景不符，句意不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的任务，公司请专家做作业不合逻辑。"}], "explanations": {"市场调查": "正确。“做了一次市场调查”指进行了一次收集市场信息的活动。", "电话": "搭配：「做」不与「电话」搭配，应说「打电话」。", "手术": "语义：请专家做手术与句子中的商业背景不符，句意不通。", "作业": "语义：作业是学生的任务，公司请专家做作业不合逻辑。"}, "sentence_index": 0, "correct_answer": "市场调查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察这次的市场调查用了三个月，终于找到了凶手。", "explanation": "这里“市场调查”用成了“案件侦查”的意思。市场调查是了解市场和顾客需求的活动，查找凶手应说“侦查”。"}, {"text": "这次市场调查每天早上六点开门。", "explanation": "这里把“市场调查”理解成了“市场”（买卖东西的场所）。市场调查是活动，不能开门。"}, {"text": "这次市场调查很好吃，大家都买了。", "explanation": "这里把“市场调查”理解成了食品。市场调查是收集市场信息的活动，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市场调查", "is_correct": true, "explanation": "正确。“好的市场调查”指做得好的、收集信息的调查活动，它需要收集很多信息。"}, {"text": "蛋糕", "is_correct": false, "explanation": "配价：“收集信息”需要能够收集的人或机构作主语，蛋糕不能作为施事。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不需要收集信息，“好的歌曲要收集很多信息”句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不需要收集很多信息，与句子的意思不相符。"}], "explanations": {"市场调查": "正确。“好的市场调查”指做得好的、收集信息的调查活动，它需要收集很多信息。", "蛋糕": "配价：“收集信息”需要能够收集的人或机构作主语，蛋糕不能作为施事。", "歌曲": "语义：歌曲不需要收集信息，“好的歌曲要收集很多信息”句意不通。", "天空": "语义：天空不需要收集很多信息，与句子的意思不相符。"}, "sentence_index": 6, "correct_answer": "市场调查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院的护士每天给病人做市场调查。", "explanation": "这里应该用〈体检〉。市场调查针对市场和顾客，不用于给病人做身体检查。"}, {"text": "我们公司请工程师去车间做市场调查，给汽车换一个发动机。", "explanation": "这里应该用〈检修〉。市场调查了解的是市场和顾客需求，不用于给汽车检修或更换发动机。"}, {"text": "我们把市场调查煮熟了，端给了邻居。", "explanation": "这里把「市场调查」理解成了食材。市场调查是活动或报告，不能煮，也不能端给别人吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司去年做了一张市场调查。", "corrected_sentence": "我们公司去年做了一次市场调查。", "error_description": "量词错误：“市场调查”应搭配量词“次”，不能用“张”（“张”多用于纸张、桌子等）。正确说法是“做了一次市场调查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们每个月都一次市场调查。", "corrected_sentence": "同学们每个月都做一次市场调查。", "error_description": "漏掉动词：“市场调查”前要有动词“做”，应说“做一次市场调查”，不能直接在“一次”后接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90254b30-e4d2-4263-b5e2-e18345dc5590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
