INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93149, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "如一是从头到尾都一样，没有变。", "primary_collocate": null, "pronunciation": "rú yī", "ipa": "ɻu˧˥ i˥", "syllable_count": 2, "sentences": [{"text": "他一年到头，学习的热情始终如一。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脾气多年来始终如一，从没变过。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的服务质量始终如一，客户都很放心。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友对我的关心始终如一，我很感动。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早起跑步，坚持得始终如一。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管天气好坏，他的笑容始终如一。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板对新老客人始终如一。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的友谊多年来始终如一。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩始终如一，不好也不坏。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对自己的要求始终如一，从不放松。", "target_word": "如一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "如一：从头到尾都一样，没有变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3db2a8-898c-4672-8b0b-0fbffde2e471') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如一", "is_correct": true, "explanation": "「如一」指从头到尾一样，与“一年到头”呼应，符合句意。"}, {"text": "反复", "is_correct": false, "explanation": "搭配：「始终」修饰的词要表示稳定，“始终反复”不成立。"}, {"text": "时好时坏", "is_correct": false, "explanation": "语义：“时好时坏”表示变化，与“始终”矛盾。"}, {"text": "朝令夕改", "is_correct": false, "explanation": "语义：「朝令夕改」指常常改变，与“始终”的含义相反。"}], "explanations": {"如一": "「如一」指从头到尾一样，与“一年到头”呼应，符合句意。", "反复": "搭配：「始终」修饰的词要表示稳定，“始终反复”不成立。", "时好时坏": "语义：“时好时坏”表示变化，与“始终”矛盾。", "朝令夕改": "语义：「朝令夕改」指常常改变，与“始终”的含义相反。"}, "sentence_index": 0, "correct_answer": "如一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩始终如一，去年却提高了二十分。", "explanation": "这里说的是成绩有了提高，但如一表示始终不变，不指变化。"}, {"text": "我们的关系始终如一，最近却变得很冷淡。", "explanation": "这里说的是关系发生了改变，但如一表示始终不变，不指改变的过程。"}, {"text": "他跑步的速度始终如一，一个月后就快了很多。", "explanation": "这里说的是速度变快了，但如一表示始终不变，不指变化的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如一", "is_correct": true, "explanation": "「如一」指始终一样，与“始终”搭配，符合句意。"}, {"text": "时冷时热", "is_correct": false, "explanation": "语义：“时冷时热”表示变化，与“始终”矛盾。"}, {"text": "朝三暮四", "is_correct": false, "explanation": "语义：「朝三暮四」指反复无常，与“始终”的含义相反。"}, {"text": "反复无常", "is_correct": false, "explanation": "搭配：「始终」不修饰表示多变的词，“始终反复无常”不通。"}], "explanations": {"如一": "「如一」指始终一样，与“始终”搭配，符合句意。", "时冷时热": "语义：“时冷时热”表示变化，与“始终”矛盾。", "朝三暮四": "语义：「朝三暮四」指反复无常，与“始终”的含义相反。", "反复无常": "搭配：「始终」不修饰表示多变的词，“始终反复无常”不通。"}, "sentence_index": 6, "correct_answer": "如一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的看法始终如一，上个月却突然改了主意。", "explanation": "这里说的是看法有了改变，但如一表示始终不变，不指改变的过程。"}, {"text": "她如一地要求自己，从不放松。", "explanation": "这里应该用〈始终〉。如一不单独修饰动作，应说“始终如一地”。"}, {"text": "我的身高始终如一，每年都长高了好几厘米。", "explanation": "这里说的是身高在增长，但如一表示始终不变，不指变化的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他始终如一的坚持跑步。", "corrected_sentence": "他始终如一地坚持跑步。", "error_description": "错误：「如一」修饰动词“坚持”时要用「地」，不能用「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对学习始终如一的，从不放松。", "corrected_sentence": "她对学习始终如一，从不放松。", "error_description": "错误：「始终如一」作谓语时不能带「的」，多出的「的」应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
