INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93151, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "师父是教你本事的人。", "primary_collocate": null, "pronunciation": "shī fu", "ipa": "ʂɻ̩˥ fu", "syllable_count": 2, "sentences": [{"text": "我的师父教了我十年。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师父，这个动作我还是学不会。", "target_word": "师父", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他跟着师父学做面包。", "target_word": "师父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父每天下班后，都会再教我一个新本事。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师父笑着对我说：“慢慢来。”", "target_word": "师父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请师父看看我做的菜。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很感谢自己的师父。", "target_word": "师父", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "师父把做鞋的方法都教给了他。", "target_word": "师父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我去看望了师父。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的师父教木工教了四十年。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "师父们", "label": "复数"}, {"form": "師父", "label": "繁体"}], "register": "中性", "sense_fingerprint": "师父：教你手艺或本事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "师父", "is_correct": true, "explanation": "“师父”指传授本事的人，可以作“教”的主语，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会教人，“教”的主语应为人。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“教了我十年”的主语须是人，“天气”不能与之搭配。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子不会教人，“教了我十年”的主语须是人。"}], "explanations": {"师父": "“师父”指传授本事的人，可以作“教”的主语，句意通顺。", "石头": "语义：石头不会教人，“教”的主语应为人。", "天气": "搭配：“教了我十年”的主语须是人，“天气”不能与之搭配。", "盒子": "语义：盒子不会教人，“教了我十年”的主语须是人。"}, "sentence_index": 0, "correct_answer": "师父"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寺里的师父请我们吃了一顿素斋。", "explanation": "这里应该用〈僧人〉。“师父”在这一义项里指僧人，与“传授本事的人”不是同一个意思，此句不用于本义。"}, {"text": "这位师父是我的同桌。", "explanation": "这里应该用〈同学〉。“师父”指传授本事的人，不用于称呼同桌。"}, {"text": "我的师父和我一起学数学。", "explanation": "这里应该用〈同学〉。“师父”是传授本事的人，不会和你一起跟着别人学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "师父", "is_correct": true, "explanation": "“师父”是传授本事的人，可以作“感谢”的对象，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能成为感谢的对象，这个句子说不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能被感谢，“感谢”的对象应为人。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：“感谢”的对象须是人，“夏天”不能与“感谢”搭配。"}], "explanations": {"师父": "“师父”是传授本事的人，可以作“感谢”的对象，句意通顺。", "桌子": "语义：桌子不能成为感谢的对象，这个句子说不通。", "电脑": "语义：电脑不能被感谢，“感谢”的对象应为人。", "夏天": "搭配：“感谢”的对象须是人，“夏天”不能与“感谢”搭配。"}, "sentence_index": 6, "correct_answer": "师父"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的师父跟着我学做木工，已经学了四年。", "explanation": "这里应该用〈徒弟〉。“师父”是教人本事的人，不会跟着别人学做木工。"}, {"text": "我的大学师父是我的室友。", "explanation": "这里应该用〈室友〉。“师父”指传授本事的人，不用于称呼同住的同学。"}, {"text": "我和他是师父，常一起切磋手艺。", "explanation": "这里应该用〈同行〉。“师父”是师徒关系中教人本事的一方，同辈的手艺人之间不称“师父”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我请了一只师父来教我做饭。", "corrected_sentence": "我请了一位师父来教我做饭。", "error_description": "“师父”指人，量词应用“位”，不能用“只”；应说“一位师父”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我跟着一只师父学做饭。", "corrected_sentence": "我跟着一位师父学做饭。", "error_description": "“师父”指人，量词应用“位”，不能用“只”；应说“一位师父”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
