INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "传授技艺的人；对僧道或手艺人的尊称。", "primary_collocate": null, "pronunciation": "shī fu", "ipa": "ʂɻ̩˥ fu", "syllable_count": 2, "sentences": [{"text": "师父，请问怎么去山上的庙？", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位师父在寺里已经住了很多年。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修鞋的师父说，鞋明天就能修好。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师父，我的手机屏幕坏了，能修吗？", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师父坐在树下，静静地念着经。", "target_word": "师父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位做木工的师父，手艺特别好。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "庙里的师父请我们喝了一杯茶。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人想拜这位师父为师。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师父，您的手艺真好，我想跟您学。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的师父每天早上都会敲钟。", "target_word": "师父", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "师父们", "label": "复数"}, {"form": "師父", "label": "繁体"}], "register": "中性", "sense_fingerprint": "师父：对僧道或手艺人的尊称，也指传授技艺的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59d0d08a-d19a-4f5d-af3f-425b4714631c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "师父", "is_correct": true, "explanation": "“师父”是对僧道的尊称，可以用作称呼，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能被称呼，也不能回答问路的问题，这个句子说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以问路的对象，称呼它不成立。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：问路时的称呼须是人，“夏天”不能作称呼。"}], "explanations": {"师父": "“师父”是对僧道的尊称，可以用作称呼，句意通顺。", "桌子": "语义：桌子不能被称呼，也不能回答问路的问题，这个句子说不通。", "石头": "语义：石头不是可以问路的对象，称呼它不成立。", "夏天": "搭配：问路时的称呼须是人，“夏天”不能作称呼。"}, "sentence_index": 0, "correct_answer": "师父"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位师父是我的小学老师。", "explanation": "这里应该用〈老师〉。“师父”指传授手艺的人、僧道或手艺人的尊称，学校里教书的人一般不称“师父”。"}, {"text": "那位师父是我的弟弟。", "explanation": "这里应该用〈弟弟〉。“师父”是对僧道或手艺人的尊称，不用于称呼弟弟。"}, {"text": "师父，我们一起去打球吧。", "explanation": "这里应该用〈同学〉。“师父”是对僧道或手艺人的尊称，不用来称呼同龄朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "师父", "is_correct": true, "explanation": "“师父”是对僧人的尊称，“庙里的师父”作主语，可以请人喝茶，句意通顺。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会请人喝茶，这个句子说不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能请人喝茶，“请……喝茶”的主语须是人。"}, {"text": "冬天", "is_correct": false, "explanation": "搭配：“请……喝茶”的主语须是人，“冬天”不能与之搭配。"}], "explanations": {"师父": "“师父”是对僧人的尊称，“庙里的师父”作主语，可以请人喝茶，句意通顺。", "窗户": "语义：窗户不会请人喝茶，这个句子说不通。", "电脑": "语义：电脑不能请人喝茶，“请……喝茶”的主语须是人。", "冬天": "搭配：“请……喝茶”的主语须是人，“冬天”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "师父"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的师父很多。", "explanation": "这里应该用〈老师〉。“师父”指僧道或手艺人，学校里教书的人不称“师父”。"}, {"text": "这本书的师父写得很好。", "explanation": "这里应该用〈作者〉。“师父”指传授技艺的人或手艺人、僧道的尊称，不指书的作者。"}, {"text": "这位师父是我的同桌。", "explanation": "这里应该用〈同学〉。“师父”是对僧道或手艺人的尊称，不用于称呼同桌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请问那只师父，山上的庙怎么走？", "corrected_sentence": "请问那位师父，山上的庙怎么走？", "error_description": "“师父”指人，量词应用“位”，不能用“只”；应说“那位师父”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庙里的那只师父请我们喝了一杯茶。", "corrected_sentence": "庙里的那位师父请我们喝了一杯茶。", "error_description": "“师父”指人，量词应用“位”，不能用“只”；应说“那位师父”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168687ab-a016-4943-b2b4-152f49b56804') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93153, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93153, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93153, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "害是让别人受到伤害，变得不好。", "primary_collocate": null, "pronunciation": "hài", "ipa": "xaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "你这样做会害了他。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人想害我们，我们要小心。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不是故意要害你的。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别为了赚钱去害别人。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在饭里放药，想害老师。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她担心自己会害了孩子的前途。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说假话，不只骗人，还会害人。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人曾经害过很多老人。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟不但害自己，也害家人。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把朋友的钱都花光了，真是害了朋友。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "害了", "label": "体标"}, {"form": "害过", "label": "体标"}], "register": "中性", "sense_fingerprint": "存心或无意地让别人受到伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4de93c19-9eac-449b-96e7-31ed056a2812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93153, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "害", "is_correct": true, "explanation": "正确：hài，即本条目，意思是让别人受到伤害。"}, {"text": "海", "is_correct": false, "explanation": "声调不同：hǎi（第三声）与 hài（第四声）声调不同，意思是海。"}, {"text": "孩", "is_correct": false, "explanation": "声调不同：hái（第二声）与 hài（第四声）声调不同，意思是孩子。"}, {"text": "爱", "is_correct": false, "explanation": "声母不同：ài 没有 h，与 hài 只差一个声母，意思是爱。"}], "explanations": {"害": "正确：hài，即本条目，意思是让别人受到伤害。", "海": "声调不同：hǎi（第三声）与 hài（第四声）声调不同，意思是海。", "孩": "声调不同：hái（第二声）与 hài（第四声）声调不同，意思是孩子。", "爱": "声母不同：ài 没有 h，与 hài 只差一个声母，意思是爱。"}, "sentence_index": null, "correct_answer": "害"}, "level_3": {"options": [{"text": "害", "is_correct": true, "explanation": "正确：“会害了他”表示这样做会让他受到伤害。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“会吃了他”说不通。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“这样做会”后面要接不好的后果，“感谢了他”不能这样搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬人，“这样做会咬了他”不合理。"}], "explanations": {"害": "正确：“会害了他”表示这样做会让他受到伤害。", "吃": "语义：“吃”指进食，“会吃了他”说不通。", "感谢": "搭配：“这样做会”后面要接不好的后果，“感谢了他”不能这样搭配。", "咬": "语义：“咬”指用牙齿咬人，“这样做会咬了他”不合理。"}, "sentence_index": 0, "correct_answer": "害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他悄悄害了老师的钱，然后拿走了。", "explanation": "这里应该用〈偷〉。害表示使人受到伤害，不表示拿走别人的东西。"}, {"text": "他一直害我们，每次都替我们拿行李。", "explanation": "这里应该用〈帮助〉。害表示使人受伤害，与替我们拿行李的意思相反。"}, {"text": "他在比赛中害了一个进球，大家都很高兴。", "explanation": "这里应该用〈踢进〉。害表示使人受损害，不能用来表示进球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93153, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "害", "is_correct": true, "explanation": "正确：hài，即本条目，意思是让别人受到伤害。"}, {"text": "盖", "is_correct": false, "explanation": "声母不同：gài（g）与 hài（h）声母不同，意思是盖。"}, {"text": "在", "is_correct": false, "explanation": "声母不同：zài（z）与 hài（h）声母不同，意思是在。"}, {"text": "太", "is_correct": false, "explanation": "声母不同：tài（t）与 hài（h）声母不同，意思是太。"}], "explanations": {"害": "正确：hài，即本条目，意思是让别人受到伤害。", "盖": "声母不同：gài（g）与 hài（h）声母不同，意思是盖。", "在": "声母不同：zài（z）与 hài（h）声母不同，意思是在。", "太": "声母不同：tài（t）与 hài（h）声母不同，意思是太。"}, "sentence_index": null, "correct_answer": "害"}, "level_3": {"options": [{"text": "害", "is_correct": true, "explanation": "正确：“还会害人”表示说假话还会伤害别人。"}, {"text": "嫁", "is_correct": false, "explanation": "语义：说假话和“嫁人”没有关系，句意不通。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔人”不是常见搭配，“还会扔人”说不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗人”的意思不合理，与“说假话”也无关。"}], "explanations": {"害": "正确：“还会害人”表示说假话还会伤害别人。", "嫁": "语义：说假话和“嫁人”没有关系，句意不通。", "扔": "搭配：“扔人”不是常见搭配，“还会扔人”说不通。", "洗": "语义：“洗人”的意思不合理，与“说假话”也无关。"}, "sentence_index": 6, "correct_answer": "害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总是害朋友，每天都去看他。", "explanation": "这里应该用〈照顾〉。害表示伤害别人，与“每天都去看他”的关心矛盾。"}, {"text": "他害得同学们都很开心。", "explanation": "这里应该用〈让〉。〈害得〉后面只接不好的结果，不能接“很开心”。"}, {"text": "他这次考试考得很好，全靠老师害他。", "explanation": "这里应该用〈帮〉。害表示使人受伤害，这里说老师帮了他，不是伤害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的谎话被害了一家人。", "corrected_sentence": "他的谎话害了一家人。", "error_description": "错误：多用了“被”。“谎话”是致害的原因，不是受害者，“被”字句的主语应是受害方。去掉“被”，说“他的谎话害了一家人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个商人曾经害很多农民。", "corrected_sentence": "这个商人曾经害过很多农民。", "error_description": "错误：漏了体标“过”。“曾经”表示有过的经历，动词后要加“过”，应说“害过很多农民”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
