INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93154, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使受损害；使遭遇不幸。", "primary_collocate": null, "pronunciation": "hài", "ipa": "xaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "一场大雨害得我们全身都湿了。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "懒惰害了他一辈子。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌博害了不少家庭。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大病害我丢了工作。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的坏习惯害了全家人。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都是我马虎，害你白跑了一趟。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个错误的决定害了公司。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不好的天气害我们错过了飞机。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝酒开车，差点儿害了自己。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水害了河里的很多鱼。", "target_word": "害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "害了", "label": "体标"}, {"form": "害过", "label": "体标"}], "register": "中性", "sense_fingerprint": "某人或某事使人受损失、遭遇不幸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4de93c19-9eac-449b-96e7-31ed056a2812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93154, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "害", "is_correct": true, "explanation": "正确：hài，即本条目，意思是使人受损害、遭遇不幸。"}, {"text": "海", "is_correct": false, "explanation": "声调不同：hǎi（第三声）与 hài（第四声）声调不同，意思是海。"}, {"text": "孩", "is_correct": false, "explanation": "声调不同：hái（第二声）与 hài（第四声）声调不同，意思是孩子。"}, {"text": "太", "is_correct": false, "explanation": "声母不同：tài（t）与 hài（h）声母不同，意思是太。"}], "explanations": {"害": "正确：hài，即本条目，意思是使人受损害、遭遇不幸。", "海": "声调不同：hǎi（第三声）与 hài（第四声）声调不同，意思是海。", "孩": "声调不同：hái（第二声）与 hài（第四声）声调不同，意思是孩子。", "太": "声母不同：tài（t）与 hài（h）声母不同，意思是太。"}, "sentence_index": null, "correct_answer": "害"}, "level_3": {"options": [{"text": "害", "is_correct": true, "explanation": "正确：“害得我们全身都湿了”表示大雨造成的不好结果。"}, {"text": "劝", "is_correct": false, "explanation": "语义：“劝得我们全身都湿了”没有因果关系，句意不通。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：“打扮得”后面接外貌或服饰，不能接“全身都湿了”。"}, {"text": "猜", "is_correct": false, "explanation": "语义：“猜得”说的是猜测的结果，不能使人全身湿透。"}], "explanations": {"害": "正确：“害得我们全身都湿了”表示大雨造成的不好结果。", "劝": "语义：“劝得我们全身都湿了”没有因果关系，句意不通。", "打扮": "搭配：“打扮得”后面接外貌或服饰，不能接“全身都湿了”。", "猜": "语义：“猜得”说的是猜测的结果，不能使人全身湿透。"}, "sentence_index": 0, "correct_answer": "害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔生意害我们赚了很多钱。", "explanation": "这里应该用〈让〉。害表示使人遭受损害，与赚钱的意思相反。"}, {"text": "我们很害他的遭遇，都觉得很可惜。", "explanation": "这里应该用〈同情〉。害表示使人遭受损害，不能表示对别人遭遇的态度。"}, {"text": "这次假期多亏了他，害我们玩得很开心。", "explanation": "这里应该用〈让〉。害表示使人遭受损害，与玩得很开心的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93154, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "害", "is_correct": true, "explanation": "正确：hài，即本条目，意思是使人受损害、遭遇不幸。"}, {"text": "盖", "is_correct": false, "explanation": "声母不同：gài（g）与 hài（h）声母不同，意思是盖。"}, {"text": "在", "is_correct": false, "explanation": "声母不同：zài（z）与 hài（h）声母不同，意思是在。"}, {"text": "爱", "is_correct": false, "explanation": "声母不同：ài 没有 h，与 hài 只差一个声母，意思是爱。"}], "explanations": {"害": "正确：hài，即本条目，意思是使人受损害、遭遇不幸。", "盖": "声母不同：gài（g）与 hài（h）声母不同，意思是盖。", "在": "声母不同：zài（z）与 hài（h）声母不同，意思是在。", "爱": "声母不同：ài 没有 h，与 hài 只差一个声母，意思是爱。"}, "sentence_index": null, "correct_answer": "害"}, "level_3": {"options": [{"text": "害", "is_correct": true, "explanation": "正确：“那个错误的决定害了公司”表示决定使公司受损失。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”不能对公司造成后果，“笑了公司”说不通。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔了公司”不是常见搭配，不能作这里的谓语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能使公司受损失，句意不通。"}], "explanations": {"害": "正确：“那个错误的决定害了公司”表示决定使公司受损失。", "笑": "语义：“笑”不能对公司造成后果，“笑了公司”说不通。", "扔": "搭配：“扔了公司”不是常见搭配，不能作这里的谓语。", "唱": "语义：“唱”不能使公司受损失，句意不通。"}, "sentence_index": 6, "correct_answer": "害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位医生很会害病人，每次都把病治得很好。", "explanation": "这里应该用〈治〉。害表示使人遭受损害，与“把病治得很好”的意思相反。"}, {"text": "他害得同学们很开心。", "explanation": "这里应该用〈让〉。〈害得〉后面只能接不好的结果。"}, {"text": "他常常害大家吃饭，我们都很感谢他。", "explanation": "这里应该用〈请〉。害表示使人受伤害，不能表示请大家吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次意外他害摔断了腿。", "corrected_sentence": "这次意外害他摔断了腿。", "error_description": "错误：“害”要带受害人，应说“害他”，不能说“他害”。正确句为“这次意外害他摔断了腿。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场大火害地很多人无家可归。", "corrected_sentence": "那场大火害得很多人无家可归。", "error_description": "错误：表示“使……”的固定结构是“害得”，不能写成“害地”；“地”是修饰动词的结构助词，不能接在“害”后引出结果。应说“害得很多人无家可归”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
