INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93155, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "平方米是量地方有多大的单位。", "primary_collocate": null, "pronunciation": "píng fāng mǐ", "ipa": "pʰiŋ˧˥ fɑŋ˥ mi˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个房间有二十平方米。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的客厅大约三十平方米。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间教室一共有六十平方米。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一套八十平方米的房子。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地不大，只有一百平方米。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有一个五百平方米的花园。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的卧室十五平方米，很小。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店有四十平方米，东西很多。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，你们的办公室有多少平方米？", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厨房只有六平方米，太小了。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平米", "label": "简称"}], "register": "中性", "sense_fingerprint": "量房间、土地大小的单位，常放在数字后面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93155, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公斤", "is_correct": false, "explanation": "搭配：公斤计量重量，不能用来说房间有多少公斤。"}, {"text": "平方米", "is_correct": true, "explanation": "平方米是面积单位，与房间的大小相合，是正确答案。"}, {"text": "升", "is_correct": false, "explanation": "语义：升是容量单位，不能表示房间的大小。"}, {"text": "公里", "is_correct": false, "explanation": "语义：公里计量长度，二十公里的房间不合常理。"}], "explanations": {"公斤": "搭配：公斤计量重量，不能用来说房间有多少公斤。", "平方米": "平方米是面积单位，与房间的大小相合，是正确答案。", "升": "语义：升是容量单位，不能表示房间的大小。", "公里": "语义：公里计量长度，二十公里的房间不合常理。"}, "sentence_index": 0, "correct_answer": "平方米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个水箱能装五十平方米的水。", "explanation": "这里应该用〈立方米〉。平方米是面积单位，表示水的体积要用立方米。"}, {"text": "这条路有五平方米宽。", "explanation": "这里应该用〈米〉。平方米是面积单位，说路的宽度要用长度单位“米”，不能用平方米。"}, {"text": "这箱苹果有十平方米。", "explanation": "这里应该用〈公斤〉。平方米计量面积，称重量要用公斤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亩", "is_correct": false, "explanation": "搭配：亩多用于计量土地，不说卧室有多少亩。"}, {"text": "平方米", "is_correct": true, "explanation": "平方米计量面积，与“很小”的卧室相合，是正确答案。"}, {"text": "公顷", "is_correct": false, "explanation": "语义：公顷是很大的面积，与“很小”的卧室相矛盾。"}, {"text": "吨", "is_correct": false, "explanation": "搭配：吨计量重量，不能用来说卧室的大小。"}], "explanations": {"亩": "搭配：亩多用于计量土地，不说卧室有多少亩。", "平方米": "平方米计量面积，与“很小”的卧室相合，是正确答案。", "公顷": "语义：公顷是很大的面积，与“很小”的卧室相矛盾。", "吨": "搭配：吨计量重量，不能用来说卧室的大小。"}, "sentence_index": 6, "correct_answer": "平方米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我等了三平方米。", "explanation": "这里应该用〈分钟〉。平方米是面积单位，不能用来计量时间。"}, {"text": "他今年二十平方米了。", "explanation": "这里应该用〈岁〉。平方米不能用来计算年龄。"}, {"text": "这瓶水花了五平方米。", "explanation": "这里应该用〈块〉。平方米计量面积，不能用来计算钱数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套公寓有八十张平方米。", "corrected_sentence": "这套公寓有八十平方米。", "error_description": "错误：数字和“平方米”之间多加了量词“张”。正确：“平方米”本身就是单位，数字后直接接“平方米”，应说“八十平方米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子有三十的平方米。", "corrected_sentence": "这间屋子有三十平方米。", "error_description": "错误：“三十”与“平方米”之间多加了“的”。正确：“平方米”前的数字后直接接“平方米”，作谓语时不加“的”，应说“有三十平方米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
