INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93156, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "面积单位，边长为一米的正方形的面积。", "primary_collocate": null, "pronunciation": "píng fāng mǐ", "ipa": "pʰiŋ˧˥ fɑŋ˥ mi˨˩˦", "syllable_count": 3, "sentences": [{"text": "一平方米是边长为一米的正方形的面积。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面积的单位有平方米和平方公里。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布的面积是两平方米。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一平方米的地砖要五十块钱。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们给墙刷漆，一共刷了十平方米。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的面积不到一平方米。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游泳池有两百平方米。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的面积是用平方米来算的。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一平方米能放四张小桌子。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他租了一间二十五平方米的小房子。", "target_word": "平方米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平米", "label": "简称"}], "register": "中性", "sense_fingerprint": "面积单位，一米乘一米的正方形大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e91c0d-146f-4be2-97f8-2129581fbe82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "米", "is_correct": false, "explanation": "语义：米是长度单位，“一米是正方形的面积”说不通。"}, {"text": "平方米", "is_correct": true, "explanation": "平方米是面积单位，与“正方形的面积”相合，是正确答案。"}, {"text": "公顷", "is_correct": false, "explanation": "语义：公顷是很大的面积，与“边长为一米”的正方形相矛盾。"}, {"text": "立方米", "is_correct": false, "explanation": "搭配：立方米计量体积，不能用来说正方形的面积。"}], "explanations": {"米": "语义：米是长度单位，“一米是正方形的面积”说不通。", "平方米": "平方米是面积单位，与“正方形的面积”相合，是正确答案。", "公顷": "语义：公顷是很大的面积，与“边长为一米”的正方形相矛盾。", "立方米": "搭配：立方米计量体积，不能用来说正方形的面积。"}, "sentence_index": 0, "correct_answer": "平方米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子能装一平方米的东西。", "explanation": "这里应该用〈立方米〉。平方米是面积单位，表示容积要用立方米。"}, {"text": "这条路有五平方米长。", "explanation": "这里应该用〈公里〉。平方米计量面积，说路的长度要用公里。"}, {"text": "这瓶牛奶有一平方米。", "explanation": "这里应该用〈升〉。平方米是面积单位，不能用来计量液体的容量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公里", "is_correct": false, "explanation": "语义：公里计量长度，游泳池不可能有两百公里。"}, {"text": "斤", "is_correct": false, "explanation": "搭配：斤计量重量，不能用来说游泳池的大小。"}, {"text": "平方米", "is_correct": true, "explanation": "平方米计量面积，与游泳池的大小相合，是正确答案。"}, {"text": "亩", "is_correct": false, "explanation": "搭配：亩多用于计量土地，游泳池不说有多少亩。"}], "explanations": {"公里": "语义：公里计量长度，游泳池不可能有两百公里。", "斤": "搭配：斤计量重量，不能用来说游泳池的大小。", "平方米": "平方米计量面积，与游泳池的大小相合，是正确答案。", "亩": "搭配：亩多用于计量土地，游泳池不说有多少亩。"}, "sentence_index": 6, "correct_answer": "平方米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了三平方米笔。", "explanation": "这里应该用〈支〉。平方米是面积单位，数笔要用量词“支”，不能用平方米。"}, {"text": "今天的气温是三十平方米。", "explanation": "这里应该用〈度〉。平方米是面积单位，不能用来表示气温。"}, {"text": "我们住了三平方米。", "explanation": "这里应该用〈天〉。平方米不能用来计量时间的长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一张平方米大约是一张小桌子的面积。", "corrected_sentence": "一平方米大约是一张小桌子的面积。", "error_description": "错误：数字“一”和“平方米”之间多加了量词“张”。正确：“平方米”本身就是单位，数字后直接接“平方米”，应说“一平方米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块草坪有两百的平方米。", "corrected_sentence": "这块草坪有两百平方米。", "error_description": "错误：数字和“平方米”之间多加了“的”。正确：数字后直接接“平方米”，应说“两百平方米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9c3a46a-96f5-483f-9334-4a7d0c4d882d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
