INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93157, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "宝贝是很喜欢、很珍爱的东西或孩子。", "primary_collocate": null, "pronunciation": "bǎo bèi", "ipa": "pɑʊ˨˩˦ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这块旧手表是爷爷最爱的宝贝。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小女儿是全家人的宝贝。", "target_word": "宝贝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把那张老照片当成宝贝，从不让别人碰。", "target_word": "宝贝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟有一个小盒子，里面全是他的宝贝。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆旧自行车是爸爸的宝贝，他每天都擦。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对她来说，女儿就是最大的宝贝。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子是父母的宝贝，谁都舍不得骂。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶把那对玉镯子当宝贝，一直放在柜子里。", "target_word": "宝贝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他像宝贝一样抱着刚买的小狗。", "target_word": "宝贝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套旧邮票是哥哥多年收藏的宝贝。", "target_word": "宝贝", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个宝贝", "label": "量词"}, {"form": "寶貝", "label": "繁体"}], "register": "口语", "sense_fingerprint": "自己特别珍爱、舍不得失去的东西或孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 镯 (Zipf 2.13)']::text[], '2534af2a-1516-45ed-a22b-20f025827a87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93157, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宝贝", "is_correct": true, "explanation": "宝贝：很喜欢、很珍爱的东西或孩子。"}, {"text": "百倍", "is_correct": false, "explanation": "bǎi（第三声）与 bǎo 韵母不同，意思是一百倍。"}, {"text": "保卫", "is_correct": false, "explanation": "wèi 与 bèi 声母不同，意思是保护、防卫。"}, {"text": "保费", "is_correct": false, "explanation": "fèi 与 bèi 声母不同，意思是保险费。"}, {"text": "报备", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是事先报告、备案。"}], "explanations": {"宝贝": "宝贝：很喜欢、很珍爱的东西或孩子。", "百倍": "bǎi（第三声）与 bǎo 韵母不同，意思是一百倍。", "保卫": "wèi 与 bèi 声母不同，意思是保护、防卫。", "保费": "fèi 与 bèi 声母不同，意思是保险费。", "报备": "bào（第四声）与 bǎo（第三声）声调不同，意思是事先报告、备案。"}, "sentence_index": null, "correct_answer": "宝贝"}, "level_3": {"options": [{"text": "宝贝", "is_correct": true, "explanation": "宝贝：很珍爱的东西，可以是“爷爷最爱的”。"}, {"text": "水果", "is_correct": false, "explanation": "语义：这句话说的是一块手表，不是水果，与主语矛盾。"}, {"text": "课本", "is_correct": false, "explanation": "语义：手表不是课本，“这块旧手表是……课本”前后不一致。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“爷爷最爱的”一般接具体物品或人，“空气”是抽象物质，不这样搭配。"}], "explanations": {"宝贝": "宝贝：很珍爱的东西，可以是“爷爷最爱的”。", "水果": "语义：这句话说的是一块手表，不是水果，与主语矛盾。", "课本": "语义：手表不是课本，“这块旧手表是……课本”前后不一致。", "空气": "搭配：“爷爷最爱的”一般接具体物品或人，“空气”是抽象物质，不这样搭配。"}, "sentence_index": 0, "correct_answer": "宝贝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校有三千个宝贝。", "explanation": "这里应该用〈孩子〉。宝贝指某个被珍爱的孩子，不用来泛指一大群孩子或学生。"}, {"text": "书桌上放着一张宝贝。", "explanation": "这里应该用〈件〉。宝贝指珍爱的物品，量词用“件”；“张”用于纸张、桌子等平面物品，不这么用。"}, {"text": "他的戒指上镶着一座大宝贝。", "explanation": "这里应该用〈件〉。座用于山、桥、建筑等大型物体，戒指上的饰物不用“座”计量；宝贝指珍贵的物品，量词用“件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宝贝", "is_correct": true, "explanation": "宝贝：很珍爱的孩子，与“舍不得骂”相合。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：父母不会把孩子当仇人，与“谁都舍不得骂”矛盾。"}, {"text": "对手", "is_correct": false, "explanation": "语义：“对手”指竞争的对象，与父母对孩子的感情不符。"}, {"text": "负担", "is_correct": false, "explanation": "搭配：“是父母的负担”与“谁都舍不得骂”语意冲突，一般不这样搭配。"}], "explanations": {"宝贝": "宝贝：很珍爱的孩子，与“舍不得骂”相合。", "仇人": "语义：父母不会把孩子当仇人，与“谁都舍不得骂”矛盾。", "对手": "语义：“对手”指竞争的对象，与父母对孩子的感情不符。", "负担": "搭配：“是父母的负担”与“谁都舍不得骂”语意冲突，一般不这样搭配。"}, "sentence_index": 6, "correct_answer": "宝贝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所幼儿园有五十名宝贝。", "explanation": "这里应该用〈儿童〉。宝贝指某个被珍爱的孩子，不用来统称一群孩子。"}, {"text": "展柜里摆着一台宝贝。", "explanation": "这里应该用〈件〉。台用于机器、仪器等，宝贝指珍爱的物品，量词用“件”。"}, {"text": "他把一匹宝贝放进了盒子里。", "explanation": "这里应该用〈件〉。匹用于马或成卷的布，宝贝指珍爱的物品，量词用“件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他收藏了一头宝贝。", "corrected_sentence": "他收藏了一件宝贝。", "error_description": "“宝贝”指珍爱的物品，量词可用“件”。这里错在量词“头”，“头”用于牛、猪等大型动物，不能用来数珍爱的物品，应改为“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块石头是我最珍爱的宝贝们。", "corrected_sentence": "这块石头是我最珍爱的宝贝。", "error_description": "“宝贝们”是复数形式，多用于指一群人（多为孩子）。指一块石头时不能加“们”，应去掉，改为“宝贝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ded08da-eef4-42ea-a58b-074c223c2b8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
