INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某人或某一代人之后的子孙。", "primary_collocate": null, "pronunciation": "hòu dài", "ipa": "xoʊ˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这位古代名人的后代住在南方。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要给后代留下干净的水。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想给后代一个好环境。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老城是前人留给后代的。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树是为后代种的。", "target_word": "后代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一位古代将军的后代。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的人都是同一个人的后代。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的后代会怎么看今天的事?", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书会一直留给后代。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孔子的后代现在还住在山东。", "target_word": "后代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "子孙后代", "label": "复合"}], "register": "中性", "sense_fingerprint": "某人或某一代人以后的所有子孙,范围较广", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76794e94-6924-4452-985d-713c29f920c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后代", "is_correct": true, "explanation": "后代指某人的子孙，古代名人的子孙住在南方，符合语境。"}, {"text": "文物", "is_correct": false, "explanation": "语义：文物是器物，不会居住在某地。"}, {"text": "路人", "is_correct": false, "explanation": "搭配：“路人”指路上的行人，不能说成“古代名人的路人”。"}, {"text": "石碑", "is_correct": false, "explanation": "语义：石碑是刻字的石头，不会居住。"}], "explanations": {"后代": "后代指某人的子孙，古代名人的子孙住在南方，符合语境。", "文物": "语义：文物是器物，不会居住在某地。", "路人": "搭配：“路人”指路上的行人，不能说成“古代名人的路人”。", "石碑": "语义：石碑是刻字的石头，不会居住。"}, "sentence_index": 0, "correct_answer": "后代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同事里有个后代，比我晚十年入行。", "explanation": "这里应该用〈后辈〉。后代指子孙，同行中后进的人要用后辈。"}, {"text": "我们班的后代个个成绩都好。", "explanation": "这里应该用〈同学〉。后代指子孙，班里的同学要说同学。"}, {"text": "这辆地铁上坐着三个后代。", "explanation": "这里应该用〈乘客〉。后代指子孙，车上的人要说乘客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后代", "is_correct": true, "explanation": "后代指子孙，同一个人的子孙组成一个村子，符合语境。"}, {"text": "乘客", "is_correct": false, "explanation": "配价：“乘客”需要交通工具作补足，不能说“同一个人的乘客”。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像是雕刻出来的人像，不是活人，不能与村民构成血缘关系。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，不是人，与“村子的人”的句意不合。"}], "explanations": {"后代": "后代指子孙，同一个人的子孙组成一个村子，符合语境。", "乘客": "配价：“乘客”需要交通工具作补足，不能说“同一个人的乘客”。", "雕像": "语义：雕像是雕刻出来的人像，不是活人，不能与村民构成血缘关系。", "窗户": "语义：窗户是建筑构件，不是人，与“村子的人”的句意不合。"}, "sentence_index": 6, "correct_answer": "后代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前线的士兵需要后代的支援。", "explanation": "这里应该用〈后方〉。后代指子孙，为前线提供支援的地方要说后方。"}, {"text": "他是我的后代，比我小一届。", "explanation": "这里应该用〈学弟〉。后代指子孙，同校的低年级同学要用学弟。"}, {"text": "这场比赛的看台上坐着五千个后代。", "explanation": "这里应该用〈观众〉。后代指子孙，坐在看台上看比赛的人要说观众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家的三只后代都在国外定居。", "corrected_sentence": "这位画家的三个后代都在国外定居。", "error_description": "“后代”指人，量词应用“个”，“只”多用于动物，应改为“三个后代”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位诗人的两条后代都爱读书。", "corrected_sentence": "这位诗人的两位后代都爱读书。", "error_description": "“后代”指人，量词应用“位”或“个”，“条”用于细长的东西，应改为“两位后代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
