INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93161, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对打是两个人互相打对方。", "primary_collocate": null, "pronunciation": "duì dǎ", "ipa": "tweɪ˥˩ ta˨˩", "syllable_count": 2, "sentences": [{"text": "两个男孩在路边对打起来了。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩不说话，直接就对打。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个小孩为了玩具对打，妈妈很生气。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察来了，对打的两个人才停下来。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上，两个年轻人在门口对打。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在街上对打，大家都不敢过去。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人喝了酒，一句话不对就对打。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，同学之间不能对打。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，两个英雄在山上对打。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到他们对打，我马上叫了老师。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对打了", "label": "体标（了）"}, {"form": "对打过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "对打：两个人动手互相打架", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3db2a8-898c-4672-8b0b-0fbffde2e471') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93161, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绣花", "is_correct": false, "explanation": "语义：绣花是细致的手工活，与两个男孩在路边打闹的场景不符"}, {"text": "对打", "is_correct": true, "explanation": "对打：双方动手互相打，与“起来”搭配，表示动手打起来"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清洁环境的活动，与两个男孩在路边的动作不符"}, {"text": "结婚", "is_correct": false, "explanation": "配价：结婚需要“跟＋对象”的结构，句中没有这一结构，而且两个男孩不能结婚"}], "explanations": {"绣花": "语义：绣花是细致的手工活，与两个男孩在路边打闹的场景不符", "对打": "对打：双方动手互相打，与“起来”搭配，表示动手打起来", "打扫": "语义：打扫是清洁环境的活动，与两个男孩在路边的动作不符", "结婚": "配价：结婚需要“跟＋对象”的结构，句中没有这一结构，而且两个男孩不能结婚"}, "sentence_index": 0, "correct_answer": "对打"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两位老板心平气和地对打了一个小时，最后签了合同。", "explanation": "这里应该用〈对话〉。对打指双方动手互打，与“心平气和”的语境矛盾；两人交谈应用对话"}, {"text": "他们用对讲机对打，互相通报位置。", "explanation": "这里应该用〈通话〉。对打指动手互打，用对讲机互相联络是通话，不能说对打"}, {"text": "妈妈和女儿在厨房里对打了很久，聊了很多家常。", "explanation": "这里应该用〈交谈〉。对打指动手互打，与“聊了很多家常”不符；日常聊天应用交谈"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93161, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干杯", "is_correct": false, "explanation": "语义：干杯是敬酒的动作，与“一句话不对”引发的冲突无关"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“就”后接的动作要紧接前一事件，“一句话不对就睡觉”不成立"}, {"text": "对打", "is_correct": true, "explanation": "对打：双方动手互相打，与“一句话不对就”的冲突语境相符"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋是平和的游戏，与“一句话不对”引发的激烈冲突不符"}], "explanations": {"干杯": "语义：干杯是敬酒的动作，与“一句话不对”引发的冲突无关", "睡觉": "搭配：“就”后接的动作要紧接前一事件，“一句话不对就睡觉”不成立", "对打": "对打：双方动手互相打，与“一句话不对就”的冲突语境相符", "下棋": "语义：下棋是平和的游戏，与“一句话不对”引发的激烈冲突不符"}, "sentence_index": 6, "correct_answer": "对打"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两位候选人在电视台对打了两个小时，观众都在看。", "explanation": "这里应该用〈辩论〉。对打指动手互打，双方用言语争论要用辩论，不能说对打"}, {"text": "两国领导人在会议厅对打了三天，最后签了协议。", "explanation": "这里应该用〈会谈〉。对打指动手互打，正式的外交商谈要用会谈，不能说对打"}, {"text": "两人为了方案在办公室对打了一上午，最后达成一致。", "explanation": "这里应该用〈讨论〉。对打指动手互打，在办公室商议问题要用讨论，不能说对打"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个司机在马路上对打过起来了，交警赶紧过去。", "corrected_sentence": "两个司机在马路上对打起来了，交警赶紧过去。", "error_description": "错误：“对打过起来了”，多加了“过”。表示动作开始的“起来”不能和表示经历的“过”一起用，应为“对打起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个醉汉在酒吧门口对打下来，服务员赶紧报了警。", "corrected_sentence": "两个醉汉在酒吧门口对打起来，服务员赶紧报了警。", "error_description": "错误：“对打下来”，应为“对打起来”。表示动手打起来、事态开始要用“起来”，“下来”不表示这个意思", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
