INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93162, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方面对面互相打球或练习。", "primary_collocate": null, "pronunciation": "duì dǎ", "ipa": "tweɪ˥˩ ta˨˩", "syllable_count": 2, "sentences": [{"text": "我和哥哥在公园里对打乒乓球。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位运动员在场上对打了很久。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练让我们两个人一组对打。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩每天下午都去球场对打。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先对打几个球，再开始比赛。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个学生在训练场上对打，教练在旁边看。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找人跟我对打网球。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李和小王对打得很快，很好看。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开始比赛前，他们先对打十分钟。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹刚学会打球，还不会和别人对打。", "target_word": "对打", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对打了", "label": "体标（了）"}, {"form": "对打过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "对打：双方面对面互相打球或练习", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de3db2a8-898c-4672-8b0b-0fbffde2e471') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "搭配：参观的对象是场所或展品，不能说参观乒乓球"}, {"text": "回忆", "is_correct": false, "explanation": "语义：回忆是想起过去的事，与“在公园里”正在进行的活动不符"}, {"text": "对打", "is_correct": true, "explanation": "对打：双方面对面互相打球，与“乒乓球”搭配"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理针对坏掉的器物，句中没有东西坏了的语境"}], "explanations": {"参观": "搭配：参观的对象是场所或展品，不能说参观乒乓球", "回忆": "语义：回忆是想起过去的事，与“在公园里”正在进行的活动不符", "对打": "对打：双方面对面互相打球，与“乒乓球”搭配", "修理": "语义：修理针对坏掉的器物，句中没有东西坏了的语境"}, "sentence_index": 0, "correct_answer": "对打"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个老同学在饭店里对打了半天，聊了很多往事。", "explanation": "这里应该用〈聊天〉。对打指双方面对面互相打球，两人闲聊要用聊天，不能说对打"}, {"text": "他在台上对打了半个小时，台下的人一直在听。", "explanation": "这里应该用〈演讲〉。对打指双方面对面互相打球，一个人在台上讲话要用演讲，不能说对打"}, {"text": "老师在教室里对打了一个小时，学生们认真地记笔记。", "explanation": "这里应该用〈讲解〉。对打指双方面对面互相打球，老师单方面讲题要用讲解，不能说对打"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收藏", "is_correct": false, "explanation": "语义：收藏是把东西留存起来，与“跟我……网球”的活动不符"}, {"text": "观察", "is_correct": false, "explanation": "搭配：观察的对象多是现象或动植物，不说观察网球"}, {"text": "对打", "is_correct": true, "explanation": "对打：双方面对面互相打球，与“网球”搭配，表示一起练习"}, {"text": "批发", "is_correct": false, "explanation": "语义：批发是成批卖东西，与“找人跟我……”的活动完全不符"}], "explanations": {"收藏": "语义：收藏是把东西留存起来，与“跟我……网球”的活动不符", "观察": "搭配：观察的对象多是现象或动植物，不说观察网球", "对打": "对打：双方面对面互相打球，与“网球”搭配，表示一起练习", "批发": "语义：批发是成批卖东西，与“找人跟我……”的活动完全不符"}, "sentence_index": 6, "correct_answer": "对打"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个朋友在咖啡馆对打了一下午，聊得很开心。", "explanation": "这里应该用〈交谈〉。对打指双方面对面互相打球，不能用于两人聊天，聊天应用交谈"}, {"text": "两国领导人在会议厅心平气和地对打了三天。", "explanation": "这里应该用〈会谈〉。对打指双方面对面互相打球，不能用于正式商谈，会谈才是正确说法"}, {"text": "他们俩在办公室对打了一上午，最后达成一致。", "explanation": "这里应该用〈讨论〉。对打指双方面对面互相打球，不能用于办公室里的商议，讨论一个问题应用讨论"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和同学在操场上被对打羽毛球，玩得很开心。", "corrected_sentence": "我和同学在操场上对打羽毛球，玩得很开心。", "error_description": "错误：“被对打”，多加了“被”。“对打”是双方互相打，不能用被动句，应为“对打羽毛球”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想找个朋友跟我一起对打了网球，练练发球。", "corrected_sentence": "我想找个朋友跟我一起对打网球，练练发球。", "error_description": "错误：“对打了”，应为“对打”。“想找个朋友”指将要做的事，句中不能用“了”表示已经完成", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bc62b8-4efb-48a1-a54a-c11c6b3e4577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
