INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手把是手拿着的那个地方。", "primary_collocate": null, "pronunciation": "shǒu bǎ", "ipa": "ʂoʊ˨˩˦ pa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个水壶的手把是热的，小心一点。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的行李箱坏了，手把拉不出来。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀的手把是木头做的，很好看。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的手小，握不住这么粗的手把。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平底锅的手把用久了会松。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请抓着公共汽车的手把，站稳。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一个袋子挂在车门的手把上。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在手把上缠了一圈布，这样握着不滑。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶杯的手把很小，只能伸进一根手指。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手把是新换的，比以前好用。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "门手把", "label": "复合"}], "register": "中性", "sense_fingerprint": "手把：手拿着的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手把", "is_correct": true, "explanation": "手把：手拿着的那个地方。句中指水壶上可以握的部位，热的就是它。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“热”不能用来形容颜色，“颜色是热的”不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：水壶上没有窗户，此处不能填入。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音不能说“是热的”，句意不通。"}], "explanations": {"手把": "手把：手拿着的那个地方。句中指水壶上可以握的部位，热的就是它。", "颜色": "搭配：“热”不能用来形容颜色，“颜色是热的”不通。", "窗户": "语义：水壶上没有窗户，此处不能填入。", "声音": "搭配：声音不能说“是热的”，句意不通。"}, "sentence_index": 0, "correct_answer": "手把"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抓住了我的手把，总拿这件事威胁我。", "explanation": "这里应该用〈把柄〉。把柄指被人抓住、用来要挟的弱点，手把指手拿着的地方，不能指人的弱点。"}, {"text": "走廊的手把太矮，孩子扶不到。", "explanation": "这里应该用〈扶手〉。扶手是沿墙或楼梯设置、供人扶着的栏杆，手把指手拿着的地方，不用于走廊。"}, {"text": "这罐啤酒的手把拉不开，我拿了把钥匙撬。", "explanation": "这里应该用〈拉环〉。易拉罐上用手指拉开的小环叫拉环，罐身上没有手把。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手把", "is_correct": true, "explanation": "手把：手拿着的那个地方。句中指车门上可以挂东西的把手。"}, {"text": "天空", "is_correct": false, "explanation": "语义：车门上挂东西不能挂在天空上，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：袋子不能挂在“声音”上，声音也不能用来挂东西。"}, {"text": "名字", "is_correct": false, "explanation": "语义：车门上没有名字可以挂袋子，此处不能填入。"}], "explanations": {"手把": "手把：手拿着的那个地方。句中指车门上可以挂东西的把手。", "天空": "语义：车门上挂东西不能挂在天空上，句意不通。", "声音": "搭配：袋子不能挂在“声音”上，声音也不能用来挂东西。", "名字": "语义：车门上没有名字可以挂袋子，此处不能填入。"}, "sentence_index": 6, "correct_answer": "手把"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "遥控器的手把不灵了，换台很麻烦。", "explanation": "这里应该用〈按钮〉。遥控器靠按钮操作；手把指器物上供手握持的部分，遥控器上没有这样的部件。"}, {"text": "这块手表的手把断了，我得换一根新的。", "explanation": "这里应该用〈表带〉。表带是绕在手腕上的带子；手把指器物上供手握持的部分，手表上没有这样的部件。"}, {"text": "这台电脑的手把坏了，只好另外买一个。", "explanation": "这里应该用〈键盘〉。键盘是输入文字的按键组；手把指器物上供手握持的部分，电脑上没有这样的部件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抽屉上装了一颗手把，拉起来很方便。", "corrected_sentence": "抽屉上装了一个手把，拉起来很方便。", "error_description": "量词误用：手把是器物上的部件，应用量词“个”，“颗”多用于小而圆的东西，不用于手把。正确为“一个手把”，“一颗手把”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她踢着行李箱的手把，慢慢往前走。", "corrected_sentence": "她拉着行李箱的手把，慢慢往前走。", "error_description": "搭配错误：手把是供手握持的部分，应说“拉着/握着手把”，不能说“踢着手把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
