INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "器物上供手握持的部分；把手。", "primary_collocate": null, "pronunciation": "shǒu bǎ", "ipa": "ʂoʊ˨˩˦ pa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个杯子的手把断了，不能用了。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈握着婴儿车的手把，慢慢地走。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天一摸门的手把，手就凉了。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅的手把很烫，你要用布拿。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞的手把是木头做的。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一只手提着箱子的手把，另一只手拿手机。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手把太细了，我握不住。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把行李箱的手把拉出来，慢慢走。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刀的手把是塑料的，拿着很舒服。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个抽屉的手把掉了，我用手指拉开它。", "target_word": "手把", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "门手把", "label": "复合"}], "register": "中性", "sense_fingerprint": "手把：器物上供手握持的部分（把手）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0806fb53-8715-4a01-946f-96193aca6881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手把", "is_correct": true, "explanation": "手把：器物上供手握持的部分，即把手。句中的杯子有手把，断了就不能用。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：杯子上没有墙壁，“杯子的墙壁断了”不合常识。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“断”不能用于颜色，“颜色断了”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：杯子上没有窗户，此处不能填入。"}], "explanations": {"手把": "手把：器物上供手握持的部分，即把手。句中的杯子有手把，断了就不能用。", "墙壁": "语义：杯子上没有墙壁，“杯子的墙壁断了”不合常识。", "颜色": "搭配：“断”不能用于颜色，“颜色断了”说不通。", "窗户": "语义：杯子上没有窗户，此处不能填入。"}, "sentence_index": 0, "correct_answer": "手把"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抓住了我的手把，一直拿来要挟我。", "explanation": "这里应该用〈把柄〉。把柄指被人拿来要挟的弱点，手把是器物上供手握持的部分，不能指人的弱点。"}, {"text": "楼梯的手把很滑，老人上下楼要扶稳。", "explanation": "这里应该用〈扶手〉。扶手是沿楼梯设置、供人扶着的栏杆，手把专指器物上供手握持的部分，不用于楼梯。"}, {"text": "这罐饮料的手把拉不开，我得用钥匙撬。", "explanation": "这里应该用〈拉环〉。易拉罐上用手指拉开的小环叫拉环，罐身上没有手把，这里应说拉环。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手把", "is_correct": true, "explanation": "手把：器物上供手握持的部分。句中指可以握的把手，太细就握不住。"}, {"text": "地板", "is_correct": false, "explanation": "搭配：“握”不能用于地板，“我握不住地板”说不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是器物，不能握，也谈不上太细。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不能用“太细”来形容。"}], "explanations": {"手把": "手把：器物上供手握持的部分。句中指可以握的把手，太细就握不住。", "地板": "搭配：“握”不能用于地板，“我握不住地板”说不通。", "天空": "语义：天空不是器物，不能握，也谈不上太细。", "颜色": "搭配：颜色不能用“太细”来形容。"}, "sentence_index": 6, "correct_answer": "手把"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥的手把很矮，行人很容易掉下去。", "explanation": "这里应该用〈栏杆〉。栏杆是桥边拦挡行人的杆状设施；手把指器物上供手握持的部分，不指桥上的围栏。"}, {"text": "这件外套的手把坏了，只好用别针别上。", "explanation": "这里应该用〈拉链〉。拉链是衣服上用来开合的部件；手把指器物上供手握持的部分，外套上没有这样的部件。"}, {"text": "这本书的手把破了，我用胶带粘好了。", "explanation": "这里应该用〈封皮〉。封皮是书籍外面的硬纸或布；手把指器物上供手握持的部分，书上没有这样的部件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我换了一颗手把，用起来很顺手。", "corrected_sentence": "我换了一个手把，用起来很顺手。", "error_description": "量词误用：手把是器物的部件，应用量词“个”，“颗”多用于小而圆的东西，不用于手把。正确为“一个手把”，“一颗手把”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我踢着行李箱的手把，慢慢往前走。", "corrected_sentence": "我抓着行李箱的手把，慢慢往前走。", "error_description": "搭配错误：手把是供手握持的部分，应说“抓着/握着手把”，不能说“踢着手把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba0e186-4357-4790-bdd5-a6d2a7a6a7c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
