INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93169, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爱才是很喜欢有本事的人。", "primary_collocate": null, "pronunciation": "ài cái", "ipa": "ai˥˩ tsʰai˧˥", "syllable_count": 2, "sentences": [{"text": "王经理很爱才，常常夸奖年轻人。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师爱才，总是多给好学生机会。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说他爱才，所以有人愿意来。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长是个爱才的人，喜欢有本事的学生。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱才，看到会画画的孩子就高兴。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的老板爱才，不管年纪大小。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她爱才，常请有本事的人来家里吃饭。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱才的老师，对有本事的学生特别好。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一向爱才，听说你会写诗，想认识你。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人爱才，见到聪明的孩子就笑。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愛才", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很喜欢有本事的人，对有本事的人有好感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8d98bf-ca56-4497-b80d-a8800a5dfbfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93169, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱才", "is_correct": true, "explanation": "正确：“很爱才”表示很喜欢有本事的人，与“常常夸奖年轻人”一致。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：讨厌与“常常夸奖年轻人”的态度矛盾。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：嫉妒是忌恨别人的长处，与夸奖年轻人的语境不符。"}, {"text": "排斥", "is_correct": false, "explanation": "配价：“排斥”需要带宾语（排斥某人），单独用“很排斥”不完整。"}], "explanations": {"爱才": "正确：“很爱才”表示很喜欢有本事的人，与“常常夸奖年轻人”一致。", "讨厌": "语义：讨厌与“常常夸奖年轻人”的态度矛盾。", "嫉妒": "语义：嫉妒是忌恨别人的长处，与夸奖年轻人的语境不符。", "排斥": "配价：“排斥”需要带宾语（排斥某人），单独用“很排斥”不完整。"}, "sentence_index": 0, "correct_answer": "爱才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很爱才自己的孩子，从不让他们吃苦。", "explanation": "这里应该用〈疼爱〉。爱才专指喜欢有本事的人，爱孩子要说疼爱。"}, {"text": "这位画家很爱才那幅画，一直不肯卖。", "explanation": "这里应该用〈珍爱〉。爱才的对象是有本事的人，画作要用珍爱。"}, {"text": "他很爱才那只旧手表，修了好几次。", "explanation": "这里应该用〈爱惜〉。爱才的对象是人，旧物要用爱惜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱才", "is_correct": true, "explanation": "正确：“她爱才”表示喜欢有本事的人，与“常请有本事的人来家里吃饭”一致。"}, {"text": "怕", "is_correct": false, "explanation": "语义：怕与“常请有本事的人来家里吃饭”的态度矛盾。"}, {"text": "反感", "is_correct": false, "explanation": "语义：反感与常请人来家里吃饭的态度相反。"}, {"text": "轻视", "is_correct": false, "explanation": "配价：“轻视”需要带宾语，单独用“她轻视”不完整。"}], "explanations": {"爱才": "正确：“她爱才”表示喜欢有本事的人，与“常请有本事的人来家里吃饭”一致。", "怕": "语义：怕与“常请有本事的人来家里吃饭”的态度矛盾。", "反感": "语义：反感与常请人来家里吃饭的态度相反。", "轻视": "配价：“轻视”需要带宾语，单独用“她轻视”不完整。"}, "sentence_index": 6, "correct_answer": "爱才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总是爱才那辆新车，每天都擦两遍。", "explanation": "这里应该用〈爱惜〉。爱才只用于有本事的人，车要说爱惜。"}, {"text": "那个孩子很爱才冰淇淋，每天都要吃两个。", "explanation": "这里应该用〈喜欢〉。爱才只用于人，不用于食物。"}, {"text": "他很爱才这片土地，从不让人破坏它。", "explanation": "这里应该用〈爱护〉。爱才只用于有本事的人，土地要说爱护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长正在爱才，常常鼓励年轻老师。", "corrected_sentence": "校长爱才，常常鼓励年轻老师。", "error_description": "错误：“爱才”是状态动词，表示持续的喜好，不能用“正在”表示进行。正确：去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她被爱才，常请有本事的年轻人来家里做客。", "corrected_sentence": "她爱才，常请有本事的年轻人来家里做客。", "error_description": "错误：“爱才”是主动动词，不能直接加“被”构成被动句。正确：“她爱才”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
