INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爱惜、重视有才能的人。", "primary_collocate": null, "pronunciation": "ài cái", "ipa": "ai˥˩ tsʰai˧˥", "syllable_count": 2, "sentences": [{"text": "公司爱才，给有本事的人很高的工资。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好领导要爱才，也要给人才机会。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱才，把最好的位置给了小李。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校爱才，每年都送优秀老师去学习。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱才的经理，会留住有能力的员工。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱才，有本事的人都走了。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家爱才，欢迎留学生回来工作。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板爱才，所以大家都愿意留下来。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她爱才，常帮助有才能的年轻人。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个爱才的城市，会有更多人来工作。", "target_word": "爱才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愛才", "label": "繁体"}], "register": "中性", "sense_fingerprint": "爱惜并重视有才能的人，愿意给他们机会和待遇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8d98bf-ca56-4497-b80d-a8800a5dfbfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱才", "is_correct": true, "explanation": "正确：公司重视有本事的人，所以给他们很高的工资。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：讨厌有本事的人，就不会给他们很高的工资，与句意矛盾。"}, {"text": "排斥", "is_correct": false, "explanation": "配价：“排斥”需要带宾语（排斥某人），单独用“公司排斥”不完整。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：嫉妒是忌恨别人，与给人才高工资的语境矛盾。"}], "explanations": {"爱才": "正确：公司重视有本事的人，所以给他们很高的工资。", "讨厌": "语义：讨厌有本事的人，就不会给他们很高的工资，与句意矛盾。", "排斥": "配价：“排斥”需要带宾语（排斥某人），单独用“公司排斥”不完整。", "嫉妒": "语义：嫉妒是忌恨别人，与给人才高工资的语境矛盾。"}, "sentence_index": 0, "correct_answer": "爱才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校爱才那些成绩很差的学生，希望他们努力学习。", "explanation": "这里应该用〈关心〉。爱才只用于有才能的人，成绩差的学生要说关心。"}, {"text": "图书馆很爱才那些旧书，从不让人借阅。", "explanation": "这里应该用〈爱惜〉。爱才的对象是有才能的人，书籍要用爱惜。"}, {"text": "老板爱才那辆旧车，一直不肯卖掉。", "explanation": "这里应该用〈爱惜〉。爱才指重视人才，旧车要用爱惜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱才", "is_correct": true, "explanation": "正确：国家重视人才，所以欢迎留学生回来工作。"}, {"text": "怕", "is_correct": false, "explanation": "语义：怕与“欢迎留学生回来工作”的态度矛盾。"}, {"text": "轻视", "is_correct": false, "explanation": "配价：“轻视”需要带宾语，单独用“国家轻视”不完整。"}, {"text": "戒备", "is_correct": false, "explanation": "语义：戒备是提防，与欢迎留学生回来工作的语境相反。"}], "explanations": {"爱才": "正确：国家重视人才，所以欢迎留学生回来工作。", "怕": "语义：怕与“欢迎留学生回来工作”的态度矛盾。", "轻视": "配价：“轻视”需要带宾语，单独用“国家轻视”不完整。", "戒备": "语义：戒备是提防，与欢迎留学生回来工作的语境相反。"}, "sentence_index": 6, "correct_answer": "爱才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他爱才那棵老树，每天都给它浇水。", "explanation": "这里应该用〈保护〉。爱才指重视有才能的人，老树要说保护。"}, {"text": "这家餐厅的菜很爱才，味道很好。", "explanation": "这里应该用〈讲究〉。爱才只用于人，菜品要说讲究。"}, {"text": "孩子很爱才那只玩具熊，每天都抱着睡觉。", "explanation": "这里应该用〈喜欢〉。爱才只用于人，玩具要说喜欢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校正在爱才，每年都送老师去进修。", "corrected_sentence": "学校爱才，每年都送老师去进修。", "error_description": "错误：“爱才”是状态动词，不能用“正在”表示进行。正确：去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司一向被爱才，所以很多人愿意来。", "corrected_sentence": "公司一向爱才，所以很多人愿意来。", "error_description": "错误：“爱才”是主动动词，不能直接加“被”构成被动句。正确：“公司一向爱才”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e286751-3bfa-4706-aff2-38058e45a08d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93171, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "“放”与“拘留”意思相反，拘留是限制人身自由，放是解除限制。"}, {"text": "送", "is_correct": false, "explanation": "与“拘留”没有反义关系：“送”表示把人或物送往别处。"}, {"text": "吃", "is_correct": false, "explanation": "与“拘留”没有反义关系：“吃”指把食物咽下。"}, {"text": "种", "is_correct": false, "explanation": "与“拘留”没有反义关系：“种”指把种子埋入土中。"}], "correct_answer": "放", "explanations": {"放": "“放”与“拘留”意思相反，拘留是限制人身自由，放是解除限制。", "送": "与“拘留”没有反义关系：“送”表示把人或物送往别处。", "吃": "与“拘留”没有反义关系：“吃”指把食物咽下。", "种": "与“拘留”没有反义关系：“种”指把种子埋入土中。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93171, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "“放”与“拘留”意思相反，指解除对人身的限制。"}, {"text": "唱", "is_correct": false, "explanation": "与“拘留”没有反义关系：“唱”指发出歌声。"}, {"text": "搬", "is_correct": false, "explanation": "与“拘留”没有反义关系：“搬”指移动物体的位置。"}, {"text": "游", "is_correct": false, "explanation": "与“拘留”没有反义关系：“游”指在水中行进。"}], "correct_answer": "放", "explanations": {"放": "“放”与“拘留”意思相反，指解除对人身的限制。", "唱": "与“拘留”没有反义关系：“唱”指发出歌声。", "搬": "与“拘留”没有反义关系：“搬”指移动物体的位置。", "游": "与“拘留”没有反义关系：“游”指在水中行进。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93171, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拘留是把犯了错的人先关一小段时间。", "primary_collocate": null, "pronunciation": "jū liú", "ipa": "tɕy˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "警察把他拘留了三天。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了酒还开车,警察拘留了他。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王打了人,警察要拘留他。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们拘留了那个小偷两天。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了错,先拘留一天再说。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前被拘留过一次。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察没有拘留他,只是说了他几句。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么要拘留这个年轻人?", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打架了,警察会拘留他几天。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察拘留了那个人，还没放他。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拘留了", "label": "体标"}, {"form": "拘留过", "label": "体标"}], "register": "中性", "sense_fingerprint": "警察把犯错的人先关几天(日常说法)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76794e94-6924-4452-985d-713c29f920c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拘留", "is_correct": true, "explanation": "“拘留”指短期关押犯错的人，符合“把他……了三天”的语境。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹去污物，不能用于对人的处置，也不能表示关押三天。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指把人或物送往某处，不能表示关押三天。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是给人或动物吃东西，不能用于对犯错者的处置。"}], "explanations": {"拘留": "“拘留”指短期关押犯错的人，符合“把他……了三天”的语境。", "擦": "语义：“擦”是抹去污物，不能用于对人的处置，也不能表示关押三天。", "送": "语义：“送”指把人或物送往某处，不能表示关押三天。", "喂": "语义：“喂”是给人或动物吃东西，不能用于对犯错者的处置。"}, "sentence_index": 0, "correct_answer": "拘留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个小偷被拘留了两年。", "explanation": "这里应该用〈关押〉。拘留是短期措施，行政拘留最长十五日，关押几年的要用关押。"}, {"text": "警察拘留了他的汽车三天。", "explanation": "这里应该用〈扣留〉。拘留的对象是人，车辆等财物要用扣留。"}, {"text": "他因为迟到被学校拘留了一周。", "explanation": "这里应该用〈关禁闭〉。拘留是公安机关依法执行的措施，学校的处罚要用关禁闭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拘留", "is_correct": true, "explanation": "“拘留”指短期限制人身自由，句中“没有……他，只是说了他几句”正好对应不关押的情况。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说“穿他”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃他”。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，不能用于人，与句中意思不合。"}], "explanations": {"拘留": "“拘留”指短期限制人身自由，句中“没有……他，只是说了他几句”正好对应不关押的情况。", "穿": "搭配：“穿”的对象是衣物，不能说“穿他”。", "吃": "搭配：“吃”的对象是食物，不能说“吃他”。", "烤": "语义：“烤”是加热食物，不能用于人，与句中意思不合。"}, "sentence_index": 6, "correct_answer": "拘留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疫情期间，他被拘留在医院十四天。", "explanation": "这里应该用〈隔离〉。拘留是依法的处罚措施，防疫隔离不能用拘留。"}, {"text": "他被拘留在家里，不能出门。", "explanation": "这里应该用〈软禁〉。拘留要关在拘留所，不能说在家里。"}, {"text": "他因为迟到被拘留了一节课。", "explanation": "这里应该用〈罚站〉。拘留是公安机关依法执行的措施，学校的处罚不能用拘留。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察把那个醉汉拘留得一夜。", "corrected_sentence": "警察把那个醉汉拘留了一夜。", "error_description": "时量补语前应用“了”表示完成，不能用“得”。“拘留得一夜”是错误形式，应为“拘留了一夜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察没有拘留了那个小偷。", "corrected_sentence": "警察没有拘留那个小偷。", "error_description": "用“没有”否定“拘留”时，动词后不能再加“了”。应去掉“了”，说成“没有拘留那个小偷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "释放", "is_correct": true, "explanation": "“释放”与“拘留”意思相反，指依法解除对人身的限制。"}, {"text": "搬", "is_correct": false, "explanation": "与“拘留”没有反义关系：“搬”指移动物体。"}, {"text": "唱", "is_correct": false, "explanation": "与“拘留”没有反义关系：“唱”指发出歌声。"}, {"text": "游", "is_correct": false, "explanation": "与“拘留”没有反义关系：“游”指在水中行进。"}], "correct_answer": "释放", "explanations": {"释放": "“释放”与“拘留”意思相反，指依法解除对人身的限制。", "搬": "与“拘留”没有反义关系：“搬”指移动物体。", "唱": "与“拘留”没有反义关系：“唱”指发出歌声。", "游": "与“拘留”没有反义关系：“游”指在水中行进。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "释放", "is_correct": true, "explanation": "“释放”与“拘留”意思相反，指依法解除对人身的限制。"}, {"text": "吃", "is_correct": false, "explanation": "与“拘留”没有反义关系：“吃”指把食物咽下。"}, {"text": "种", "is_correct": false, "explanation": "与“拘留”没有反义关系：“种”指把种子埋入土中。"}, {"text": "跳", "is_correct": false, "explanation": "与“拘留”没有反义关系：“跳”指腿部用力使身体离开地面。"}], "correct_answer": "释放", "explanations": {"释放": "“释放”与“拘留”意思相反，指依法解除对人身的限制。", "吃": "与“拘留”没有反义关系：“吃”指把食物咽下。", "种": "与“拘留”没有反义关系：“种”指把种子埋入土中。", "跳": "与“拘留”没有反义关系：“跳”指腿部用力使身体离开地面。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依法将违法者在短期内留置并限制其自由。", "primary_collocate": null, "pronunciation": "jū liú", "ipa": "tɕy˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "公安机关依法拘留了这名违法者。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定,可以拘留违法的人十五天。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方依法拘留了三名嫌疑人。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察因他打人,依法拘留了他。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方决定依法拘留他。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有法律规定,不能随便拘留别人。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察依法拘留他十天。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公安机关拘留过很多违法者。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "依法拘留违法者,是警察的工作。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方已经依法拘留了那个司机。", "target_word": "拘留", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拘留了", "label": "体标"}, {"form": "拘留过", "label": "体标"}], "register": "书面", "sense_fingerprint": "公安机关依法短期留置违法者并限制其自由(法律用语)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76794e94-6924-4452-985d-713c29f920c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拘留", "is_correct": true, "explanation": "“拘留”是依法短期限制违法者人身自由，与句中“依法”的语境相符。"}, {"text": "查封", "is_correct": false, "explanation": "搭配：“查封”针对房屋、场所等财物，不能用于人。"}, {"text": "表彰", "is_correct": false, "explanation": "语义：“表彰”是褒扬有功的人，与“违法者”矛盾。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”针对账户、资产，不能用于人。"}], "explanations": {"拘留": "“拘留”是依法短期限制违法者人身自由，与句中“依法”的语境相符。", "查封": "搭配：“查封”针对房屋、场所等财物，不能用于人。", "表彰": "语义：“表彰”是褒扬有功的人，与“违法者”矛盾。", "冻结": "搭配：“冻结”针对账户、资产，不能用于人。"}, "sentence_index": 0, "correct_answer": "拘留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察依法拘留了他的手机。", "explanation": "这里应该用〈扣押〉。拘留针对人身自由，手机等财物要用扣押。"}, {"text": "他因为贩毒被判了三年拘留。", "explanation": "这里应该用〈监禁〉。拘留最长十五日，判几年要用监禁。"}, {"text": "他因为超速被依法拘留两百元。", "explanation": "这里应该用〈罚款〉。拘留是限制人身自由的措施，不能按金额计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拘留", "is_correct": true, "explanation": "“拘留”是依法短期限制人身自由，与“依法……他十天”的语境相符。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”针对申请或事项，不能用于拘禁人身。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是褒奖，与依法限制人身自由的意思相反。"}, {"text": "签发", "is_correct": false, "explanation": "搭配：“签发”的对象是证件、文件，不能说“签发他十天”。"}], "explanations": {"拘留": "“拘留”是依法短期限制人身自由，与“依法……他十天”的语境相符。", "批准": "语义：“批准”针对申请或事项，不能用于拘禁人身。", "表扬": "语义：“表扬”是褒奖，与依法限制人身自由的意思相反。", "签发": "搭配：“签发”的对象是证件、文件，不能说“签发他十天”。"}, "sentence_index": 6, "correct_answer": "拘留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察依法拘留了那家饭店。", "explanation": "这里应该用〈查封〉。拘留的对象是人，饭店等场所要用查封。"}, {"text": "老师让他拘留了一节课。", "explanation": "这里应该用〈罚站〉。拘留是公安机关依法执行的措施，学校老师的处罚不能用拘留。"}, {"text": "他因为违纪被学校拘留一周。", "explanation": "这里应该用〈禁足〉。拘留是公安机关依法执行的措施，学校的处罚要用禁足。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公安机关依法拘留得那名醉酒驾驶者十天。", "corrected_sentence": "公安机关依法拘留了那名醉酒驾驶者十天。", "error_description": "表示拘留时长的“十天”前应用“了”表示完成，不能用“得”。“拘留得那名醉酒驾驶者十天”是错误形式，应为“拘留了那名醉酒驾驶者十天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警方没有依法拘留了那名肇事司机。", "corrected_sentence": "警方没有依法拘留那名肇事司机。", "error_description": "用“没有”否定“拘留”时，动词后不能再加“了”。应去掉“了”，说成“没有依法拘留那名肇事司机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a281980-0060-4ce7-a5a5-384856b654c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
