INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93173, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拖是拉着东西在地上走。", "primary_collocate": null, "pronunciation": "tuō", "ipa": "tʰuɔ˥", "syllable_count": 1, "sentences": [{"text": "他拖着箱子走进门。", "target_word": "拖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子太重了，我拖不动。", "target_word": "拖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拖着行李箱走进了车站。", "target_word": "拖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗拖着我的鞋跑到了院子里。", "target_word": "拖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把大树拖到了河边。", "target_word": "拖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子累了，拖着书包慢慢走。", "target_word": "拖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拖了一把椅子，坐在我旁边。", "target_word": "拖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这头牛能拖很重的车。", "target_word": "拖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别在地上拖，会把裤子弄脏的。", "target_word": "拖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起把受伤的小船拖上了岸。", "target_word": "拖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拖了", "label": "体标"}, {"form": "拖着", "label": "体标"}, {"form": "拖走", "label": "复合"}], "register": "中性", "sense_fingerprint": "拖：用力拉着东西，使它贴着地面移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93173, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拖", "is_correct": true, "explanation": "正确：拖（tuō）指拉着东西在地面上移动，这里是本义。"}, {"text": "驼", "is_correct": false, "explanation": "tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。"}, {"text": "妥", "is_correct": false, "explanation": "tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。"}, {"text": "唾", "is_correct": false, "explanation": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。"}], "explanations": {"拖": "正确：拖（tuō）指拉着东西在地面上移动，这里是本义。", "驼": "tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。", "妥": "tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。", "唾": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。"}, "sentence_index": null, "correct_answer": "拖"}, "level_3": {"options": [{"text": "拖", "is_correct": true, "explanation": "正确：“他拖着箱子走进门”表示拉着箱子贴地移动，“拖”是本义。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只与饮食类宾语搭配，不说“吃箱子”。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”指戴在头上或身上，不能用来处理箱子。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与搬运箱子的动作无关。"}], "explanations": {"拖": "正确：“他拖着箱子走进门”表示拉着箱子贴地移动，“拖”是本义。", "吃": "搭配：“吃”只与饮食类宾语搭配，不说“吃箱子”。", "戴": "搭配：“戴”指戴在头上或身上，不能用来处理箱子。", "唱": "语义：“唱”指发声演唱，与搬运箱子的动作无关。"}, "sentence_index": 0, "correct_answer": "拖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拖上帽子，走出了家门。", "explanation": "这里应该用〈戴〉。拖表示拉着东西在地上移动，不能用来表示把帽子戴在头上。"}, {"text": "他把外套拖在门后，忘了拿走。", "explanation": "这里应该用〈挂〉。“拖”表示拉着东西在地面移动，外套挂在门后要说“挂”。"}, {"text": "他拖起手来，回答了老师的问题。", "explanation": "这里应该用〈举〉。“拖”指拉动物体移动，举手要说“举”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93173, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拖", "is_correct": true, "explanation": "正确：拖（tuō）指拉着东西在地面上移动，这里是本义。"}, {"text": "多", "is_correct": false, "explanation": "duō 与 tuō 声母不同（d 与 t），意思是多少。"}, {"text": "驮", "is_correct": false, "explanation": "tuó（第二声）与 tuō（第一声）声调不同，意思是用背承载。"}, {"text": "推", "is_correct": false, "explanation": "tuī 与 tuō 韵母不同（i 与 o），意思是推动。"}, {"text": "唾", "is_correct": false, "explanation": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。"}], "explanations": {"拖": "正确：拖（tuō）指拉着东西在地面上移动，这里是本义。", "多": "duō 与 tuō 声母不同（d 与 t），意思是多少。", "驮": "tuó（第二声）与 tuō（第一声）声调不同，意思是用背承载。", "推": "tuī 与 tuō 韵母不同（i 与 o），意思是推动。", "唾": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。"}, "sentence_index": null, "correct_answer": "拖"}, "level_3": {"options": [{"text": "拖", "is_correct": true, "explanation": "正确：“他拖了一把椅子”表示拉着椅子过来，“拖”是本义。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”指咀嚼食物，与搬动椅子的动作不合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”要搭配衣物等宾语，不能说“穿了一把椅子”。"}, {"text": "梳", "is_correct": false, "explanation": "语义：“梳”指用梳子整理头发，与搬动椅子无关。"}], "explanations": {"拖": "正确：“他拖了一把椅子”表示拉着椅子过来，“拖”是本义。", "嚼": "语义：“嚼”指咀嚼食物，与搬动椅子的动作不合。", "穿": "搭配：“穿”要搭配衣物等宾语，不能说“穿了一把椅子”。", "梳": "语义：“梳”指用梳子整理头发，与搬动椅子无关。"}, "sentence_index": 6, "correct_answer": "拖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把脏衣服拖干净了，晾在阳台上。", "explanation": "这里应该用〈洗〉。“拖”表示拉动，不能用来表示清洗衣服。"}, {"text": "他一口气拖了半杯水。", "explanation": "这里应该用〈喝〉。“拖”表示拉着东西移动，不能用来表示喝水。"}, {"text": "她拖了一封长长的信。", "explanation": "这里应该用〈写〉。“拖”表示拉动，不能用来表示写信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拖得行李箱走进了房间。", "corrected_sentence": "他拖着行李箱走进了房间。", "error_description": "错误：“拖得行李箱”，持续态“着”误写成“得”，“得”后不能直接接宾语。正确：“拖着行李箱”，“拖”与“着”直接相连，表示拉着东西的状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把箱子拖了进仓库。", "corrected_sentence": "工人把箱子拖进了仓库。", "error_description": "错误：“拖了进仓库”，“了”放在了趋向补语“进”前。正确：“拖进了仓库”，“了”要放在趋向补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
