INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93174, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93174, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拖是把事情推迟、不及时去做。", "primary_collocate": null, "pronunciation": "tuō", "ipa": "tʰuɔ˥", "syllable_count": 1, "sentences": [{"text": "今天的事别拖到明天。", "target_word": "拖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事不能再拖了。", "target_word": "拖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是拖到最后一天才交作业。", "target_word": "拖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的病不能拖，快去医院吧。", "target_word": "拖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议拖了两个小时，大家都很累。", "target_word": "拖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直拖着报告没写，老板很生气。", "target_word": "拖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不想上学，就一直拖着不起床。", "target_word": "拖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事他一拖就是半年。", "target_word": "拖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的婚事拖了很多年。", "target_word": "拖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱不够，他只好把付款拖到下个月。", "target_word": "拖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拖了", "label": "体标"}, {"form": "拖着", "label": "体标"}, {"form": "拖拖拉拉", "label": "重叠"}, {"form": "拖延", "label": "复合"}], "register": "中性", "sense_fingerprint": "拖：把事情推迟、不及时处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c5916a-9e2c-4e57-852e-1ec8e059930b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93174, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拖", "is_correct": true, "explanation": "正确：拖（tuō）指拉动，也指拖延，这里是“拖延”义。"}, {"text": "驼", "is_correct": false, "explanation": "tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。"}, {"text": "妥", "is_correct": false, "explanation": "tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。"}, {"text": "推", "is_correct": false, "explanation": "tuī 与 tuō 韵母不同（i 与 o），意思是推动。"}], "explanations": {"拖": "正确：拖（tuō）指拉动，也指拖延，这里是“拖延”义。", "驼": "tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。", "妥": "tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。", "推": "tuī 与 tuō 韵母不同（i 与 o），意思是推动。"}, "sentence_index": null, "correct_answer": "拖"}, "level_3": {"options": [{"text": "拖", "is_correct": true, "explanation": "正确：“别拖到明天”表示推迟，“拖”正是本词的拖延义。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”表示递交或送行，不能表示把事情推迟。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只与饮食类宾语搭配，不说“今天的事吃到明天”。"}, {"text": "叠", "is_correct": false, "explanation": "语义：“叠”指折叠，与推迟事情的意思无关。"}], "explanations": {"拖": "正确：“别拖到明天”表示推迟，“拖”正是本词的拖延义。", "送": "语义：“送”表示递交或送行，不能表示把事情推迟。", "吃": "搭配：“吃”只与饮食类宾语搭配，不说“今天的事吃到明天”。", "叠": "语义：“叠”指折叠，与推迟事情的意思无关。"}, "sentence_index": 0, "correct_answer": "拖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拖着一杯咖啡走进了办公室。", "explanation": "这里应该用〈端〉。“拖”指拉着东西在地面移动，杯子只能端着，不能拖着走。"}, {"text": "那次他拖了我一把，帮我渡过了难关。", "explanation": "这里应该用〈拉〉。“拖”不表示搀扶或帮助，帮人一把要说“拉一把”。"}, {"text": "这个项目需要拖进，才能有新的进展。", "explanation": "这里应该用〈推进〉。拖只表示拉动或拖延，不能表示推动工作的进展。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93174, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拖", "is_correct": true, "explanation": "正确：拖（tuō）指拖延，这里是“拖延”义。"}, {"text": "多", "is_correct": false, "explanation": "duō 与 tuō 声母不同（d 与 t），意思是多少。"}, {"text": "驮", "is_correct": false, "explanation": "tuó（第二声）与 tuō（第一声）声调不同，意思是用背承载。"}, {"text": "唾", "is_correct": false, "explanation": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。"}], "explanations": {"拖": "正确：拖（tuō）指拖延，这里是“拖延”义。", "多": "duō 与 tuō 声母不同（d 与 t），意思是多少。", "驮": "tuó（第二声）与 tuō（第一声）声调不同，意思是用背承载。", "唾": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。"}, "sentence_index": null, "correct_answer": "拖"}, "level_3": {"options": [{"text": "拖", "is_correct": true, "explanation": "正确：“就一直拖着不起床”表示孩子拖延、懒得起床，“拖”是本词的拖延义。"}, {"text": "拉", "is_correct": false, "explanation": "配价：“拉”需要带宾语（拉某物），“一直拉着不起床”缺少宾语。"}, {"text": "扛", "is_correct": false, "explanation": "语义：“扛”指用肩承担重物，与孩子不起床的语境不合。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”要带“毛衣”等宾语，“织着不起床”不通。"}], "explanations": {"拖": "正确：“就一直拖着不起床”表示孩子拖延、懒得起床，“拖”是本词的拖延义。", "拉": "配价：“拉”需要带宾语（拉某物），“一直拉着不起床”缺少宾语。", "扛": "语义：“扛”指用肩承担重物，与孩子不起床的语境不合。", "织": "搭配：“织”要带“毛衣”等宾语，“织着不起床”不通。"}, "sentence_index": 6, "correct_answer": "拖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要拖紧时间，尽快完成任务。", "explanation": "这里应该用〈抓紧〉。“拖”不能与“紧”搭配表示抓紧时间。"}, {"text": "这件事必须拖快进度，不能再慢下去了。", "explanation": "这里应该用〈加快〉。“拖”表示拖延，不能表示加快进度。"}, {"text": "他很快拖完了作业，老师很满意。", "explanation": "这里应该用〈完成〉。“拖”表示拖延或拉动，不能表示做完作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不能再拖下去过。", "corrected_sentence": "我们不能再拖下去了。", "error_description": "错误：“拖下去过”，句末误用了表示经历的“过”。正确：“拖下去了”，句末“了”表示情况的变化，“不能再……了”是固定格式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告我已经拖三天，不能再拖了。", "corrected_sentence": "这份报告我已经拖了三天，不能再拖了。", "error_description": "错误：“已经拖三天”，漏掉了完成态“了”。正确：“已经拖了三天”，“已经”后表示已完成的动作要带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20b97f2d-618d-466b-8b39-6f87f32bcafa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
