INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93175, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指挥官是带着大家打仗，发命令的人。", "primary_collocate": null, "pronunciation": "zhǐ huī guān", "ipa": "ʈʂɻ̩˨˩ xweɪ˥ kwan˥", "syllable_count": 3, "sentences": [{"text": "指挥官站在山上，看着前面的路。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官对大家说：“天亮就走。”", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位指挥官很年轻。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官发了命令，士兵都动了。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都听指挥官的话。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们的指挥官。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官带着大家过了河。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的指挥官很勇敢。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官把地图放在桌子上。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是这个队的指挥官？", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "指揮官", "label": "繁体"}], "register": "中性", "sense_fingerprint": "带领大家打仗并发出命令的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93175, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指挥官", "is_correct": true, "explanation": "正确：指挥官是带兵打仗、能站在山上看路的人，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「看着前面的路」要求能看的主语，石头不能作主语。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不会站在山上看着前面的路。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户固定在墙上，不能站在山上。"}], "explanations": {"指挥官": "正确：指挥官是带兵打仗、能站在山上看路的人，符合句意。", "石头": "搭配：「看着前面的路」要求能看的主语，石头不能作主语。", "鱼": "语义：鱼不会站在山上看着前面的路。", "窗户": "语义：窗户固定在墙上，不能站在山上。"}, "sentence_index": 0, "correct_answer": "指挥官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位指挥官每天在学校给学生上课。", "explanation": "这里应该用〈老师〉。在学校给学生上课的是老师，指挥官是带兵打仗、发命令的人。"}, {"text": "这位指挥官每天给客人剪头发。", "explanation": "这里应该用〈理发师〉。给客人剪头发的是理发师，指挥官是带兵打仗、发命令的人。"}, {"text": "这位指挥官每天在法院审理案件。", "explanation": "这里应该用〈法官〉。审理案件的是法官，指挥官是带兵打仗、发命令的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93175, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指挥官", "is_correct": true, "explanation": "正确：指挥官能带着大家过河，符合句意。"}, {"text": "风", "is_correct": false, "explanation": "语义：风不会带领大家过河。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯不会带领大家过河。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不会带领大家过河。"}], "explanations": {"指挥官": "正确：指挥官能带着大家过河，符合句意。", "风": "语义：风不会带领大家过河。", "电灯": "语义：电灯不会带领大家过河。", "花": "语义：花不会带领大家过河。"}, "sentence_index": 6, "correct_answer": "指挥官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位指挥官每天带运动员训练。", "explanation": "这里应该用〈教练〉。指挥官指带兵打仗的军官，带运动员训练的是教练。"}, {"text": "这位指挥官每天在厨房做饭。", "explanation": "这里应该用〈厨师〉。指挥官指带兵打仗的军官，在厨房做饭的应说厨师。"}, {"text": "这位指挥官每天给病人看病。", "explanation": "这里应该用〈医生〉。指挥官指带兵打仗的军官，给病人看病的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只指挥官昨天到了前线。", "corrected_sentence": "这位指挥官昨天到了前线。", "error_description": "量词错误：“指挥官”指人，应说“这位指挥官”；“这只”只用于动物，不能用来指人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位的指挥官明天要去前线。", "corrected_sentence": "这位指挥官明天要去前线。", "error_description": "助词错误：“这位”直接修饰名词，中间不能加“的”，应说“这位指挥官”，不能说“这位的指挥官”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
