INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "统率并指挥部队或行动的军官。", "primary_collocate": null, "pronunciation": "zhǐ huī guān", "ipa": "ʈʂɻ̩˨˩ xweɪ˥ kwan˥", "syllable_count": 3, "sentences": [{"text": "这位指挥官统率着三千名士兵。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争开始后，指挥官换了人。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官在会议上说明了行动计划。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了十年指挥官。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次救援行动的指挥官是一位女军官。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官要对整个行动负责。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官下令部队明天出发。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老指挥官回忆起过去的战争。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的指挥官很快熟悉了部队。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥官看过地图，决定改变路线。", "target_word": "指挥官", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "指揮官", "label": "繁体"}], "register": "中性", "sense_fingerprint": "统率部队或指挥行动的军官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f060a69f-69e7-47d9-8874-2983faa2fc88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指挥官", "is_correct": true, "explanation": "正确：指挥官统率部队，“统率着三千名士兵”符合句意。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机不会统率三千名士兵。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不会统率军队，句子说不通。"}, {"text": "园丁", "is_correct": false, "explanation": "搭配：「统率」的主语应是指挥部队的人，园丁不能与之搭配。"}], "explanations": {"指挥官": "正确：指挥官统率部队，“统率着三千名士兵”符合句意。", "司机": "语义：司机不会统率三千名士兵。", "厨师": "语义：厨师不会统率军队，句子说不通。", "园丁": "搭配：「统率」的主语应是指挥部队的人，园丁不能与之搭配。"}, "sentence_index": 0, "correct_answer": "指挥官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位指挥官每天开出租车送客人。", "explanation": "这里应该用〈司机〉。开出租车送客人的是司机，指挥官是统率部队、指挥行动的军官。"}, {"text": "这位指挥官每天在厨房炒菜。", "explanation": "这里应该用〈厨师〉。在厨房炒菜的是厨师，指挥官是统率部队、指挥行动的军官。"}, {"text": "这位指挥官每天在超市收钱。", "explanation": "这里应该用〈收银员〉。在超市收钱的是收银员，指挥官是统率部队、指挥行动的军官。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指挥官", "is_correct": true, "explanation": "正确：指挥官有权下令，“下令部队明天出发”符合句意。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟不能下令让部队出发。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能发出命令。"}, {"text": "命令", "is_correct": false, "explanation": "搭配：「下令」的主语应是有权的人，“命令”本身不能下令。"}], "explanations": {"指挥官": "正确：指挥官有权下令，“下令部队明天出发”符合句意。", "小鸟": "语义：小鸟不能下令让部队出发。", "河流": "语义：河流不能发出命令。", "命令": "搭配：「下令」的主语应是有权的人，“命令”本身不能下令。"}, "sentence_index": 6, "correct_answer": "指挥官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位指挥官每天给病人换药。", "explanation": "这里应该用〈护士〉。给病人换药的是护士，指挥官指统率部队的军官。"}, {"text": "这位指挥官每天在街边修鞋。", "explanation": "这里应该用〈修鞋匠〉。在街边修鞋的是修鞋匠，指挥官是统率部队、指挥行动的军官。"}, {"text": "这位指挥官每天在店里做衣服。", "explanation": "这里应该用〈裁缝〉。在店里做衣服的是裁缝，指挥官是统率部队、指挥行动的军官。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台指挥官昨晚召开了紧急会议。", "corrected_sentence": "这位指挥官昨晚召开了紧急会议。", "error_description": "量词错误：“指挥官”指人，应说“这位指挥官”；“台”用于机器，不能用来指人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位的指挥官刚刚下了命令。", "corrected_sentence": "这位指挥官刚刚下了命令。", "error_description": "助词错误：“这位”直接修饰名词，中间不能加“的”，应说“这位指挥官”，不能说“这位的指挥官”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '067c409c-b6f7-4385-a2f9-80d786dcd589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
