INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指控是说某个人做了坏事。", "primary_collocate": null, "pronunciation": "zhǐ kòng", "ipa": "ʈʂɨ˨˩˦ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "邻居指控他偷了自行车。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明指控同学偷了他的钱包。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她指控老板每天让工人加班到半夜。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有指控过别人。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女人指控司机撞了她的车。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你凭什么指控我？", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们指控这家店卖假药。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人指控那个年轻人骗了他的钱。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客指控这家饭店用了坏肉。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有证据，你不能随便指控别人。", "target_word": "指控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指控了", "label": "体标"}, {"form": "指控过", "label": "体标"}], "register": "中性", "sense_fingerprint": "指控：说某人做了坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59bfadb7-bca0-4e03-be83-d192fc022fe2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指控", "is_correct": true, "explanation": "正确：指控即说某人做了坏事，邻居说他偷了自行车，符合句意。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：夸奖是称赞好的行为，与“偷了自行车”矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：感谢针对别人的帮助或好意，不能用于偷窃行为。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”后要接损失或款项，不能接“他偷了自行车”。"}], "explanations": {"指控": "正确：指控即说某人做了坏事，邻居说他偷了自行车，符合句意。", "夸奖": "语义：夸奖是称赞好的行为，与“偷了自行车”矛盾。", "感谢": "语义：感谢针对别人的帮助或好意，不能用于偷窃行为。", "赔偿": "搭配：“赔偿”后要接损失或款项，不能接“他偷了自行车”。"}, "sentence_index": 0, "correct_answer": "指控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是指控别人不努力。", "explanation": "这里应该用〈指责〉。指控多指说某人做了坏事或犯罪，不努力还不到需要指控的程度。"}, {"text": "老师指控他上课讲话。", "explanation": "这里应该用〈批评〉。指控带有“说某人犯了严重错误”的分量，上课讲话只需批评。"}, {"text": "妈妈指控邻居太吵。", "explanation": "这里应该用〈抱怨〉。指控要说出对方做了坏事，邻居太吵只是不满，应说抱怨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee97845d-99ce-4754-8946-e27181ae5554') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
